INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "服などを身に着ける。また、色や雰囲気などを帯びる。", "primary_collocate": null, "pronunciation": "まとう", "ipa": "matoɯ", "syllable_count": 3, "sentences": [{"text": "さあ、この退廃的な美しさを纏い、冷徹な街路へ歩み出そうではないか。", "target_word": "纏い", "complexity_tier": "T3", "furigana": "たいはいてき うつく まと れいてつ がいろ あゆ だ", "sentence_source": "mined"}, {"text": "それはまさに、自然の営みと時間が凝縮したかような深紅を纏うリンゴであった。", "target_word": "纏う", "complexity_tier": "T3", "furigana": "しぜん いとな じかん ぎょうしゅく しんく まと", "sentence_source": "mined"}, {"text": "数日かけて培養されたルヴァン種は、独特の酸味と芳醇な香りを纏い、パンの骨格を形成する。", "target_word": "纏い", "complexity_tier": "T3", "furigana": "すうじつ ばいよう だね どくとく さんみ ほうじゅん かお まと こっかく けいせい", "sentence_source": "mined"}, {"text": "最終段階のベーキングでは、高温の蒸気と共に膨張した生地が、黄金色の硬質で脆いクラストを纏い、内部は瑞々しくも弾力に富んだクラムへと昇華する。", "target_word": "纏い", "complexity_tier": "T3", "furigana": "さいしゅう だんかい こうおん じょうき とも ぼうちょう きじ こがねいろ こうしつ もろ まと ないぶ みずみず だんりょく と しょうか", "sentence_source": "mined"}, {"text": "彼女は白いドレスを纏っていた。", "target_word": "纏っ", "complexity_tier": "T3", "furigana": "かのじょ しろ まと", "sentence_source": "generated"}, {"text": "王は赤いマントを纏って現れた。", "target_word": "纏っ", "complexity_tier": "T3", "furigana": "おう あか まと あらわ", "sentence_source": "generated"}, {"text": "彼は不思議な空気を纏う人だ。", "target_word": "纏う", "complexity_tier": "T3", "furigana": "かれ ふしぎ くうき まと ひと", "sentence_source": "generated"}, {"text": "山は朝の霧を纏っている。", "target_word": "纏っ", "complexity_tier": "T3", "furigana": "やま あさ きり まと", "sentence_source": "generated"}, {"text": "緊張感を纏った会場に入った。", "target_word": "纏っ", "complexity_tier": "T3", "furigana": "きんちょうかん まと かいじょう はい", "sentence_source": "generated"}, {"text": "春の花は甘い香りを纏う。", "target_word": "纏う", "complexity_tier": "T3", "furigana": "はる はな あま かお まと", "sentence_source": "generated"}], "morphological_forms": [{"form": "纏った", "label": "活用"}, {"form": "纏って", "label": "活用"}, {"form": "纏わない", "label": "活用"}, {"form": "纏える", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 衣服や雰囲気を身に帯びる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52272, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "表には出ていないが、内に隠れていること。", "primary_collocate": null, "pronunciation": "せんざい", "ipa": "seɴzai", "syllable_count": 4, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "びせいぶつ たいしゃ さよう はっこう たん ほぞん ぎほう いき こ しゅしょく も せんざい のうりょく ひやくてき かくちょう かがくてき げいじゅつ", "sentence_source": "mined"}, {"text": "彼には潜在的な才能がある。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "かれ せんざいてき さいのう", "sentence_source": "generated"}, {"text": "その問題は社会に潜在している。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "もんだい しゃかい せんざい", "sentence_source": "generated"}, {"text": "潜在する危険に気づくべきだ。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "せんざい きけん き", "sentence_source": "generated"}, {"text": "才能が潜在している子どもも多い。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "さいのう せんざい こ おお", "sentence_source": "generated"}, {"text": "潜在的な客を探している。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "せんざいてき きゃく さが", "sentence_source": "generated"}, {"text": "不安は心の奥に潜在していた。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "ふあん こころ おく せんざい", "sentence_source": "generated"}, {"text": "この町には潜在的な魅力が多い。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "まち せんざいてき みりょく おお", "sentence_source": "generated"}, {"text": "人の心には多くの思いが潜在する。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "ひと こころ おお おも せんざい", "sentence_source": "generated"}, {"text": "潜在的な需要を調べる。", "target_word": "潜在", "complexity_tier": "T3", "furigana": "せんざいてき じゅよう しら", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜在的", "label": "派生"}, {"form": "潜在能力", "label": "派生"}, {"form": "潜在意識", "label": "派生"}, {"form": "潜在する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 表に出ず内部に隠れていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36155, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を考えるときの、正しい筋道。考えのつながり方。", "primary_collocate": null, "pronunciation": "ろんり", "ipa": "ɾoɴɾi", "syllable_count": 3, "sentences": [{"text": "真実を解き明かすための静謐かつ論理的なプロセス、それこそが指紋分析の真髄と言えよう。", "target_word": "論理", "complexity_tier": "T3", "furigana": "しんじつ と あ せいひつ ろんりてき しもん ぶんせき しんずい い", "sentence_source": "mined"}, {"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "論理", "complexity_tier": "T3", "furigana": "のち しんけいけい こうちく ちゅうしょうてき ろんり ぶつりてき きょどう げんみつ どうき", "sentence_source": "mined"}, {"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "論理", "complexity_tier": "T3", "furigana": "ちょっかん たよ けいさん ろんり きのうてき どくそうてき とし くうかん そうしゅつ めざ", "sentence_source": "mined"}, {"text": "彼の話には論理がない。", "target_word": "論理", "complexity_tier": "T3", "furigana": "かれ はなし ろんり", "sentence_source": "generated"}, {"text": "論理的に考えることが大切だ。", "target_word": "論理", "complexity_tier": "T3", "furigana": "ろんりてき かんが たいせつ", "sentence_source": "generated"}, {"text": "その論理はおかしいと思う。", "target_word": "論理", "complexity_tier": "T3", "furigana": "ろんり おも", "sentence_source": "generated"}, {"text": "数学で論理の力を育てる。", "target_word": "論理", "complexity_tier": "T3", "furigana": "すうがく ろんり ちから そだ", "sentence_source": "generated"}, {"text": "彼女は論理的に説明できる。", "target_word": "論理", "complexity_tier": "T3", "furigana": "かのじょ ろんりてき せつめい", "sentence_source": "generated"}, {"text": "論理を使って相手を説得した。", "target_word": "論理", "complexity_tier": "T3", "furigana": "ろんり つか あいて せっとく", "sentence_source": "generated"}, {"text": "感情より論理を大事にする人だ。", "target_word": "論理", "complexity_tier": "T3", "furigana": "かんじょう ろんり だいじ ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "論理的", "label": "派生"}, {"form": "論理学", "label": "派生"}, {"form": "論理性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 正しい思考の筋道や法則", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37633, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある事を実際にする。", "primary_collocate": null, "pronunciation": "おこなう", "ipa": "okonaɯ", "syllable_count": 4, "sentences": [{"text": "鶏の飼育は、温度や餌が厳密に調整された環境で行われます。", "target_word": "行わ", "complexity_tier": "T3", "furigana": "にわとり しいく おんど えさ げんみつ ちょうせい かんきょう おこな", "sentence_source": "mined"}, {"text": "また、限られた環境で効率的に生産を行う「資源管理」の観点からも、持続可能な食料供給の実現において重要な役割を果たしています。", "target_word": "行う", "complexity_tier": "T3", "furigana": "かぎ かんきょう こうりつてき せいさん おこな しげん かんり かんてん じぞく かのう しょくりょう きょうきゅう じつげん じゅうよう やくわり は", "sentence_source": "mined"}, {"text": "学校で避難訓練を行う。", "target_word": "行う", "complexity_tier": "T3", "furigana": "がっこう ひなん くんれん おこな", "sentence_source": "generated"}, {"text": "明日、テストが行われる。", "target_word": "行わ", "complexity_tier": "T3", "furigana": "あした おこな", "sentence_source": "generated"}, {"text": "毎朝、体操を行っている。", "target_word": "行っ", "complexity_tier": "T3", "furigana": "まいあさ たいそう おこな", "sentence_source": "generated"}, {"text": "会議は三階で行います。", "target_word": "行い", "complexity_tier": "T3", "furigana": "かいぎ さんがい おこな", "sentence_source": "generated"}, {"text": "祭りは毎年夏に行われる。", "target_word": "行わ", "complexity_tier": "T3", "furigana": "まつ まいとし なつ おこな", "sentence_source": "generated"}, {"text": "調査を行った結果を発表した。", "target_word": "行っ", "complexity_tier": "T3", "furigana": "ちょうさ おこな けっか はっぴょう", "sentence_source": "generated"}, {"text": "みんなで掃除を行いましょう。", "target_word": "行い", "complexity_tier": "T3", "furigana": "そうじ おこな", "sentence_source": "generated"}, {"text": "生徒が行う実験を見学した。", "target_word": "行う", "complexity_tier": "T3", "furigana": "せいと おこな じっけん けんがく", "sentence_source": "generated"}], "morphological_forms": [{"form": "行った", "label": "活用"}, {"form": "行って", "label": "活用"}, {"form": "行われる", "label": "活用"}, {"form": "行い", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 物事を実際にする・実施する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39369, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "技術や製品、サービスなどに新しい考えを導入し、大きく変えることです。", "primary_collocate": null, "pronunciation": "いのべーしょん", "ipa": "inobeːɕoɴ", "syllable_count": 6, "sentences": [{"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "たん しゅっし けいえいせんりゃく ていきょう しじょう あら かち う かそく", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "むすう しゅたい かぎ じょうほう もと た てきおう く かえ かてい いと とっぱつてき けんげん ほか", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "ふかくじつせい たか ぎじゅつてき かだい いど きぎょうか たい きょうきゅう かれ しじょう しっぱい ほかん はかいてき ほうが はぐく", "sentence_source": "mined"}, {"text": "この会社はイノベーションを大切にしている。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "かいしゃ たいせつ", "sentence_source": "generated"}, {"text": "スマホは大きなイノベーションだった。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "おお", "sentence_source": "generated"}, {"text": "イノベーションが町の生活を変えた。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "まち せいかつ か", "sentence_source": "generated"}, {"text": "若い人たちがイノベーションを起こしている。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "わか ひと お", "sentence_source": "generated"}, {"text": "イノベーションのおかげで仕事が楽になった。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "しごと らく", "sentence_source": "generated"}, {"text": "先生はイノベーションの大切さを話した。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "せんせい たいせつ はな", "sentence_source": "generated"}, {"text": "新しいイノベーションに期待している。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "あたら きたい", "sentence_source": "generated"}], "morphological_forms": [{"form": "イノベーター", "label": "派生"}, {"form": "技術イノベーション", "label": "派生"}, {"form": "オープンイノベーション", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 新しい考えで技術や製品を大きく変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目に見えないものや抽象的なものが、ある場所の中に存在する。特に、神や霊、生命、感情、能力などが内側に備わっていることを表す。", "primary_collocate": null, "pronunciation": "やどる", "ipa": "jadoɾɯ", "syllable_count": 3, "sentences": [{"text": "社会経済現象の真の駆動力は、還元主義的な分析の彼方、ネットワーク全体の創発的特性の内にこそ宿っていると言えよう。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "しゃかいけいざいげんしょう しん くどうりょく かんげんしゅぎてき ぶんせき かなた ぜんたい そうはつてき とくせい うち やど い", "sentence_source": "mined"}, {"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "すがた ぎょうし こども ひとみ せいめい も こんげんてき たくま いけい ねん やど", "sentence_source": "mined"}, {"text": "単なるパンを焼き上げるという行為の域を超え、そこには古の製法への畏敬の念と、素材の潜在能力を限界まで引き出そうとする職人としての揺るぎない覚悟が、静かに宿っていたのである。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "たん や あ こうい いき こ いにしえ せいほう いけい ねん そざい せんざいのうりょく げんかい ひ だ しょくにん ゆ かくご しず やど", "sentence_source": "mined"}, {"text": "この木には神様が宿ると言われている。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "き かみさま やど い", "sentence_source": "generated"}, {"text": "彼女の目に強い決意が宿った。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "かのじょ め つよ けつい やど", "sentence_source": "generated"}, {"text": "古い人形には心が宿るという話がある。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "ふる にんぎょう こころ やど はなし", "sentence_source": "generated"}, {"text": "小さな体に大きな力が宿っている。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "ちい からだ おお ちから やど", "sentence_source": "generated"}, {"text": "言葉には魂が宿ると祖母は言った。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "ことば たましい やど そぼ い", "sentence_source": "generated"}, {"text": "その絵には画家の思いが宿っている。", "target_word": "宿っ", "complexity_tier": "T3", "furigana": "え がか おも やど", "sentence_source": "generated"}, {"text": "命の宿る種を大切に植えた。", "target_word": "宿る", "complexity_tier": "T3", "furigana": "いのち やど たね たいせつ う", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿った", "label": "活用"}, {"form": "宿って", "label": "活用"}, {"form": "宿らない", "label": "活用"}, {"form": "宿り", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 見えないものが内側に存在する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品やサービスを購入したり利用したりして、なくしていくこと。経済活動の一環として、生産されたものが人々に使われること。", "primary_collocate": null, "pronunciation": "しょうひ", "ipa": "ɕoːçi", "syllable_count": 3, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "消費", "complexity_tier": "T3", "furigana": "さんぎょうかくめい いこう きゅうげき にんげんかつどう かせきねんりょう たいりょう しょうひ しんりん はかい じゅんかん しんこく はたん", "sentence_source": "mined"}, {"text": "企業はこれらの色彩が持つ記号的意味を深く理解し、自社のアイデンティティを消費者の心に効果的に植え付けようとしている。", "target_word": "消費", "complexity_tier": "T3", "furigana": "きぎょう しきさい も きごうてき いみ ふか りかい じしゃ しょうひしゃ こころ こうかてき う つ", "sentence_source": "mined"}, {"text": "夏は電気の消費が増える。", "target_word": "消費", "complexity_tier": "T3", "furigana": "なつ でんき しょうひ ふ", "sentence_source": "generated"}, {"text": "水の消費を少し減らそう。", "target_word": "消費", "complexity_tier": "T3", "furigana": "みず しょうひ すこ へ", "sentence_source": "generated"}, {"text": "この車はガソリンを多く消費する。", "target_word": "消費", "complexity_tier": "T3", "furigana": "くるま おお しょうひ", "sentence_source": "generated"}, {"text": "消費が増えると、町が元気になる。", "target_word": "消費", "complexity_tier": "T3", "furigana": "しょうひ ふ まち げんき", "sentence_source": "generated"}, {"text": "米の消費量が年々減っている。", "target_word": "消費", "complexity_tier": "T3", "furigana": "こめ しょうひりょう ねんねん へ", "sentence_source": "generated"}, {"text": "運動するとエネルギーを消費できる。", "target_word": "消費", "complexity_tier": "T3", "furigana": "うんどう しょうひ", "sentence_source": "generated"}, {"text": "家庭の消費について調べた。", "target_word": "消費", "complexity_tier": "T3", "furigana": "かてい しょうひ しら", "sentence_source": "generated"}, {"text": "紙の消費をおさえる工夫をしている。", "target_word": "消費", "complexity_tier": "T3", "furigana": "かみ しょうひ くふう", "sentence_source": "generated"}], "morphological_forms": [{"form": "消費する", "label": "派生"}, {"form": "消費者", "label": "派生"}, {"form": "消費税", "label": "派生"}, {"form": "消費量", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物やサービスを使ってなくすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: おさえる (Zipf 2.47)']::text[], '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38989, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "過去のある時点において、以前はという意味の副詞。", "primary_collocate": null, "pronunciation": "かつて", "ipa": "kat͡sɯte", "syllable_count": 3, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "あんてい せいたいけい げんだいぶんめい けいざいかつどう ゆが しゅうふく きわ こんなん きょくめん むか", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな冷徹さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "かそうくうかんじょう こうちく せいせいぶつ した や きょうじ か か ぬく れいてつ あいだ た ま きんちょうかんけい み と そうぞうせい ほんしつ と", "sentence_source": "mined"}, {"text": "森の奥深くに佇む、その赤いドアの小さな家は、かつて祖母が一人で暮らしていた場所だ。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "もり おくふか たたず あか ちい いえ そぼ ひとり く ばしょ", "sentence_source": "mined"}, {"text": "ここはかつて小さな村だった。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "ちい むら", "sentence_source": "generated"}, {"text": "かつての友人に駅で会った。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "ゆうじん えき あ", "sentence_source": "generated"}, {"text": "父はかつて野球の選手だった。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "ちち やきゅう せんしゅ", "sentence_source": "generated"}, {"text": "かつては川で泳ぐ子が多かった。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "かわ およ こ おお", "sentence_source": "generated"}, {"text": "かつての町の写真を見つけた。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "まち しゃしん み", "sentence_source": "generated"}, {"text": "この店はかつて本屋だった。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "みせ ほんや", "sentence_source": "generated"}, {"text": "かつて住んでいた家を訪ねた。", "target_word": "かつて", "complexity_tier": "T3", "furigana": "す いえ たず", "sentence_source": "generated"}], "morphological_forms": [{"form": "かつての", "label": "派生"}, {"form": "かつては", "label": "派生"}, {"form": "いまだかつて", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | 過去のある時に、以前は", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37687, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "ある動作や出来事が行われる時点や場面を表す。", "primary_collocate": null, "pronunciation": "さい", "ipa": "sai", "syllable_count": 2, "sentences": [{"text": "そこで、デザインを決める際、子供が自由に描いた絵を参考にすることにした。", "target_word": "際", "complexity_tier": "T3", "furigana": "き さい こども じゆう か え さんこう", "sentence_source": "mined"}, {"text": "お帰りの際は、忘れ物に注意してください。", "target_word": "際", "complexity_tier": "T3", "furigana": "かえ さい わす もの ちゅうい", "sentence_source": "generated"}, {"text": "入館の際に名前を書いてください。", "target_word": "際", "complexity_tier": "T3", "furigana": "にゅうかん さい なまえ か", "sentence_source": "generated"}, {"text": "地震の際は机の下に入る。", "target_word": "際", "complexity_tier": "T3", "furigana": "じしん さい つくえ した はい", "sentence_source": "generated"}, {"text": "駅に着いた際、母に電話した。", "target_word": "際", "complexity_tier": "T3", "furigana": "えき つ さい はは でんわ", "sentence_source": "generated"}, {"text": "この際、部屋をきれいに片づけよう。", "target_word": "際", "complexity_tier": "T3", "furigana": "さい へや かた", "sentence_source": "generated"}, {"text": "出かける際には、かぎをかける。", "target_word": "際", "complexity_tier": "T3", "furigana": "で さい", "sentence_source": "generated"}, {"text": "ご利用の際はカードが必要です。", "target_word": "際", "complexity_tier": "T3", "furigana": "りよう さい ひつよう", "sentence_source": "generated"}, {"text": "引っ越しの際、古い本を捨てた。", "target_word": "際", "complexity_tier": "T3", "furigana": "ひ こ さい ふる ほん す", "sentence_source": "generated"}, {"text": "試合の際の注意を先生が話した。", "target_word": "際", "complexity_tier": "T3", "furigana": "しあい さい ちゅうい せんせい はな", "sentence_source": "generated"}], "morphological_forms": [{"form": "際に", "label": "派生"}, {"form": "際は", "label": "派生"}, {"form": "この際", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 何かをするときやその場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生き物が成長したり活動したりするために必要な成分。", "primary_collocate": null, "pronunciation": "えいよう", "ipa": "eːjoː", "syllable_count": 4, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "たと こくもつ まめるい しゅしょく せっしゅ さい さいぼうへき はば えいよう せいたいりようりつ ひく しゅくめい せお", "sentence_source": "mined"}, {"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "ひ で とも めざ にわとり けんこう えいよう ほうふ たまご う じょうけん", "sentence_source": "mined"}, {"text": "野菜には栄養がたくさんある。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "やさい えいよう", "sentence_source": "generated"}, {"text": "栄養のある物を食べなさい。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "えいよう もの た", "sentence_source": "generated"}, {"text": "この土は栄養が足りない。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "つち えいよう た", "sentence_source": "generated"}, {"text": "母は栄養を考えて料理を作る。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "はは えいよう かんが りょうり つく", "sentence_source": "generated"}, {"text": "植物は根から栄養をとっている。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "しょくぶつ ね えいよう", "sentence_source": "generated"}, {"text": "栄養が足りないと、つかれやすい。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "えいよう た", "sentence_source": "generated"}, {"text": "給食は栄養のバランスがいい。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "きゅうしょく えいよう", "sentence_source": "generated"}, {"text": "子犬に栄養たっぷりのえさをあげた。", "target_word": "栄養", "complexity_tier": "T3", "furigana": "こいぬ えいよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "栄養素", "label": "派生"}, {"form": "栄養士", "label": "派生"}, {"form": "栄養失調", "label": "派生"}, {"form": "栄養価"