INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることをうまく行うための、生まれつきまたは練習で身につけた力。", "primary_collocate": null, "pronunciation": "のうりょく", "ipa": "noːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "その一つひとつの動作が、彼女の認知能力と社会性を育む養分となる。", "target_word": "能力", "complexity_tier": "T3", "furigana": "かのじょ にんち のうりょく しゃかいせい はぐく ようぶん", "sentence_source": "mined"}, {"text": "彼には高い能力がある。", "target_word": "能力", "complexity_tier": "T3", "furigana": "かれ たか のうりょく", "sentence_source": "generated"}, {"text": "練習で能力を伸ばしている。", "target_word": "能力", "complexity_tier": "T3", "furigana": "れんしゅう のうりょく の", "sentence_source": "generated"}, {"text": "能力のある人が選ばれた。", "target_word": "能力", "complexity_tier": "T3", "furigana": "のうりょく ひと えら", "sentence_source": "generated"}, {"text": "自分の能力を信じてほしい。", "target_word": "能力", "complexity_tier": "T3", "furigana": "じぶん のうりょく しん", "sentence_source": "generated"}, {"text": "この仕事は能力が必要だ。", "target_word": "能力", "complexity_tier": "T3", "furigana": "しごと のうりょく ひつよう", "sentence_source": "generated"}, {"text": "能力に合った仕事を探す。", "target_word": "能力", "complexity_tier": "T3", "furigana": "のうりょく あ しごと さが", "sentence_source": "generated"}, {"text": "彼女の能力は皆が認めている。", "target_word": "能力", "complexity_tier": "T3", "furigana": "かのじょ のうりょく みな みと", "sentence_source": "generated"}, {"text": "言葉を話す能力は大切だ。", "target_word": "能力", "complexity_tier": "T3", "furigana": "ことば はな のうりょく たいせつ", "sentence_source": "generated"}, {"text": "能力を十分に発揮できた。", "target_word": "能力", "complexity_tier": "T3", "furigana": "のうりょく じゅうぶん はっき", "sentence_source": "generated"}], "morphological_forms": [{"form": "能力者", "label": "派生"}, {"form": "能力的", "label": "派生"}, {"form": "能力主義", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事をうまく行うための力", "collocate_grounding": {"status": "no