INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51536, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "米や麦など、食用にする植物の種子の総称。", "primary_collocate": null, "pronunciation": "こくもつ", "ipa": "kokɯmotsɯ", "syllable_count": 4, "sentences": [{"text": "例えば、穀物や豆類を主食として摂取する際、その細胞壁に阻まれた栄養は、生体利用率が低いという宿命を背負っている。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "米は大切な穀物です。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "こめ たいせつ こくもつ", "sentence_source": "generated"}, {"text": "この国は穀物をたくさん作る。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "くに こくもつ つく", "sentence_source": "generated"}, {"text": "穀物の値段が上がっている。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "こくもつ ねだん あ", "sentence_source": "generated"}, {"text": "倉庫に穀物を保存する。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "そうこ こくもつ ほぞん", "sentence_source": "generated"}, {"text": "穀物が雨でだめになった。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "こくもつ あめ", "sentence_source": "generated"}, {"text": "麦も穀物の一つだ。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "むぎ こくもつ ひと", "sentence_source": "generated"}, {"text": "穀物を外国から買っている。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "こくもつ がいこく か", "sentence_source": "generated"}], "morphological_forms": [{"form": "穀物類", "label": "派生"}, {"form": "穀物倉庫", "label": "派生"}, {"form": "トン", "label": "助数詞"}], "register": "formal", "sense_fingerprint": "名詞 | 米や麦など食用の種子", "collocate_grounding": {"status": "no_source", "reason":