INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35673, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "微生物の働きによって有機物が分解され、アルコールや酸などが生成される化学変化。食品の製造に利用される。", "primary_collocate": null, "pronunciation": "はっこう", "ipa": "hakkoː", "syllable_count": 4, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "そこに、発酵の不可欠な役割が凝縮されているのである。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "納豆は大豆を発酵させて作る。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "なっとう だいず はっこう つく", "sentence_source": "generated"}, {"text": "パンの生地が発酵している。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "きじ はっこう", "sentence_source": "generated"}, {"text": "発酵には時間がかかる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "はっこう じかん", "sentence_source": "generated"}, {"text": "夏は発酵が早く進む。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "なつ はっこう はや すす", "sentence_source": "generated"}, {"text": "みそは発酵した食べ物だ。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "はっこう た もの", "sentence_source": "generated"}, {"text": "発酵の力で味が深くなる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "はっこう ちから あじ ふか", "sentence_source": "generated"}, {"text": "温度が低いと発酵しにくい。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "おんど ひく はっこう", "sentence_source": "generated"}], "morphological_forms": [{"form": "発酵する", "label": "活用"}, {"form": "発酵食品", "label": "派生"}, {"form": "発酵させる", "label": "活用"}, {"form": "発酵した", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 微生物による食品の化学変化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52080, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素や成分がぎっしりと詰まって、密度が高まること。また、そうすること。", "primary_collocate": null, "pronunciation": "ぎょうしゅく", "ipa": "ɡʲoːɕɯkɯ", "syllable_count": 4, "sentences": [{"text": "そこに、発酵の不可欠な役割が凝縮されているのである。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "それはまさに、自然の営みと時間が凝縮したかような深紅を纏うリンゴであった。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "この本には彼の考えが凝縮されている。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "ほん かれ かんが ぎょうしゅく", "sentence_source": "generated"}, {"text": "果物のうまみが凝縮している。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "くだもの ぎょうしゅく", "sentence_source": "generated"}, {"text": "話を短く凝縮して伝えた。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "はなし みじか ぎょうしゅく つた", "sentence_source": "generated"}, {"text": "一年の努力の凝縮だった。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "いちねん どりょく ぎょうしゅく", "sentence_source": "generated"}, {"text": "干すと味が凝縮する。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "ほ あじ ぎょうしゅく", "sentence_source": "generated"}, {"text": "凝縮された時間を過ごした。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "ぎょうしゅく じかん す", "sentence_source": "generated"}, {"text": "思い出が一枚の写真に凝縮した。", "target_word": "凝縮", "complexity_tier": "T3", "furigana": "おも で いちまい しゃしん ぎょうしゅく", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝縮する", "label": "活用"}, {"form": "凝縮された", "label": "活用"}, {"form": "凝縮して", "label": "活用"}, {"form": "凝縮感", "label": "派生"}], "register": "form