INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39435, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "異なる要素や概念が結びついて、新しいものを生み出すこと。", "primary_collocate": null, "pronunciation": "ゆうごう", "ipa": "jɯːɡoː", "syllable_count": 4, "sentences": [{"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "融合", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "東と西の文化が融合した町だ。", "target_word": "融合", "complexity_tier": "T3", "furigana": "ひがし にし ぶんか ゆうごう まち", "sentence_source": "generated"}, {"text": "二つの音楽を融合させた。", "target_word": "融合", "complexity_tier": "T3", "furigana": "ふた おんがく ゆうごう", "sentence_source": "generated"}, {"text": "伝統と新しさの融合が魅力だ。", "target_word": "融合", "complexity_tier": "T3", "furigana": "でんとう あたら ゆうごう みりょく", "sentence_source": "generated"}, {"text": "科学と芸術が融合している。", "target_word": "融合", "complexity_tier": "T3", "furigana": "かがく げいじゅつ ゆうごう", "sentence_source": "generated"}, {"text": "和食と洋食の融合を楽しむ。", "target_word": "融合", "complexity_tier": "T3", "furigana": "わしょく ようしょく ゆうごう たの", "sentence_source": "generated"}, {"text": "融合には時間が必要だ。", "target_word": "融合", "complexity_tier": "T3", "furigana": "ゆうごう じかん ひつよう", "sentence_source": "generated"}, {"text": "二つの考えがうまく融合した。", "target_word": "融合", "complexity_tier": "T3", "furigana": "ふた かんが ゆうごう", "sentence_source": "generated"}, {"text": "この料理は融合の成功例だ。", "target_word": "融合", "complexity_tier": "T3", "furigana": "りょうり ゆうごう せいこうれい", "sentence_source": "generated"}, {"text": "技術の融合で新製品ができた。", "target_word": "融合", "complexity_tier": "T3", "furigana": "ぎじゅつ ゆうごう しんせいひん", "sentence_source": "generated"}], "morphological_forms": [{"form": "融合する", "label": "活用"}, {"form": "融合した", "label": "活用"}, {"form": "融合させる", "label": "活用"}, {"form": "融合的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 異なる