INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36943, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の価値やよさを判断して決めること。", "primary_collocate": null, "pronunciation": "ひょうか", "ipa": "çjoːka", "syllable_count": 3, "sentences": [{"text": "浮世絵は、日本で発展した独自の工芸であり、世界的に評価される芸術です。", "target_word": "評価", "complexity_tier": "T3", "furigana": "うきよえ にほん はってん どくじ こうげい せかいてき ひょうか げいじゅつ", "sentence_source": "mined"}, {"text": "先生は私の作文を高く評価してくれた。", "target_word": "評価", "complexity_tier": "T3", "furigana": "せんせい わたし さくぶん たか ひょうか", "sentence_source": "generated"}, {"text": "この店の料理は評価がとても高い。", "target_word": "評価", "complexity_tier": "T3", "furigana": "みせ りょうり ひょうか たか", "sentence_source": "generated"}, {"text": "彼の努力は正しく評価されるべきだ。", "target_word": "評価", "complexity_tier": "T3", "furigana": "かれ どりょく ただ ひょうか", "sentence_source": "generated"}, {"text": "新しい映画の評価は人によって違う。", "target_word": "評価", "complexity_tier": "T3", "furigana": "あたら えいが ひょうか ひと ちが", "sentence_source": "generated"}, {"text": "テストの結果で成績を評価する。", "target_word": "評価", "complexity_tier": "T3", "furigana": "けっか せいせき ひょうか", "sentence_source": "generated"}, {"text": "みんなの評価を聞いて安心した。", "target_word": "評価", "complexity_tier": "T3", "furigana": "ひょうか き あんしん", "sentence_source": "generated"}, {"text": "自分の仕事を自分で評価するのは難しい。", "target_word": "評価", "complexity_tier": "T3", "furigana": "じぶん しごと じぶん ひょうか むずか", "sentence_source": "generated"}, {"text": "その本はネットで良い評価を受けている。", "target_word": "評価", "complexity_tier": "T3", "furigana": "ほん よ ひょうか う", "sentence_source": "generated"}, {"text": "評価の基準をはっきり決めよう。", "target_word": "評価", "complexity_tier": "T3", "furigana": "ひょうか きじゅん き", "sentence_source": "generated"}], "morphological_forms": [{"form": "評価する", "label": "派生"}, {"form": "評価される", "label": "活用"}, {"form": "高評価", "label": "派生"}, {"form": "再評価", "label": "派生"}], "register": "formal