INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "相手に物や必要なものを渡すこと。", "primary_collocate": null, "pronunciation": "あたえる", "ipa": "ataeɾɯ", "syllable_count": 4, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "与える", "complexity_tier": "T3", "furigana": "さくもつ せいいく じょうきょう こま はあく ひつよう みず ひりょう てきかく あた しく", "sentence_source": "mined"}, {"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "与える", "complexity_tier": "T3", "furigana": "じかんたい あた た もの じもと と しんせん こくもつ やさい ま あ", "sentence_source": "mined"}, {"text": "毎朝、犬にえさを与えている。", "target_word": "与え", "complexity_tier": "T3", "furigana": "まいあさ いぬ あた", "sentence_source": "generated"}, {"text": "花に水を与えるのを忘れた。", "target_word": "与える", "complexity_tier": "T3", "furigana": "はな みず あた わす", "sentence_source": "generated"}, {"text": "先生は生徒に考える時間を与えた。", "target_word": "与え", "complexity_tier": "T3", "furigana": "せんせい せいと かんが じかん あた", "sentence_source": "generated"}, {"text": "子どもにお菓子を与えすぎないでね。", "target_word": "与え", "complexity_tier": "T3", "furigana": "こ かし あた", "sentence_source": "generated"}, {"text": "動物園では、決まった時間にえさが与えられる。", "target_word": "与え", "complexity_tier": "T3", "furigana": "どうぶつえん き じかん あた", "sentence_source": "generated"}, {"text": "彼にもう一度チャンスを与えよう。", "target_word": "与え", "complexity_tier": "T3", "furigana": "かれ いちど あた", "sentence_source": "generated"}, {"text": "植物に肥料を与えて、よく育てた。", "target_word": "与え", "complexity_tier": "T3", "furigana": "しょくぶつ ひりょう あた そだ", "sentence_source": "generated"}, {"text": "ねこにミルクを与えてはいけない。", "target_word": "与え", "complexity_tier": "T3", "furigana": "あた", "sentence_source": "generated"}], "morphological_forms": [{"form": "与えた", "label": "活用"}, {"form": "与えて", "label": "活用"}, {"form": "与えない", "label": "活用"}, {"form": "与えられる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 相手に物や必要なものを渡す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "非常に厳しく、耐えるのが難しい様子。", "primary_collocate": null, "pronunciation": "かこく", "ipa": "kakokɯ", "syllable_count": 3, "sentences": [{"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "さいしょ いちねん うつく でんえん ふうけい うらはら どろ かこく にくたい ろうどう れんぞく", "sentence_source": "mined"}, {"text": "砂漠の夏はとても過酷だ。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "さばく なつ かこく", "sentence_source": "generated"}, {"text": "彼は過酷な練習に毎日耐えている。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かれ かこく れんしゅう まいにち た", "sentence_source": "generated"}, {"text": "山の上の生活は過酷でした。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "やま うえ せいかつ かこく", "sentence_source": "generated"}, {"text": "この仕事の過酷さに驚いた。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "しごと かこく おどろ", "sentence_source": "generated"}, {"text": "過酷な環境でも、この草は育つ。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かこく かんきょう くさ そだ", "sentence_source": "generated"}, {"text": "昔の工場は過酷な場所だった。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "むかし こうじょう かこく ばしょ", "sentence_source": "generated"}, {"text": "選手たちは過酷なレースを走り切った。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "せんしゅ かこく はし き", "sentence_source": "generated"}, {"text": "冬の北海道の寒さは過酷だ。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "ふゆ ほっかいどう さむ かこく", "sentence_source": "generated"}, {"text": "あまりに過酷で、途中でやめる人もいる。", "target_word": "過酷", "complexity_tier": "T3", "furigana": "かこく とちゅう ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "過酷な", "label": "活用"}, {"form": "過酷だ", "label": "活用"}, {"form": "過酷に", "label": "活用"}, {"form": "過酷さ", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 非常に厳しく耐えがたい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36803, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が食べるために畑などで育てる植物。", "primary_collocate": null, "pronunciation": "やさい", "ipa": "jasai", "syllable_count": 3, "sentences": [{"text": "しかし、農薬を使わずに野菜を育てるという仕事を通じて、彼は自然の厳しさと、土が命を育むという壮大な仕組みを、自らの肌で実感していくことになります。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "のうやく つか やさい そだ しごと つう かれ しぜん きび つち いのち はぐく そうだい しく みずか はだ じっかん", "sentence_source": "mined"}, {"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "じかんたい あた た もの じもと と しんせん こくもつ やさい ま あ", "sentence_source": "mined"}, {"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "けいけん ほうふ のうか こうだい はたけ どじょう ていねい たがや やさい たね う", "sentence_source": "mined"}, {"text": "毎日、野菜をたくさん食べている。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "まいにち やさい た", "sentence_source": "generated"}, {"text": "この野菜は庭で育てたものです。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "やさい にわ そだ", "sentence_source": "generated"}, {"text": "弟は野菜があまり好きではない。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "おとうと やさい す", "sentence_source": "generated"}, {"text": "スーパーで新鮮な野菜を買った。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "しんせん やさい か", "sentence_source": "generated"}, {"text": "野菜のスープを作ってみよう。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "やさい つく", "sentence_source": "generated"}, {"text": "夏は野菜の値段が安くなる。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "なつ やさい ねだん やす", "sentence_source": "generated"}, {"text": "祖母の畑では、いろいろな野菜がとれる。", "target_word": "野菜", "complexity_tier": "T3", "furigana": "そぼ はたけ やさい", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "助数詞"}, {"form": "個", "label": "助数詞"}, {"form": "野菜畑", "label": "派生"}, {"form": "野菜炒め", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 畑で育てて食べる植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "問題や相手などに、正面から向かって真剣に取り組むこと。", "primary_collocate": null, "pronunciation": "むきあう", "ipa": "mɯkiaɯ", "syllable_count": 4, "sentences": [{"text": "放課後の美術室で、私は白い画用紙に向き合っている。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "ほうかご びじゅつしつ わたし しろ がようし む あ", "sentence_source": "mined"}, {"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "せいひつ じたく こうぼう しょがくしゃ む あ せいさく ほんしつ", "sentence_source": "mined"}, {"text": "過酷な自然環境と向き合いながら、彼は今日も黙々と作業を続け、やがて訪れる豊かな実りの季節を心待ちにしている。", "target_word": "向き合い", "complexity_tier": "T3", "furigana": "かこく しぜん かんきょう む あ かれ きょう もくもく さぎょう つづ おとず ゆた みの きせつ こころま", "sentence_source": "mined"}, {"text": "自分の弱さと向き合うのは怖い。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "じぶん よわ む あ こわ", "sentence_source": "generated"}, {"text": "彼女は病気と前向きに向き合った。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "かのじょ びょうき まえむ む あ", "sentence_source": "generated"}, {"text": "問題から逃げずに向き合いたい。", "target_word": "向き合い", "complexity_tier": "T3", "furigana": "もんだい に む あ", "sentence_source": "generated"}, {"text": "子どもとしっかり向き合う時間が大切だ。", "target_word": "向き合う", "complexity_tier": "T3", "furigana": "こ む あ じかん たいせつ", "sentence_source": "generated"}, {"text": "二人は将来に真剣に向き合った。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "ふたり しょうらい しんけん む あ", "sentence_source": "generated"}, {"text": "苦手な数学に毎日向き合っている。", "target_word": "向き合っ", "complexity_tier": "T3", "furigana": "にがて すうがく まいにち む あ", "sentence_source": "generated"}, {"text": "失敗と向き合える人は強い。", "target_word": "向き合", "complexity_tier": "T3", "furigana": "しっぱい む あ ひと つよ", "sentence_source": "generated"}], "morphological_forms": [{"form": "向き合った", "label": "活用"}, {"form": "向き合って", "label": "活用"}, {"form": "向き合わない", "label": "活用"}, {"form": "向き合い", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 問題や相手に正面から取り組む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "宇宙や自然の秩序、または物事の道理や法則。", "primary_collocate": null, "pronunciation": "せつり", "ipa": "setsɯɾi", "syllable_count": 3, "sentences": [{"text": "その姿は、まさに宇宙の摂理そのものを体現しているかのようであった。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "すがた うちゅう せつり たいげん", "sentence_source": "mined"}, {"text": "この一連の工程は、自然の摂理と人間の叡智が交差する、紛れもなく芸術的な創造物である。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "いちれん こうてい しぜん せつり にんげん えいち こうさ まぎ げいじゅつてき そうぞうぶつ", "sentence_source": "mined"}, {"text": "その行為は単なるガーデニングの域を超え、自然の摂理に対する静かなる祈りにも似ている。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "こうい たん いき こ しぜん せつり たい しず いの に", "sentence_source": "mined"}, {"text": "花が散るのは自然の摂理だ。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "はな ち しぜん せつり", "sentence_source": "generated"}, {"text": "生き物が死ぬのは、自然の摂理である。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "い もの し しぜん せつり", "sentence_source": "generated"}, {"text": "彼は自然の摂理に逆らおうとした。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "かれ しぜん せつり さか", "sentence_source": "generated"}, {"text": "季節がめぐるのも摂理の一つだ。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "きせつ せつり ひと", "sentence_source": "generated"}, {"text": "昔の人は星の動きに摂理を見た。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "むかし ひと ほし うご せつり み", "sentence_source": "generated"}, {"text": "摂理に従って、川は海へ流れる。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "せつり したが かわ うみ なが", "sentence_source": "generated"}, {"text": "この本は自然の摂理について書いている。", "target_word": "摂理", "complexity_tier": "T3", "furigana": "ほん しぜん せつり か", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然の摂理", "label": "派生"}, {"form": "神の摂理", "label": "派生"}, {"form": "宇宙の摂理", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 自然や宇宙を貫く秩序や法則", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52074, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "強調の副詞。述べた内容が疑いなく事実であることを示す。", "primary_collocate": null, "pronunciation": "まさに", "ipa": "masani", "syllable_count": 3, "sentences": [{"text": "その姿は、まさに宇宙の摂理そのものを体現しているかのようであった。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "まさに", "sentence_source": "mined"}, {"text": "まさに、大地と対話するその姿勢こそが、未来を担う魂の育成に他ならないのだろう。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "まさに", "sentence_source": "mined"}, {"text": "これはまさに私がほしかった本だ。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "わたし ほん", "sentence_source": "generated"}, {"text": "彼の言葉はまさに正しかった。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "かれ ことば ただ", "sentence_source": "generated"}, {"text": "今日はまさに夏の暑さだ。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "きょう なつ あつ", "sentence_source": "generated"}, {"text": "まさにその時、電話が鳴った。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "とき でんわ な", "sentence_source": "generated"}, {"text": "彼女はまさに天才と言える。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "かのじょ てんさい い", "sentence_source": "generated"}, {"text": "その景色はまさに絵のようだった。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "けしき え", "sentence_source": "generated"}, {"text": "まさに君の言うとおりだ。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "きみ い", "sentence_source": "generated"}, {"text": "試合はまさに今始まるところだ。", "target_word": "まさに", "complexity_tier": "T3", "furigana": "しあい いま はじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "まさしく", "label": "派生"}, {"form": "今まさに", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | 疑いなくその通りだと強める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "プログラムや数式で使われる、値が変化する記号や名前。", "primary_collocate": null, "pronunciation": "へんすう", "ipa": "heɴsɯː", "syllable_count": 4, "sentences": [{"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "変数", "complexity_tier": "T3", "furigana": "へんすう", "sentence_source": "mined"}, {"text": "指先を通じて伝わる生地の微妙な弾力や発酵の進行具合を唯一の羅針盤とし、彼は温度と湿度という変数を緻密に制御することで、微生物という目に見えぬパートナーとの静かなる対話を試みる。", "target_word": "変数", "complexity_tier": "T3", "furigana": "へんすう", "sentence_source": "mined"}, {"text": "この式ではxが変数です。", "target_word": "変数", "complexity_tier": "T3", "furigana": "しき へんすう", "sentence_source": "generated"}, {"text": "プログラムで新しい変数を作った。", "target_word": "変数", "complexity_tier": "T3", "furigana": "あたら へんすう つく", "sentence_source": "generated"}, {"text": "変数の名前は短くしよう。", "target_word": "変数", "complexity_tier": "T3", "furigana": "へんすう なまえ みじか", "sentence_source": "generated"}, {"text": "変数に数字の5を入れる。", "target_word": "変数", "complexity_tier": "T3", "furigana": "へんすう すうじ い", "sentence_source": "generated"}, {"text": "先生が変数の意味を説明した。", "target_word": "変数", "complexity_tier": "T3", "furigana": "せんせい へんすう いみ せつめい", "sentence_source": "generated"}, {"text": "変数が多いと計算が難しい。", "target_word": "変数", "complexity_tier": "T3", "furigana": "へんすう おお けいさん むずか", "sentence_source": "generated"}, {"text": "この変数は何回も変わる。", "target_word": "変数", "complexity_tier": "T3", "furigana": "へんすう なんかい か", "sentence_source": "generated"}, {"text": "二つの変数を比べてみよう。", "target_word": "変数", "complexity_tier": "T3", "furigana": "ふた へんすう くら", "sentence_source": "generated"}], "morphological_forms": [{"form": "変数名", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 値が変わる記号や名前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51516, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "口に出さず、静かに、ひたすら一つのことに集中して取り組むさま。", "primary_collocate": null, "pronunciation": "もくもく", "ipa": "mokɯmokɯ", "syllable_count": 4, "sentences": [{"text": "木漏れ日がその頬を静かに照らす中、彼はただ黙々と、自らの内なる飢えと、この季節の恵みとを一体化させていくのである。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "もくもく", "sentence_source": "mined"}, {"text": "過酷な自然環境と向き合いながら、彼は今日も黙々と作業を続け、やがて訪れる豊かな実りの季節を心待ちにしている。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "もくもく", "sentence_source": "mined"}, {"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "もくもく", "sentence_source": "mined"}, {"text": "兄は黙々と宿題をしている。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "あに もくもく しゅくだい", "sentence_source": "generated"}, {"text": "彼女は朝から黙々と働いた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "かのじょ あさ もくもく はたら", "sentence_source": "generated"}, {"text": "黙々と走る選手がいた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "もくもく はし せんしゅ", "sentence_source": "generated"}, {"text": "父は黙々とご飯を食べた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "ちち もくもく はん た", "sentence_source": "generated"}, {"text": "みんな黙々と掃除を続けた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "もくもく そうじ つづ", "sentence_source": "generated"}, {"text": "彼の黙々とした姿に感動した。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "かれ もくもく すがた かんどう", "sentence_source": "generated"}, {"text": "黙々と練習することが大切だ。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "もくもく れんしゅう たいせつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "黙々と", "label": "派生"}], "register": "formal", "sense_fingerprint": "副詞 | 黙ってひたすら取り組むさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "強く欲しがること。切実に望むこと。", "primary_collocate": null, "pronunciation": "かつぼう", "ipa": "kats͡ɯboː", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "かつぼう", "sentence_source": "mined"}, {"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "かつぼう", "sentence_source": "mined"}, {"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "かつぼう", "sentence_source": "mined"}, {"text": "人々は平和を渇望している。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "ひとびと へいわ かつぼう", "sentence_source": "generated"}, {"text": "彼は自由への渇望を感じた。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "かれ じゆう かつぼう かん", "sentence_source": "generated"}, {"text": "知識への渇望が彼女を動かす。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "ちしき かつぼう かのじょ うご", "sentence_source": "generated"}, {"text": "渇望していた夢がかなった。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "かつぼう ゆめ", "sentence_source": "generated"}, {"text": "その国は変化を渇望していた。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "くに へんか かつぼう", "sentence_source": "generated"}, {"text": "強い渇望が胸にわいてきた。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "つよ かつぼう むね", "sentence_source": "generated"}, {"text": "彼の目には渇望の色があった。", "target_word": "渇望", "complexity_tier": "T3", "furigana": "かれ め かつぼう いろ", "sentence_source": "generated"}], "morphological_forms": [{"form": "渇望する", "label": "派生"}, {"form": "渇望感", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 心から強く欲しがること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51590, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "機械や装置を目的に合わせて動かしたり、制御したりすること。", "primary_collocate": null, "pronunciation": "そうさ", "ipa": "soːsa", "syllable_count": 3, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "操作", "complexity_tier": "T3", "furigana": "そうさ", "sentence_source": "mined"}, {"text": "天然染料による染色は、単なる化学的操作の連鎖ではなく、素材と対話する儀礼にも等しい。", "target_word": "操作", "complexity_tier": "T3", "furigana": "そうさ", "sentence_source": "mined"}, {"text": "このスマホは操作が簡単だ。", "target_word": "操作", "complexity_tier": "T3", "furigana": "そうさ かんたん", "sentence_source": "generated"}, {"text": "父がクレーンを操作している。", "target_word": "操作", "complexity_tier": "T3", "furigana": "ちち そうさ", "sentence_source": "generated"}, {"text": "操作を間違えて画面が消えた。", "target_word": "操作", "complexity_tier": "T3", "furigana": "そうさ まちが がめん き", "sentence_source": "generated"}, {"text": "ロボットを遠くから操作できる。", "target_word": "操作", "complexity_tier": "T3", "furigana": "とお そうさ", "sentence_source": "generated"}, {"text": "操作の方法を教えてください。", "target_word": "操作", "complexity_tier": "T3", "furigana": "そうさ ほうほう おし", "sentence_source": "generated"}, {"text": "新しい機械の操作に慣れた。", "target_word": "操作", "complexity_tier": "T3", "furigana": "あたら きかい そうさ な", "sentence_source": "generated"}, {"text": "姉はパソコンを操作するのが得意だ。", "target_word": "操作", "complexity_tier": "T3", "furigana": "あね そうさ とくい", "sentence_source": "generated"}, {"text": "ボタン一つで操作が終わる。", "target_word": "操作", "complexity_tier": "T3", "furigana": "ひと そうさ お", "sentence_source": "generated"}], "morphological_forms": [{"form": "操作する", "label": "派生"}, {"form": "操作方法", "label": "派生"}, {"form": "遠隔操作", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 機械を動かし制御すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52102, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄や状況の間に、別の要素や要因が入り込んで影響を与えること。", "primary_collocate": null, "pronunciation": "かいざい", "ipa": "kaizai", "syllable_count": 4, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "介在", "complexity_tier": "T3", "furigana": "かいざい", "sentence_source": "mined"}, {"text": "ここで媒染という重要な工程が介在する。", "target_word": "介在", "complexity_tier": "T3", "furigana": "かいざい", "sentence_source": "mined"}, {"text": "二人の間に誤解が介在していた。", "target_word": "介在", "complexity_tier": "T3", "furigana": "ふたり あいだ ごかい かいざい", "sentence_source": "generated"}, {"text": "取引には仲介業者が介在する。", "target_word": "介在", "complexity_tier": "T3", "furigana": "とりひき ちゅうかいぎょうしゃ かいざい", "sentence_source": "generated"}, {"text": "感情の介在は避けたい。", "target_word": "介在", "complexity_tier": "T3", "furigana": "かんじょう かいざい さ", "sentence_source": "generated"}, {"text": "お金が介在すると話が変わる。", "target_word": "介在", "complexity_tier": "T3", "furigana": "かね かいざい はなし か", "sentence_source": "generated"}, {"text": "その事件には第三者の介在があった。", "target_word": "介在", "complexity_tier": "T3", "furigana": "じけん だいさんしゃ かいざい", "sentence_source": "generated"}, {"text": "人の介在なしで機械が動く。", "target_word": "介在", "complexity_tier": "T3", "furigana": "ひと かいざい きかい うご", "sentence_source": "generated"}, {"text": "問題の介在で計画が遅れた。", "target_word": "介在", "complexity_tier": "T3", "furigana": "もんだい かいざい けいかく おく", "sentence_source": "generated"}, {"text": "多くの要因が介在している。", "target_word": "介在", "complexity_tier": "T3", "furigana": "おお よういん かいざい", "sentence_source": "generated"}], "morphological_forms": [{"form": "介在する", "label": "派生"}, {"form": "介在者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 間に別の要素が入り込むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56149744-487e-40b9-ac6d-2f818fa8278f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "資金", "is_correct": true, "explanation": "「しきん」：事業の元手となるお金。"}, {"text": "試験", "is_correct": false, "explanation": "「しけん」：三つ目の「き」が「け」に変わる一モーラ差。"}, {"text": "詩吟", "is_correct": false, "explanation": "「しぎん」：「き」と「ぎ」の清濁の違い。"}, {"text": "敷居", "is_correct": false, "explanation": "「しきい」：最後の「ん」が「い」に変わる一モーラ差。"}], "explanations": {"資金": "「しきん」：事業の元手となるお金。", "試験": "「しけん」：三つ目の「き」が「け」に変わる一モーラ差。", "詩吟": "「しぎん」：「き」と「ぎ」の清濁の違い。", "敷居": "「しきい」：最後の「ん」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "資金"}, "level_3": {"options": [{"text": "資金", "is_correct": true, "explanation": "意味：投資家から集めるのは事業の元手となるお金なので「資金調達」が正しい。"}, {"text": "部品", "is_correct": false, "explanation": "意味：投資家から部品を集めるのではなく、出資されるのはお金である。"}, {"text": "食料", "is_correct": false, "explanation": "意味：投資家が提供するのは食料ではなく事業のためのお金である。"}, {"text": "木材", "is_correct": false, "explanation": "連語：「投資家からの木材調達」は事業の基盤づくりの文脈に合わない。"}], "explanations": {"資金": "意味：投資家から集めるのは事業の元手となるお金なので「資金調達」が正しい。", "部品": "意味：投資家から部品を集めるのではなく、出資されるのはお金である。", "食料": "意味：投資家が提供するのは食料ではなく事業のためのお金である。", "木材": "連語：「投資家からの木材調達」は事業の基盤づくりの文脈に合わない。"}, "sentence_index": 0, "correct_answer": "資金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資金を一冊集めた。", "explanation": "助数詞の誤り：お金の量は「冊」では数えない。"}, {"text": "祭りの資金に町で集めた。", "explanation": "助詞の誤り：「集める」の目的語は「を」で示す。「資金に」ではなく「資金を」。"}, {"text": "資金が明日足りなくなった。", "explanation": "テンスの誤り：「明日」と過去形「なった」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社を作るために資金にためた。", "corrected_sentence": "会社を作るために資金をためた。", "error_description": "助詞の誤り：「ためる」の目的語は「を」で示す。「資金に」ではなく「資金を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「行う」の目的語「資金調達」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、他動詞「行い」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、「行う」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示し、この位置では非文になる。"}], "correct_answer": "を", "explanations": {"を": "他動詞「行う」の目的語「資金調達」を示す。", "が": "主格になり、他動詞「行い」と合わない。", "に": "着点を示し、「行う」の目的語にならない。", "で": "場所・手段を示し、この位置では非文になる。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "資金", "is_correct": true, "explanation": "「しきん」：活動の元手になるお金。"}, {"text": "指針", "is_correct": false, "explanation": "「ししん」：「き」が「し」になった一モーラ差（方針）。"}, {"text": "士官", "is_correct": false, "explanation": "「しかん」：「き」が「か」になった一モーラ差（軍の将校）。"}, {"text": "詩吟", "is_correct": false, "explanation": "「しぎん」：「き」が濁って「ぎ」になった清濁の対立。"}], "explanations": {"資金": "「しきん」：活動の元手になるお金。", "指針": "「ししん」：「き」が「し」になった一モーラ差（方針）。", "士官": "「しかん」：「き」が「か」になった一モーラ差（軍の将校）。", "詩吟": "「しぎん」：「き」が濁って「ぎ」になった清濁の対立。"}, "sentence_index": null, "correct_answer": "資金"}, "level_3": {"options": [{"text": "資金", "is_correct": true, "explanation": "意味：会社を作るためにためるのは元手のお金である。"}, {"text": "涙", "is_correct": false, "explanation": "意味：涙をためても会社は作れず、文の意味が通らない。"}, {"text": "水", "is_correct": false, "explanation": "意味：水をためることは会社を作る元手にならない。"}, {"text": "ほこり", "is_correct": false, "explanation": "連語：「ほこりをためて会社を作る」は意味をなさない。"}], "explanations": {"資金": "意味：会社を作るためにためるのは元手のお金である。", "涙": "意味：涙をためても会社は作れず、文の意味が通らない。", "水": "意味：水をためることは会社を作る元手にならない。", "ほこり": "連語：「ほこりをためて会社を作る」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "資金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生徒会が資金を三匹出した。", "explanation": "助数詞の誤り：お金を「匹」で数えることはできない。"}, {"text": "文化祭が資金を生徒会は出す。", "explanation": "助詞の誤り：主語と主題がずれ、だれが出すのかわからなくなる。"}, {"text": "資金は明日生徒会が出した。", "explanation": "テンスの誤り：「明日」と過去の「出した」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この活動は寄付が資金をなっている。", "corrected_sentence": "この活動は寄付が資金になっている。", "error_description": "助詞の誤り：「なる」は「〜に」をとる。「資金を」ではなく「資金に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39057, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「なる」の結果を示す格助詞で、寄付が資金という状態になることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は目的語をとらないので非文。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示し、「なっている」と結びつかない。"}, {"text": "が", "is_correct": false, "explanation": "主格が二つ重なり文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「なる」の結果を示す格助詞で、寄付が資金という状態になることを表す。", "を": "「なる」は目的語をとらないので非文。", "で": "手段・場所を示し、「なっている」と結びつかない。", "が": "主格が二つ重なり文が成り立たない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "が": "topic_vs_subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35791, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "段階", "is_correct": true, "explanation": "「だんかい」：物事の進み具合の区切り。"}, {"text": "団体", "is_correct": false, "explanation": "「だんたい」：二つ目の「か」が「た」に変わる一モーラ差。"}, {"text": "挽回", "is_correct": false, "explanation": "「ばんかい」：最初の「だ」が「ば」に変わる一モーラ差。"}, {"text": "限界", "is_correct": false, "explanation": "「げんかい」：最初の「だ」が「げ」に変わる一モーラ差。"}], "explanations": {"段階": "「だんかい」：物事の進み具合の区切り。", "団体": "「だんたい」：二つ目の「か」が「た」に変わる一モーラ差。", "挽回": "「ばんかい」：最初の「だ」が「ば」に変わる一モーラ差。", "限界": "「げんかい」：最初の「だ」が「げ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "段階"}, "level_3": {"options": [{"text": "段階", "is_correct": true, "explanation": "意味：「初期段階」は物事が始まったばかりの区切りを表す。"}, {"text": "設定", "is_correct": false, "explanation": "意味：「初期設定」は機械の設定のことで、事業の時期を表さない。"}, {"text": "不良", "is_correct": false, "explanation": "意味：「初期不良」は製品の故障を指し、文意に合わない。"}, {"text": "費用", "is_correct": false, "explanation": "連語：「初期費用では…基盤を固め」は時期を表せず不自然。"}], "explanations": {"段階": "意味：「初期段階」は物事が始まったばかりの区切りを表す。", "設定": "意味：「初期設定」は機械の設定のことで、事業の時期を表さない。", "不良": "意味：「初期不良」は製品の故障を指し、文意に合わない。", "費用": "連語：「初期費用では…基盤を固め」は時期を表せず不自然。"}, "sentence_index": 0, "correct_answer": "段階"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "練習は三冊の段階に分かれている。", "explanation": "助数詞の誤り：段階は「冊」で数えない。「三つ」が正しい。"}, {"text": "練習を三つの段階が分かれている。", "explanation": "助詞の誤り：「を」と「が」が入れ替わり非文になる。"}, {"text": "練習は段階に三つの分かれている。", "explanation": "語順の誤り：「三つの」が「段階」を修飾できない位置にある。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.v