INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35791, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "段階", "is_correct": true, "explanation": "「だんかい」：進み具合による区切り。"}, {"text": "展開", "is_correct": false, "explanation": "「てんかい」：「だ」が「て」になった一モーラ差（広がること）。"}, {"text": "散会", "is_correct": false, "explanation": "「さんかい」：「だ」が「さ」になった一モーラ差（会が終わること）。"}, {"text": "団体", "is_correct": false, "explanation": "「だんたい」：「か」が「た」になった一モーラ差（人の集まり）。"}], "explanations": {"段階": "「だんかい」：進み具合による区切り。", "展開": "「てんかい」：「だ」が「て」になった一モーラ差（広がること）。", "散会": "「さんかい」：「だ」が「さ」になった一モーラ差（会が終わること）。", "団体": "「だんたい」：「か」が「た」になった一モーラ差（人の集まり）。"}, "sentence_index": null, "correct_answer": "段階"}, "level_3": {"options": [{"text": "段階", "is_correct": true, "explanation": "意味：進み具合のどの区切りでも、という意味になる。"}, {"text": "値段", "is_correct": false, "explanation": "意味：「どの値段でも先生が助ける」は意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "意味：色は学習の進み具合を表さない。"}, {"text": "重さ", "is_correct": false, "explanation": "意味：重さは先生が助ける場面と関係がない。"}], "explanations": {"段階": "意味：進み具合のどの区切りでも、という意味になる。", "値段": "意味：「どの値段でも先生が助ける」は意味が通らない。", "色": "意味：色は学習の進み具合を表さない。", "重さ": "意味：重さは先生が助ける場面と関係がない。"}, "sentence_index": 6, "correct_answer": "段階"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事は最終段階を入った。", "explanation": "助詞の誤り：「入る」は「に」をとる。「段階に入った」。"}, {"text": "工事は明日最終段階に入った。", "explanation": "テンスの誤り：「明日」と過去形「入った」が合わない。"}, {"text": "工事は一枚の最終段階に入った。", "explanation": "助数詞の誤り：段階を「枚」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
