INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "革新", "is_correct": true, "explanation": "「かくしん」：古いやり方を新しく変えること。"}, {"text": "確認", "is_correct": false, "explanation": "「かくにん」：三つ目の「し」が「に」に変わる一モーラ差。"}, {"text": "改心", "is_correct": false, "explanation": "「かいしん」：二つ目の「く」が「い」に変わる一モーラ差。"}, {"text": "格式", "is_correct": false, "explanation": "「かくしき」：最後の「ん」が「き」に変わる一モーラ差。"}], "explanations": {"革新": "「かくしん」：古いやり方を新しく変えること。", "確認": "「かくにん」：三つ目の「し」が「に」に変わる一モーラ差。", "改心": "「かいしん」：二つ目の「く」が「い」に変わる一モーラ差。", "格式": "「かくしき」：最後の「ん」が「き」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "革新"}, "level_3": {"options": [{"text": "革新", "is_correct": true, "explanation": "意味：スタートアップの種は新しいことを生む「革新的」なアイデアである。"}, {"text": "保守", "is_correct": false, "explanation": "意味：「保守的なアイデア」は古いやり方を守るもので、創業の種に合わない。"}, {"text": "消極", "is_correct": false, "explanation": "意味：「消極的なアイデア」は新しい事業の種という文意に合わない。"}, {"text": "否定", "is_correct": false, "explanation": "意味：「否定的なアイデア」では新しい事業の種にならない。"}], "explanations": {"革新": "意味：スタートアップの種は新しいことを生む「革新的」なアイデアである。", "保守": "意味：「保守的なアイデア」は古いやり方を守るもので、創業の種に合わない。", "消極": "意味：「消極的なアイデア」は新しい事業の種という文意に合わない。", "否定": "意味：「否定的なアイデア」では新しい事業の種にならない。"}, "sentence_index": 0, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町に小さな革新を起きた。", "explanation": "助詞の誤り：自動詞「起きる」の主語は「が」。"}, {"text": "町に一本の革新が起きた。", "explanation": "助数詞の誤り：革新は「本」で数えない。"}, {"text": "町に小さな革新が明日起きた。", "explanation": "テンスの誤り：「明日」と過去形「起きた」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は革新が大切にしている。", "corrected_sentence": "この会社は革新を大切にしている。", "error_description": "助詞の誤り：「大切にする」の対象は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「両立させる」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、使役の他動詞「両立させる」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示し、ここでは非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「両立させる」の目的語を示す。", "が": "主格になり、使役の他動詞「両立させる」と合わない。", "に": "着点を示し、目的語にならない。", "で": "手段・場所を示し、ここでは非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "古いやり方を守ることで、「革新」の対義語。"}, {"text": "改革", "is_correct": false, "explanation": "古い制度を改めることで、むしろ意味が近い。"}, {"text": "発展", "is_correct": false, "explanation": "よい方向に伸びることで、対義の関係にない。"}, {"text": "進歩", "is_correct": false, "explanation": "前に進むことで、革新と方向が同じ。"}], "correct_answer": "保守", "explanations": {"保守": "古いやり方を守ることで、「革新」の対義語。", "改革": "古い制度を改めることで、むしろ意味が近い。", "発展": "よい方向に伸びることで、対義の関係にない。", "進歩": "前に進むことで、革新と方向が同じ。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "革新", "is_correct": true, "explanation": "「かくしん」：新しい技術や考え方を取り入れること。"}, {"text": "各人", "is_correct": false, "explanation": "「かくじん」：「し」が濁って「じ」になった清濁の対立（一人一人）。"}, {"text": "拡散", "is_correct": false, "explanation": "「かくさん」：「し」が「さ」になった一モーラ差（広がり散ること）。"}, {"text": "確認", "is_correct": false, "explanation": "「かくにん」：「し」が「に」になった一モーラ差（たしかめること）。"}], "explanations": {"革新": "「かくしん」：新しい技術や考え方を取り入れること。", "各人": "「かくじん」：「し」が濁って「じ」になった清濁の対立（一人一人）。", "拡散": "「かくさん」：「し」が「さ」になった一モーラ差（広がり散ること）。", "確認": "「かくにん」：「し」が「に」になった一モーラ差（たしかめること）。"}, "sentence_index": null, "correct_answer": "革新"}, "level_3": {"options": [{"text": "革新", "is_correct": true, "explanation": "意味：新しい店が始めた今までにないサービスなので「革新的」が合う。"}, {"text": "悲劇", "is_correct": false, "explanation": "意味：「悲劇的なサービス」はサービスの性質として意味をなさない。"}, {"text": "悲観", "is_correct": false, "explanation": "意味：「悲観的なサービス」は気持ちの表現でサービスを表せない。"}, {"text": "消極", "is_correct": false, "explanation": "連語：「消極的なサービスを始めた」は不自然。"}], "explanations": {"革新": "意味：新しい店が始めた今までにないサービスなので「革新的」が合う。", "悲劇": "意味：「悲劇的なサービス」はサービスの性質として意味をなさない。", "悲観": "意味：「悲観的なサービス」は気持ちの表現でサービスを表せない。", "消極": "連語：「消極的なサービスを始めた」は不自然。"}, "sentence_index": 6, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社長は工場の革新に進めている。", "explanation": "助詞の誤り：「進める」の目的語は「を」。"}, {"text": "社長は明日工場の革新を進めた。", "explanation": "テンスの誤り：「明日」と過去形「進めた」が合わない。"}, {"text": "社長は工場の三匹の革新を進めている。", "explanation": "助数詞の誤り：革新を「匹」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "技術の革新を生活が便利になった。", "corrected_sentence": "技術の革新で生活が便利になった。", "error_description": "助詞の誤り：原因を表すのは「で」。「革新を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35837, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "原因・手段を示し、革新によって便利になったことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「なった」は目的語をとらないので非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、原因を表せない。"}, {"text": "まで", "is_correct": false, "explanation": "範囲の終点を示し、この文では意味をなさない。"}], "correct_answer": "で", "explanations": {"で": "原因・手段を示し、革新によって便利になったことを表す。", "を": "「なった」は目的語をとらないので非文。", "へ": "方向を示し、原因を表せない。", "まで": "範囲の終点を示し、この文では意味をなさない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "まで": "other"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "今までのやり方を守る立場で、「革新」の反対。"}, {"text": "変化", "is_correct": false, "explanation": "変わることで、対義ではない。"}, {"text": "創造", "is_correct": false, "explanation": "新しく作り出すことで、革新と近い意味。"}, {"text": "発明", "is_correct": false, "explanation": "新しい物を考え出すことで、対義の関係にない。"}], "correct_answer": "保守", "explanations": {"保守": "今までのやり方を守る立場で、「革新」の反対。", "変化": "変わることで、対義ではない。", "創造": "新しく作り出すことで、革新と近い意味。", "発明": "新しい物を考え出すことで、対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "調達", "is_correct": true, "explanation": "「ちょうたつ」：必要な物やお金を集めること。"}, {"text": "上達", "is_correct": false, "explanation": "「じょうたつ」：最初の「ちょ」が濁って「じょ」になる清濁の対立。"}, {"text": "到達", "is_correct": false, "explanation": "「とうたつ」：最初の「ちょ」が「と」に変わる一モーラ差。"}, {"text": "懲罰", "is_correct": false, "explanation": "「ちょうばつ」：「た」が「ば」に変わる一モーラ差。"}], "explanations": {"調達": "「ちょうたつ」：必要な物やお金を集めること。", "上達": "「じょうたつ」：最初の「ちょ」が濁って「じょ」になる清濁の対立。", "到達": "「とうたつ」：最初の「ちょ」が「と」に変わる一モーラ差。", "懲罰": "「ちょうばつ」：「た」が「ば」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "調達"}, "level_3": {"options": [{"text": "調達", "is_correct": true, "explanation": "意味：投資家からお金を集めることなので「資金調達」が正しい。"}, {"text": "返済", "is_correct": false, "explanation": "意味：投資家からの「返済」は向きが逆で、基盤を固める文意に合わない。"}, {"text": "不足", "is_correct": false, "explanation": "連語：「投資家からの資金不足を通じて」は結びつかない。"}, {"text": "消費", "is_correct": false, "explanation": "意味：お金を使うことで、集める意味にならない。"}], "explanations": {"調達": "意味：投資家からお金を集めることなので「資金調達」が正しい。", "返済": "意味：投資家からの「返済」は向きが逆で、基盤を固める文意に合わない。", "不足": "連語：「投資家からの資金不足を通じて」は結びつかない。", "消費": "意味：お金を使うことで、集める意味にならない。"}, "sentence_index": 0, "correct_answer": "調達"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祭りの材料を地元を調達した。", "explanation": "助詞の誤り：場所は「で」で示す。「を」が二つ重なり非文。"}, {"text": "祭りの材料を明日地元で調達した。", "explanation": "テンスの誤り：「明日」と過去形「調達した」が合わない。"}, {"text": "祭りの材料が地元で調達した。", "explanation": "助詞の誤り：他動詞「調達した」の目的語は「を」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "投資家から資金に調達した。", "corrected_sentence": "投資家から資金を調達した。", "error_description": "助詞の誤り：「調達する」の目的語は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「行う」の目的語「資金調達」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、他動詞「行い」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示し、「資金調達から行い」は意味をなさない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「行う」の目的語「資金調達」を示す。", "が": "主格になり、他動詞「行い」と合わない。", "に": "着点を示し、目的語にならない。", "から": "起点を示し、「資金調達から行い」は意味をなさない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "から": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "調達", "is_correct": true, "explanation": "「ちょうたつ」：品物や資金を集めて準備すること。"}, {"text": "用達", "is_correct": false, "explanation": "「ようたつ」：「ちょ」が「よ」になった一モーラ差（御用達）。"}, {"text": "通達", "is_correct": false, "explanation": "「つうたつ」：「ちょ」が「つ」になった一モーラ差（知らせ）。"}, {"text": "懲罰", "is_correct": false, "explanation": "「ちょうばつ」：「た」が「ば」になった一モーラ差（罰）。"}], "explanations": {"調達": "「ちょうたつ」：品物や資金を集めて準備すること。", "用達": "「ようたつ」：「ちょ」が「よ」になった一モーラ差（御用達）。", "通達": "「つうたつ」：「ちょ」が「つ」になった一モーラ差（知らせ）。", "懲罰": "「ちょうばつ」：「た」が「ば」になった一モーラ差（罰）。"}, "sentence_index": null, "correct_answer": "調達"}, "level_3": {"options": [{"text": "調達", "is_correct": true, "explanation": "意味：必要な道具を自分で集めて準備することを表す。"}, {"text": "紛失", "is_correct": false, "explanation": "意味：必要な道具を「自分で紛失する」は意味が通らない。"}, {"text": "破壊", "is_correct": false, "explanation": "意味：必要な道具を壊すのは文意と矛盾する。"}, {"text": "放棄", "is_correct": false, "explanation": "意味：必要なのに捨てるのは矛盾する。"}], "explanations": {"調達": "意味：必要な道具を自分で集めて準備することを表す。", "紛失": "意味：必要な道具を「自分で紛失する」は意味が通らない。", "破壊": "意味：必要な道具を壊すのは文意と矛盾する。", "放棄": "意味：必要なのに捨てるのは矛盾する。"}, "sentence_index": 6, "correct_answer": "調達"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は会社で物の調達がしている。", "explanation": "助詞の誤り：「する」の目的語は「を」。"}, {"text": "父は会社を物の調達をしている。", "explanation": "助詞の誤り：場所は「で」で示し、「を」は不可。"}, {"text": "父は明日会社で物の調達をした。", "explanation": "テンスの誤り：「明日」と過去形「した」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "必要な道具は自分で調達するした。", "corrected_sentence": "必要な道具は自分で調達した。", "error_description": "活用の誤り：「するした」という形はない。過去は「調達した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41341, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「調達する」の目的語「木材」を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示し、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、「調達する」とは結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、「木材に調達する」は非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「調達する」の目的語「木材」を示す。", "で": "手段・場所を示し、目的語にならない。", "へ": "方向を示し、「調達する」とは結びつかない。", "に": "着点を示し、「木材に調達する」は非文。"}, "error_tags": {"で": "instrument", "へ": "direction", "に": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39691, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "製作", "is_correct": true, "explanation": "「せいさく」：道具や機械などの物を作ること。"}, {"text": "生産", "is_correct": false, "explanation": "「せいさん」：最後の「く」が「ん」に変わる一モーラ差。"}, {"text": "制裁", "is_correct": false, "explanation": "「せいさい」：最後の「く」が「い」に変わる一モーラ差。"}, {"text": "性格", "is_correct": false, "explanation": "「せいかく」：三つ目の「さ」が「か」に変わる一モーラ差。"}, {"text": "詮索", "is_correct": false, "explanation": "「せんさく」：二つ目の「い」が「ん」に変わる一モーラ差。"}], "explanations": {"製作": "「せいさく」：道具や機械などの物を作ること。", "生産": "「せいさん」：最後の「く」が「ん」に変わる一モーラ差。", "制裁": "「せいさい」：最後の「く」が「い」に変わる一モーラ差。", "性格": "「せいかく」：三つ目の「さ」が「か」に変わる一モーラ差。", "詮索": "「せんさく」：二つ目の「い」が「ん」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "製作"}, "level_3": {"options": [{"text": "製作", "is_correct": true, "explanation": "意味：Tシャツという物を作ったことを表す。"}, {"text": "建設", "is_correct": false, "explanation": "連語：建物を建てる語で、Tシャツとは結びつかない。"}, {"text": "栽培", "is_correct": false, "explanation": "意味：植物を育てる語で、Tシャツには使えない。"}, {"text": "演奏", "is_correct": false, "explanation": "意味：音楽を奏でる語で、Tシャツを目的語にとれない。"}], "explanations": {"製作": "意味：Tシャツという物を作ったことを表す。", "建設": "連語：建物を建てる語で、Tシャツとは結びつかない。", "栽培": "意味：植物を育てる語で、Tシャツには使えない。", "演奏": "意味：音楽を奏でる語で、Tシャツを目的語にとれない。"}, "sentence_index": 0, "correct_answer": "製作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このいすの製作を三日かかった。", "explanation": "助詞の誤り：「かかる」は「〜に」をとる。"}, {"text": "このいすの製作に三枚かかった。", "explanation": "助数詞の誤り：期間は「枚」では数えない。「三日」。"}, {"text": "このいすの製作に明日三日かかった。", "explanation": "テンスの誤り：「明日」と過去形「かかった」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
