INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39691, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「おいて」と結びつき、場所を示す「〜において」を作る。"}, {"text": "を", "is_correct": false, "explanation": "「をおいて」は「除いて」の意味になり、場所を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「でおいて」という形はなく非文。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、「おいて」と結びつかない。"}], "correct_answer": "に", "explanations": {"に": "「おいて」と結びつき、場所を示す「〜において」を作る。", "を": "「をおいて」は「除いて」の意味になり、場所を表せない。", "で": "「でおいて」という形はなく非文。", "が": "主格になり、「おいて」と結びつかない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "が": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39691, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "製作", "is_correct": true, "explanation": "「せいさく」：物を作ること。"}, {"text": "制約", "is_correct": false, "explanation": "「せいやく」：「さ」が「や」になった一モーラ差（条件で縛ること）。"}, {"text": "静寂", "is_correct": false, "explanation": "「せいじゃく」：「さ」が「じゃ」になった一モーラ差（静けさ）。"}, {"text": "詮索", "is_correct": false, "explanation": "「せんさく」：「い」が「ん」になった一モーラ差（細かく調べること）。"}, {"text": "性格", "is_correct": false, "explanation": "「せいかく」：「さ」が「か」になった一モーラ差（人の性質）。"}], "explanations": {"製作": "「せいさく」：物を作ること。", "制約": "「せいやく」：「さ」が「や」になった一モーラ差（条件で縛ること）。", "静寂": "「せいじゃく」：「さ」が「じゃ」になった一モーラ差（静けさ）。", "詮索": "「せんさく」：「い」が「ん」になった一モーラ差（細かく調べること）。", "性格": "「せいかく」：「さ」が「か」になった一モーラ差（人の性質）。"}, "sentence_index": null, "correct_answer": "製作"}, "level_3": {"options": [{"text": "製作", "is_correct": true, "explanation": "意味：模型を作ることが趣味であることを表す。"}, {"text": "栽培", "is_correct": false, "explanation": "連語：模型は植物ではないので育てられない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：模型は食べ物ではなく料理できない。"}, {"text": "建設", "is_correct": false, "explanation": "連語：建設は大きな建物に使い、模型には合わない。"}], "explanations": {"製作": "意味：模型を作ることが趣味であることを表す。", "栽培": "連語：模型は植物ではないので育てられない。", "料理": "意味：模型は食べ物ではなく料理できない。", "建設": "連語：建設は大きな建物に使い、模型には合わない。"}, "sentence_index": 6, "correct_answer": "製作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は時計の製作がしていた。", "explanation": "助詞の誤り：「する」の目的語は「を」。"}, {"text": "祖父は明日時計の製作をしていた。", "explanation": "テンスの誤り：「明日」と過去の「していた」が合わない。"}, {"text": "祖父は二匹の時計の製作をしていた。", "explanation": "助数詞の誤り：時計は「匹」ではなく「個」で数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
