INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39691, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「製作する」の目的語「部品」を示す。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、目的語にならない。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、能動の「製作する」では部品が作る側になってしまう。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、「製作する」と結びつかない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「製作する」の目的語「部品」を示す。", "に": "着点を示し、目的語にならない。", "が": "主格になり、能動の「製作する」では部品が作る側になってしまう。", "へ": "方向を示し、「製作する」と結びつかない。"}, "error_tags": {"に": "location_vs_target", "が": "object_marking", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38063, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美術", "is_correct": true, "explanation": "「びじゅつ」：絵画や彫刻など目で見る芸術。"}, {"text": "技術", "is_correct": false, "explanation": "ぎじゅつ：最初のモーラ「び」が「ぎ」に変わる一モーラ差。"}, {"text": "記述", "is_correct": false, "explanation": "きじゅつ：「び」が「き」に変わる一モーラ差。"}, {"text": "武術", "is_correct": false, "explanation": "ぶじゅつ：「び」が「ぶ」に変わる一モーラ差（母音の違い）。"}, {"text": "秘術", "is_correct": false, "explanation": "ひじゅつ：「び」が「ひ」になる清濁の対立。"}], "explanations": {"美術": "「びじゅつ」：絵画や彫刻など目で見る芸術。", "技術": "ぎじゅつ：最初のモーラ「び」が「ぎ」に変わる一モーラ差。", "記述": "きじゅつ：「び」が「き」に変わる一モーラ差。", "武術": "ぶじゅつ：「び」が「ぶ」に変わる一モーラ差（母音の違い）。", "秘術": "ひじゅつ：「び」が「ひ」になる清濁の対立。"}, "sentence_index": null, "correct_answer": "美術"}, "level_3": {"options": [{"text": "美術", "is_correct": true, "explanation": "意味：デザインを担当するのは絵やデザインを学ぶ「美術大学」の学生が自然。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「天気大学」という大学はなく、意味をなさない。"}, {"text": "台所", "is_correct": false, "explanation": "意味：「台所大学」という大学はなく、意味をなさない。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：「散歩大学」という大学はなく、意味をなさない。"}], "explanations": {"美術": "意味：デザインを担当するのは絵やデザインを学ぶ「美術大学」の学生が自然。", "天気": "意味：「天気大学」という大学はなく、意味をなさない。", "台所": "意味：「台所大学」という大学はなく、意味をなさない。", "散歩": "意味：「散歩大学」という大学はなく、意味をなさない。"}, "sentence_index": 0, "correct_answer": "美術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は美術を一番好きな教科です。", "explanation": "助詞の誤り：「好きな教科」の対象は「が」で示す。「美術が」が正しい。"}, {"text": "私は明日、美術が一番好きな教科でした。", "explanation": "テンスの誤り：「明日」と過去形「でした」が合わない。"}, {"text": "私は二枚の美術が一番好きな教科です。", "explanation": "助数詞の誤り：教科としての美術は「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38063, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は美術館で美術を飲んだ。", "corrected_sentence": "私は美術館で美術を楽しんだ。", "error_description": "語彙（動詞）の誤り：美術は「飲む」ものではなく、鑑賞して楽しむもの。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38063, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に向き合う」：向き合う相手を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「向き合う」は対象を「を」でとらない。"}, {"text": "が", "is_correct": false, "explanation": "「画用紙が向き合う」となり主語がずれる。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は文意に合わない。"}], "correct_answer": "に", "explanations": {"に": "「〜に向き合う」：向き合う相手を「に」で示す。", "を": "「向き合う」は対象を「を」でとらない。", "が": "「画用紙が向き合う」となり主語がずれる。", "より": "比較の「より」は文意に合わない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "より": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38063, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "美術", "is_correct": true, "explanation": "「びじゅつ」：目で見て美しさを表す芸術。"}, {"text": "手術", "is_correct": false, "explanation": "「しゅじゅつ」：「び」が「しゅ」になった一モーラ差（体を治す処置）。"}, {"text": "呪術", "is_correct": false, "explanation": "「じゅじゅつ」：「び」が「じゅ」になった一モーラ差（まじない）。"}, {"text": "奇術", "is_correct": false, "explanation": "「きじゅつ」：「び」が「き」になった一モーラ差（手品）。"}, {"text": "武術", "is_correct": false, "explanation": "「ぶじゅつ」：「び」が「ぶ」になった一モーラ差（武道）。"}], "explanations": {"美術": "「びじゅつ」：目で見て美しさを表す芸術。", "手術": "「しゅじゅつ」：「び」が「しゅ」になった一モーラ差（体を治す処置）。", "呪術": "「じゅじゅつ」：「び」が「じゅ」になった一モーラ差（まじない）。", "奇術": "「きじゅつ」：「び」が「き」になった一モーラ差（手品）。", "武術": "「ぶじゅつ」：「び」が「ぶ」になった一モーラ差（武道）。"}, "sentence_index": null, "correct_answer": "美術"}, "level_3": {"options": [{"text": "美術", "is_correct": true, "explanation": "意味：「美術の本」は絵画や彫刻についての本。"}, {"text": "とても", "is_correct": false, "explanation": "文法：副詞「とても」は「の」で名詞を修飾できない。"}, {"text": "すぐ", "is_correct": false, "explanation": "文法：「すぐの本」は名詞を修飾する形にならない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "文法：副詞「ゆっくり」は「の」で名詞を修飾できない。"}], "explanations": {"美術": "意味：「美術の本」は絵画や彫刻についての本。", "とても": "文法：副詞「とても」は「の」で名詞を修飾できない。", "すぐ": "文法：「すぐの本」は名詞を修飾する形にならない。", "ゆっくり": "文法：副詞「ゆっくり」は「の」で名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "美術"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は美術を有名になった。", "explanation": "助詞の誤り：有名になった理由は「で」で示す。「美術を」は非文。"}, {"text": "この町は明日美術で有名になった。", "explanation": "テンスの誤り：「明日」と過去形「なった」が合わない。"}, {"text": "この町は三匹の美術で有名になった。", "explanation": "助数詞の誤り：美術を「匹」で数えることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
