INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38063, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に関心を持つ」：関心の対象を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「関心を持つ」の対象を「を」で示すと「を」が重なり非文。"}, {"text": "で", "is_correct": false, "explanation": "「美術で関心を持つ」は対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「美術が強い関心を持つ」では美術が主体になってしまう。"}], "correct_answer": "に", "explanations": {"に": "「〜に関心を持つ」：関心の対象を「に」で示す。", "を": "「関心を持つ」の対象を「を」で示すと「を」が重なり非文。", "で": "「美術で関心を持つ」は対象を表せない。", "が": "「美術が強い関心を持つ」では美術が主体になってしまう。"}, "error_tags": {"を": "object_marking", "で": "instrument", "が": "topic_vs_subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
