INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37381, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向上", "is_correct": true, "explanation": "音声どおりの正しい表記。"}, {"text": "交渉", "is_correct": false, "explanation": "こうしょう：「じょ」が「しょ」になる清濁の対立。"}, {"text": "控除", "is_correct": false, "explanation": "こうじょ：最後の長音がない長短の対立。"}, {"text": "構造", "is_correct": false, "explanation": "こうぞう：「じょ」が「ぞ」に変わる一モーラ差。"}, {"text": "香料", "is_correct": false, "explanation": "こうりょう：「じょ」が「りょ」に変わる一モーラ差。"}, {"text": "強情", "is_correct": false, "explanation": "ごうじょう：「こ」が「ご」になる清濁の対立。"}], "explanations": {"向上": "音声どおりの正しい表記。", "交渉": "こうしょう：「じょ」が「しょ」になる清濁の対立。", "控除": "こうじょ：最後の長音がない長短の対立。", "構造": "こうぞう：「じょ」が「ぞ」に変わる一モーラ差。", "香料": "こうりょう：「じょ」が「りょ」に変わる一モーラ差。", "強情": "ごうじょう：「こ」が「ご」になる清濁の対立。"}, "sentence_index": null, "correct_answer": "向上"}, "level_3": {"options": [{"text": "向上", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "出発", "is_correct": false, "explanation": "意味：「収益性を出発させる」は意味が通らない。"}, {"text": "卒業", "is_correct": false, "explanation": "連語：「収益性を卒業させる」は不自然。"}, {"text": "到着", "is_correct": false, "explanation": "意味：収益性は到着させるものではない。"}], "explanations": {"向上": "文脈に合う正しい語。", "出発": "意味：「収益性を出発させる」は意味が通らない。", "卒業": "連語：「収益性を卒業させる」は不自然。", "到着": "意味：収益性は到着させるものではない。"}, "sentence_index": 0, "correct_answer": "向上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机が向上して二本になった。", "explanation": "意味の誤り：机は能力や状態の向上をしない。"}, {"text": "向上を一冊買った。", "explanation": "助数詞・意味の誤り：向上は物ではない。"}, {"text": "部屋の温度が向上した。", "explanation": "連語の誤り：温度は「上昇する」もので「向上」は能力や質に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_e