INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36873, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に入る正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「高校が卒業した」では高校が主体になる。"}, {"text": "に", "is_correct": false, "explanation": "「高校に卒業した」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「卒業する」と結びつかない。"}], "correct_answer": "を", "explanations": {"を": "この位置に入る正しい助詞。", "が": "「高校が卒業した」では高校が主体になる。", "に": "「高校に卒業した」は非文。", "へ": "方向の「へ」は「卒業する」と結びつかない。"}, "error_tags": {"が": "topic_subject", "に": "case_confusion", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無機", "is_correct": true, "explanation": "生物に由来しないもの。有機の対義語。"}, {"text": "自然", "is_correct": false, "explanation": "類義に近く、対義語ではない。"}, {"text": "新鮮", "is_correct": false, "explanation": "別の性質。"}, {"text": "安全", "is_correct": false, "explanation": "無関係な性質。"}], "correct_answer": "無機", "explanations": {"無機": "生物に由来しないもの。有機の対義語。", "自然": "類義に近く、対義語ではない。", "新鮮": "別の性質。", "安全": "無関係な性質。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
