INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35983, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同時", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "当時", "is_correct": false, "explanation": "とうじ。「ど」が清音「と」になる清濁の違い"}, {"text": "動詞", "is_correct": false, "explanation": "どうし。「じ」が「し」になる清濁の違い"}, {"text": "道具", "is_correct": false, "explanation": "どうぐ。最後の「じ」が「ぐ」になる一モーラ差"}, {"text": "工事", "is_correct": false, "explanation": "こうじ。最初の「ど」が「こ」になる一モーラ差"}], "explanations": {"同時": "音声どおりの語。", "当時": "とうじ。「ど」が清音「と」になる清濁の違い", "動詞": "どうし。「じ」が「し」になる清濁の違い", "道具": "どうぐ。最後の「じ」が「ぐ」になる一モーラ差", "工事": "こうじ。最初の「ど」が「こ」になる一モーラ差"}, "sentence_index": null, "correct_answer": "同時"}, "level_3": {"options": [{"text": "同時", "is_correct": true, "explanation": "文意に合う唯一の語。"}, {"text": "偶然", "is_correct": false, "explanation": "意味：「偶然に企図する」は企図と矛盾する。"}, {"text": "一瞬", "is_correct": false, "explanation": "連語：「一瞬に企図する」とは言わない"}, {"text": "永久", "is_correct": false, "explanation": "連語：「永久に企図する」は不自然"}], "explanations": {"同時": "文意に合う唯一の語。", "偶然": "意味：「偶然に企図する」は企図と矛盾する。", "一瞬": "連語：「一瞬に企図する」とは言わない", "永久": "連語：「永久に企図する」は不自然"}, "sentence_index": 0, "correct_answer": "同時"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアが開くと同時を、犬が走り出した。", "explanation": "助詞の誤り：「同時に」とすべき"}, {"text": "二人は同時が手を挙げた。", "explanation": "助詞の誤り：副詞的に使うときは「同時に」"}, {"text": "ドアが開くのを同時に、犬が走り出した。", "explanation": "助詞の誤り：「開くと同時に」とすべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
