INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35969, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "必要", "is_correct": true, "explanation": "正解。「必要」は「ひつよう」と読む。"}, {"text": "ひよう", "is_correct": false, "explanation": "「ひよう」は音が似ているが別の語。"}, {"text": "ひこう", "is_correct": false, "explanation": "「ひこう」（飛行）は音が似ているが別の語。"}, {"text": "しよう", "is_correct": false, "explanation": "「しよう」は音が似ているが別の語。"}, {"text": "ひつじ", "is_correct": false, "explanation": "「ひつじ」は音が似ているが別の語。"}, {"text": "にちよう", "is_correct": false, "explanation": "「にちよう」は音が似ているが別の語。"}], "explanations": {"必要": "正解。「必要」は「ひつよう」と読む。", "ひよう": "「ひよう」は音が似ているが別の語。", "ひこう": "「ひこう」（飛行）は音が似ているが別の語。", "しよう": "「しよう」は音が似ているが別の語。", "ひつじ": "「ひつじ」は音が似ているが別の語。", "にちよう": "「にちよう」は音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "必要"}, "level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "目的のために欠かせない要素だけを残す、という意味になる。"}, {"text": "有名", "is_correct": false, "explanation": "有名な要素を残しても穏やかな日常とは結びつかない。"}, {"text": "危険", "is_correct": false, "explanation": "危険な要素だけを残すのは文意に反する。"}, {"text": "複雑", "is_correct": false, "explanation": "複雑な要素だけを残すとミニマリストの思想に反する。"}], "explanations": {"必要": "目的のために欠かせない要素だけを残す、という意味になる。", "有名": "有名な要素を残しても穏やかな日常とは結びつかない。", "危険": "危険な要素だけを残すのは文意に反する。", "複雑": "複雑な要素だけを残すとミニマリストの思想に反する。"}, "sentence_index": 0, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本は必要に読んでください。", "explanation": "「必要に」は副詞的に使えない。「必ず」が正しい。"}, {"text": "彼はとても必要な人に走った。", "explanation": "「必要」が動作と結びつかず意味が通らない。"}, {"text": "昨日の天気は必要でした。", "explanation": "天気が「どうしても要る」という意味にならず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35969, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行には必要の物だけを持っていく。", "corrected_sentence": "旅行には必要な物だけを持っていく。", "error_description": "「必要」が名詞を修飾するときは「必要な」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "必要", "is_correct": true, "explanation": "連体形「必要な」の語幹部分。文中の形そのもの。"}, {"text": "必要だ", "is_correct": false, "explanation": "終止形。名詞の前には置けない。"}, {"text": "必要で", "is_correct": false, "explanation": "連用形。名詞を修飾できない。"}, {"text": "必要だった", "is_correct": false, "explanation": "過去形。ここでは文脈に合わない。"}], "correct_form": "必要", "base_form": "必要だ", "form_label": "語幹（連体形「必要な」の一部）", "sentence_index": 1, "explanations": {"必要": "連体形「必要な」の語幹部分。文中の形そのもの。", "必要だ": "終止形。名詞の前には置けない。", "必要で": "連用形。名詞を修飾できない。", "必要だった": "過去形。ここでは文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
