INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35969, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "必要", "is_correct": true, "explanation": "正解。「必要」は「ひつよう」と読む。"}, {"text": "きゅうよう", "is_correct": false, "explanation": "「きゅうよう」（急用）は音が似ているが別の語。"}, {"text": "しつよう", "is_correct": false, "explanation": "「しつよう」は音が似ているが別の語。"}, {"text": "ひっし", "is_correct": false, "explanation": "「ひっし」は音が似ているが別の語。"}, {"text": "ちょうよう", "is_correct": false, "explanation": "「ちょうよう」は音が似ているが別の語。"}, {"text": "ひつぜん", "is_correct": false, "explanation": "「ひつぜん」は音が似ているが別の語。"}], "explanations": {"必要": "正解。「必要」は「ひつよう」と読む。", "きゅうよう": "「きゅうよう」（急用）は音が似ているが別の語。", "しつよう": "「しつよう」は音が似ているが別の語。", "ひっし": "「ひっし」は音が似ているが別の語。", "ちょうよう": "「ちょうよう」は音が似ているが別の語。", "ひつぜん": "「ひつぜん」は音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "必要"}, "level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "本当に要るのかを考えた、という意味。"}, {"text": "元気", "is_correct": false, "explanation": "「本当に元気なのか考えた」は「それ」と合わない。"}, {"text": "静か", "is_correct": false, "explanation": "物事が静かかどうかを考える文脈ではない。"}, {"text": "上手", "is_correct": false, "explanation": "「それ」が上手かは不自然。"}], "explanations": {"必要": "本当に要るのかを考えた、という意味。", "元気": "「本当に元気なのか考えた」は「それ」と合わない。", "静か": "物事が静かかどうかを考える文脈ではない。", "上手": "「それ」が上手かは不自然。"}, "sentence_index": 6, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎朝必要を食べます。", "explanation": "「必要」は食べ物ではない。"}, {"text": "彼女は必要に笑った。", "explanation": "「必要に」は動作の様子を表せない。"}, {"text": "この山は必要が高い。", "explanation": "「必要」は高さを持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valida