INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35183, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "この文の構造に合う正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、この位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "場所・対象を示す助詞で、ここでは不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す助詞で、ここでは意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "この文の構造に合う正しい助詞。", "を": "目的語を示す助詞で、この位置には合わない。", "に": "場所・対象を示す助詞で、ここでは不自然。", "で": "手段を表す助詞で、ここでは意味が通らない。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "原因", "is_correct": true, "explanation": "結果の元になるもの。反対語。"}, {"text": "結末", "is_correct": false, "explanation": "終わりの状態で、類義語。"}, {"text": "成績", "is_correct": false, "explanation": "テストの結果などに近い語。"}, {"text": "答え", "is_correct": false, "explanation": "結果に近い使い方もあり、反対ではない。"}], "correct_answer": "原因", "explanations": {"原因": "結果の元になるもの。反対語。", "結末": "終わりの状態で、類義語。", "成績": "テストの結果などに近い語。", "答え": "結果に近い使い方もあり、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
