INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36005, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精密", "is_correct": true, "explanation": "せいみつ。"}, {"text": "生命", "is_correct": false, "explanation": "せいめい：音が似ている。"}, {"text": "正式", "is_correct": false, "explanation": "せいしき：音が似ている。"}, {"text": "静物", "is_correct": false, "explanation": "せいぶつ：音が似ている。"}, {"text": "性質", "is_correct": false, "explanation": "せいしつ：音が似ている。"}, {"text": "清掃", "is_correct": false, "explanation": "せいそう：最初が同じ。"}], "explanations": {"精密": "せいみつ。", "生命": "せいめい：音が似ている。", "正式": "せいしき：音が似ている。", "静物": "せいぶつ：音が似ている。", "性質": "せいしつ：音が似ている。", "清掃": "せいそう：最初が同じ。"}, "sentence_index": null, "correct_answer": "精密"}, "level_3": {"options": [{"text": "精密", "is_correct": true, "explanation": "精密農業＝データで細かく管理する農業。"}, {"text": "丁寧", "is_correct": false, "explanation": "丁寧農業とは言わない。"}, {"text": "簡単", "is_correct": false, "explanation": "簡単農業は専門語ではない。"}, {"text": "重要", "is_correct": false, "explanation": "重要農業は不自然。"}], "explanations": {"精密": "精密農業＝データで細かく管理する農業。", "丁寧": "丁寧農業とは言わない。", "簡単": "簡単農業は専門語ではない。", "重要": "重要農業は不自然。"}, "sentence_index": 0, "correct_answer": "精密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は精密に笑った。", "explanation": "笑い方に精密は使わない。"}, {"text": "今日は精密な天気だ。", "explanation": "天気に精密は合わない。"}, {"text": "このスープは精密においしい。", "explanation": "味の程度に精密は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
