INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36391, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一方", "is_correct": true, "explanation": "正解：「いっぽう」と読む語。"}, {"text": "一本", "is_correct": false, "explanation": "「いっぽん」と読み、音が似ているが別の語。"}, {"text": "一歩", "is_correct": false, "explanation": "「いっぽ」と読み、音が似ているが別の語。"}, {"text": "立方", "is_correct": false, "explanation": "「りっぽう」と読み、音が似ているが別の語。"}, {"text": "日報", "is_correct": false, "explanation": "「にっぽう」と読み、音が似ているが別の語。"}, {"text": "一服", "is_correct": false, "explanation": "「いっぷく」と読み、音が似ているが別の語。"}], "explanations": {"一方": "正解：「いっぽう」と読む語。", "一本": "「いっぽん」と読み、音が似ているが別の語。", "一歩": "「いっぽ」と読み、音が似ているが別の語。", "立方": "「りっぽう」と読み、音が似ているが別の語。", "日報": "「にっぽう」と読み、音が似ているが別の語。", "一服": "「いっぷく」と読み、音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "一方"}, "level_3": {"options": [{"text": "一方", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "さらに", "is_correct": false, "explanation": "前と対比せず、付け加える意味になる。"}, {"text": "だから", "is_correct": false, "explanation": "理由と結果を表し、対比にならない。"}, {"text": "例えば", "is_correct": false, "explanation": "例を挙げる言葉で、文脈に合わない。"}], "explanations": {"一方": "文脈に合う唯一の語。", "さらに": "前と対比せず、付け加える意味になる。", "だから": "理由と結果を表し、対比にならない。", "例えば": "例を挙げる言葉で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "一方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキを一方食べた。", "explanation": "「一方」は数量を表す語として使えない。"}, {"text": "一方、雨が降ったので、傘を差した。", "explanation": "理由と結果の関係で、対比ではない。"}, {"text": "私は一方な人だ。", "explanation": "「一方」は人の性質を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, vali