INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51562, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」がこの文で正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「肉体をとても強い」は非文。"}, {"text": "に", "is_correct": false, "explanation": "「肉体にとても強い」は意味が変わる。"}, {"text": "へ", "is_correct": false, "explanation": "「肉体へとても強い」は非文。"}], "correct_answer": "は", "explanations": {"は": "「は」がこの文で正しい助詞。", "を": "「肉体をとても強い」は非文。", "に": "「肉体にとても強い」は意味が変わる。", "へ": "「肉体へとても強い」は非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38343, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "実装", "is_correct": true, "explanation": "正しい語。音がぴったり合う。"}, {"text": "失踪", "is_correct": false, "explanation": "「しっそう」と読み、音が少し違う。"}, {"text": "自走", "is_correct": false, "explanation": "「じそう」と読み、音が少し違う。"}, {"text": "地層", "is_correct": false, "explanation": "「ちそう」と読み、音が少し違う。"}, {"text": "実存", "is_correct": false, "explanation": "「じつぞん」と読み、音が少し違う。"}], "explanations": {"実装": "正しい語。音がぴったり合う。", "失踪": "「しっそう」と読み、音が少し違う。", "自走": "「じそう」と読み、音が少し違う。", "地層": "「ちそう」と読み、音が少し違う。", "実存": "「じつぞん」と読み、音が少し違う。"}, "sentence_index": null, "correct_answer": "実装"}, "level_3": {"options": [{"text": "実装", "is_correct": true, "explanation": "「社会実装」で技術を社会の中で実際に使える形にすること。"}, {"text": "実感", "is_correct": false, "explanation": "「社会実感」とは言わない。"}, {"text": "実話", "is_correct": false, "explanation": "「社会実話」とは言わない。"}, {"text": "実家", "is_correct": false, "explanation": "「社会実家」とは言わない。"}], "explanations": {"実装": "「社会実装」で技術を社会の中で実際に使える形にすること。", "実感": "「社会実感」とは言わない。", "実話": "「社会実話」とは言わない。", "実家": "「社会実家」とは言わない。"}, "sentence_index": 0, "correct_answer": "実装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、牛乳を実装して飲む。", "explanation": "「実装」は仕組みを作ることで、飲み物には使わない。"}, {"text": "昨日、友だちと公園で実装した。", "explanation": "遊ぶ意味では使わない。"}, {"text": "彼女は赤い服を実装している。", "explanation": "服を着る意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
