INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38231, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「支える」の目的語を表す。"}, {"text": "に", "is_correct": false, "explanation": "「転換に支える」は非文。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」ではこの位置で非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「支える」に合わない。"}], "correct_answer": "を", "explanations": {"を": "「支える」の目的語を表す。", "に": "「転換に支える」は非文。", "で": "手段の「で」ではこの位置で非文。", "へ": "方向の「へ」は「支える」に合わない。"}, "error_tags": {"に": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "維持", "is_correct": true, "explanation": "状態を変えずに保つことで、「転換」と反対。"}, {"text": "変更", "is_correct": false, "explanation": "変えることで、類義語に近い。"}, {"text": "展開", "is_correct": false, "explanation": "話や物事が広がることで、反対ではない。"}, {"text": "移動", "is_correct": false, "explanation": "場所が変わることで、反対ではない。"}], "correct_answer": "維持", "explanations": {"維持": "状態を変えずに保つことで、「転換」と反対。", "変更": "変えることで、類義語に近い。", "展開": "話や物事が広がることで、反対ではない。", "移動": "場所が変わることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38231, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "転換", "is_correct": true, "explanation": "正しい語。音がぴったり合う。"}, {"text": "変換", "is_correct": false, "explanation": "「へんかん」と読み、音が少し違う。"}, {"text": "転校", "is_correct": false, "explanation": "「てんこう」と読み、音が少し違う。"}, {"text": "点眼", "is_correct": false, "explanation": "「てんがん」と読み、音が少し違う。"}, {"text": "単館", "is_correct": false, "explanation": "「たんかん」と読み、音が少し違う。"}], "explanations": {"転換": "正しい語。音がぴったり合う。", "変換": "「へんかん」と読み、音が少し違う。", "転校": "「てんこう」と読み、音が少し違う。", "点眼": "「てんがん」と読み、音が少し違う。", "単館": "「たんかん」と読み、音が少し違う。"}, "sentence_index": null, "correct_answer": "転換"}, "level_3": {"options": [{"text": "転換", "is_correct": true, "explanation": "車が向きを変えた、という意味になる。"}, {"text": "運転", "is_correct": false, "explanation": "「方向を運転した」とは言わない。"}, {"text": "停止", "is_correct": false, "explanation": "「方向を停止した」とは言わない。"}, {"text": "駐車", "is_correct": false, "explanation": "「方向を駐車した」とは言わない。"}], "explanations": {"転換": "車が向きを変えた、という意味になる。", "運転": "「方向を運転した」とは言わない。", "停止": "「方向を停止した」とは言わない。", "駐車": "「方向を駐車した」とは言わない。"}, "sentence_index": 6, "correct_answer": "転換"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転換を一杯飲んで、休みました。", "explanation": "飲み物ではない。"}, {"text": "庭にきれいな転換が咲いた。", "explanation": "花ではない。"}, {"text": "転換で手を洗ってください。", "explanation": "洗う道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
