INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38231, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「必要だ」の対象（主語）を表す。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」はこの位置で非文。"}], "correct_answer": "が", "explanations": {"が": "「必要だ」の対象（主語）を表す。", "と": "並列の「と」では意味が通らない。", "で": "手段の「で」では意味が通らない。", "へ": "方向の「へ」はこの位置で非文。"}, "error_tags": {"と": "listing", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "継続", "is_correct": true, "explanation": "同じ状態を続けることで、「転換」と反対。"}, {"text": "切り替え", "is_correct": false, "explanation": "変えることで、類義語。"}, {"text": "出発", "is_correct": false, "explanation": "出かけることで、反対ではない。"}, {"text": "完成", "is_correct": false, "explanation": "作り終わることで、反対ではない。"}], "correct_answer": "継続", "explanations": {"継続": "同じ状態を続けることで、「転換」と反対。", "切り替え": "変えることで、類義語。", "出発": "出かけることで、反対ではない。", "完成": "作り終わることで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37601, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支える", "is_correct": true, "explanation": "正しい語。音がぴったり合う。"}, {"text": "抑える", "is_correct": false, "explanation": "「おさえる」と読み、音が少し違う。"}, {"text": "栄える", "is_correct": false, "explanation": "「さかえる」と読み、音が少し違う。"}, {"text": "差し替える", "is_correct": false, "explanation": "「さしかえる」と読み、音が少し違う。"}, {"text": "捕まえる", "is_correct": false, "explanation": "「つかまえる」と読み、音が少し違う。"}], "explanations": {"支える": "正しい語。音がぴったり合う。", "抑える": "「おさえる」と読み、音が少し違う。", "栄える": "「さかえる」と読み、音が少し違う。", "差し替える": "「さしかえる」と読み、音が少し違う。", "捕まえる": "「つかまえる」と読み、音が少し違う。"}, "sentence_index": null, "correct_answer": "支える"}, "level_3": {"options": [{"text": "支える", "is_correct": true, "explanation": "産業構造の転換を下から安定させる、という意味になる。"}, {"text": "壊す", "is_correct": false, "explanation": "「要石」は支えるもので、「壊す要石」は意味が通らない。"}, {"text": "忘れる", "is_correct": false, "explanation": "「転換を忘れる要石」は意味が通らない。"}, {"text": "眠る", "is_correct": false, "explanation": "自動詞で「転換を」をとれない。"}], "explanations": {"支える": "産業構造の転換を下から安定させる、という意味になる。", "壊す": "「要石」は支えるもので、「壊す要石」は意味が通らない。", "忘れる": "「転換を忘れる要石」は意味が通らない。", "眠る": "自動詞で「転換を」をとれない。"}, "sentence_index": 0, "correct_answer": "支える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、コーヒーを支えて飲む。", "explanation": "「支える」は倒れないよう保つ意味で、飲み物を作る意味ではない。"}, {"text": "雨が支えて、道がぬれた。", "explanation": "雨が降る意味では使わない。"}, {"text": "彼は駅まで支えて行った。", "explanation": "歩く・走る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
