INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37227, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "エネルギー", "is_correct": true, "explanation": "正しい語。音がぴったり合う。"}, {"text": "アレルギー", "is_correct": false, "explanation": "「あれるぎー」と読み、音が少し違う。"}, {"text": "エレジー", "is_correct": false, "explanation": "「えれじー」と読み、音が少し違う。"}, {"text": "エネミー", "is_correct": false, "explanation": "「えねみー」と読み、音が少し違う。"}, {"text": "エノキ", "is_correct": false, "explanation": "「えのき」と読み、音が少し違う。"}], "explanations": {"エネルギー": "正しい語。音がぴったり合う。", "アレルギー": "「あれるぎー」と読み、音が少し違う。", "エレジー": "「えれじー」と読み、音が少し違う。", "エネミー": "「えねみー」と読み、音が少し違う。", "エノキ": "「えのき」と読み、音が少し違う。"}, "sentence_index": null, "correct_answer": "エネルギー"}, "level_3": {"options": [{"text": "エネルギー", "is_correct": true, "explanation": "「再生可能エネルギー」で太陽や風などから得る力。"}, {"text": "スポーツ", "is_correct": false, "explanation": "「再生可能スポーツ」とは言わない。"}, {"text": "メニュー", "is_correct": false, "explanation": "「再生可能メニュー」とは言わない。"}, {"text": "ニュース", "is_correct": false, "explanation": "「再生可能ニュース」とは言わない。"}], "explanations": {"エネルギー": "「再生可能エネルギー」で太陽や風などから得る力。", "スポーツ": "「再生可能スポーツ」とは言わない。", "メニュー": "「再生可能メニュー」とは言わない。", "ニュース": "「再生可能ニュース」とは言わない。"}, "sentence_index": 0, "correct_answer": "エネルギー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エネルギーを着て、外に出た。", "explanation": "着る物ではない。"}, {"text": "このエネルギーはとても甘い。", "explanation": "味はない。"}, {"text": "エネルギーに手紙を書いた。", "explanation": "人ではないので手紙は書けない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_bat