INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36297, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "計画", "is_correct": true, "explanation": "正解：けいかく。"}, {"text": "性格", "is_correct": false, "explanation": "せいかく：最初の「け」が「せ」に変わる一モーラ差。"}, {"text": "改革", "is_correct": false, "explanation": "かいかく：「け」が「か」に変わる一モーラ差。"}, {"text": "警戒", "is_correct": false, "explanation": "けいかい：最後の「く」が「い」に変わる一モーラ差。"}, {"text": "警官", "is_correct": false, "explanation": "けいかん：最後の「く」が「ん」に変わる一モーラ差。"}], "explanations": {"計画": "正解：けいかく。", "性格": "せいかく：最初の「け」が「せ」に変わる一モーラ差。", "改革": "かいかく：「け」が「か」に変わる一モーラ差。", "警戒": "けいかい：最後の「く」が「い」に変わる一モーラ差。", "警官": "けいかん：最後の「く」が「ん」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "計画"}, "level_3": {"options": [{"text": "計画", "is_correct": true, "explanation": "「計画を立てて実行する」で、前もって考えた手順を表す。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は自分で立てて実行するものではない。"}, {"text": "宿題", "is_correct": false, "explanation": "連語：「宿題を立てる」とは言わない。"}, {"text": "返事", "is_correct": false, "explanation": "連語：「返事を立てて実行する」は不自然。"}], "explanations": {"計画": "「計画を立てて実行する」で、前もって考えた手順を表す。", "天気": "意味：天気は自分で立てて実行するものではない。", "宿題": "連語：「宿題を立てる」とは言わない。", "返事": "連語：「返事を立てて実行する」は不自然。"}, "sentence_index": 0, "correct_answer": "計画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "計画を一杯飲んで、休んだ。", "explanation": "計画は考えで、飲み物ではない。"}, {"text": "庭で計画がワンワンほえている。", "explanation": "計画は動物ではない。"}, {"text": "計画で髪を切った。", "explanation": "計画は道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
