INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36297, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜において」の形で場面を表す。"}, {"text": "で", "is_correct": false, "explanation": "「でおいて」という形はない。"}, {"text": "を", "is_correct": false, "explanation": "「をおいて」では意味が変わり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「がおいて」という形はない。"}], "correct_answer": "に", "explanations": {"に": "「〜において」の形で場面を表す。", "で": "「でおいて」という形はない。", "を": "「をおいて」では意味が変わり、文が成り立たない。", "が": "「がおいて」という形はない。"}, "error_tags": {"で": "instrument", "を": "object_marking", "が": "other"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36297, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "計画", "is_correct": true, "explanation": "正解：けいかく。"}, {"text": "正確", "is_correct": false, "explanation": "せいかく：「け」が「せ」に変わる一モーラ差。"}, {"text": "経歴", "is_correct": false, "explanation": "けいれき：「か」が「れ」に変わる一モーラ差。"}, {"text": "系列", "is_correct": false, "explanation": "けいれつ：「かく」が「れつ」に変わる。"}, {"text": "敬服", "is_correct": false, "explanation": "けいふく：「か」が「ふ」に変わり、「く」は同じ。"}], "explanations": {"計画": "正解：けいかく。", "正確": "せいかく：「け」が「せ」に変わる一モーラ差。", "経歴": "けいれき：「か」が「れ」に変わる一モーラ差。", "系列": "けいれつ：「かく」が「れつ」に変わる。", "敬服": "けいふく：「か」が「ふ」に変わり、「く」は同じ。"}, "sentence_index": null, "correct_answer": "計画"}, "level_3": {"options": [{"text": "計画", "is_correct": true, "explanation": "前もって考えた手順なので、先生に説明できる。"}, {"text": "空気", "is_correct": false, "explanation": "意味：空気をくわしく説明する場面ではない。"}, {"text": "雨", "is_correct": false, "explanation": "意味：雨を先生に説明する文脈に合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "意味：眠気はくわしく説明する対象として不自然。"}], "explanations": {"計画": "前もって考えた手順なので、先生に説明できる。", "空気": "意味：空気をくわしく説明する場面ではない。", "雨": "意味：雨を先生に説明する文脈に合わない。", "眠気": "意味：眠気はくわしく説明する対象として不自然。"}, "sentence_index": 6, "correct_answer": "計画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "計画を着て出かけた。", "explanation": "計画は服ではない。"}, {"text": "計画が空を飛んでいる。", "explanation": "計画は鳥や物ではない。"}, {"text": "計画を冷蔵庫で冷やした。", "explanation": "計画は食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id