INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冷たい", "is_correct": true, "explanation": "正解：つめたい。"}, {"text": "止めたい", "is_correct": false, "explanation": "とめたい：最初の「つ」が「と」に変わる一モーラ差。"}, {"text": "締めたい", "is_correct": false, "explanation": "しめたい：「つ」が「し」に変わる一モーラ差。"}, {"text": "決めたい", "is_correct": false, "explanation": "きめたい：「つ」が「き」に変わる一モーラ差。"}, {"text": "込めたい", "is_correct": false, "explanation": "こめたい：「つ」が「こ」に変わる一モーラ差。"}], "explanations": {"冷たい": "正解：つめたい。", "止めたい": "とめたい：最初の「つ」が「と」に変わる一モーラ差。", "締めたい": "しめたい：「つ」が「し」に変わる一モーラ差。", "決めたい": "きめたい：「つ」が「き」に変わる一モーラ差。", "込めたい": "こめたい：「つ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "冷たい"}, "level_3": {"options": [{"text": "冷たく", "is_correct": true, "explanation": "暑さに疲れた人の喉を潤す飲み物なので「冷たくて」が合う。"}, {"text": "眠く", "is_correct": false, "explanation": "意味：レモネードが眠いことはない。"}, {"text": "若く", "is_correct": false, "explanation": "意味：飲み物に「若い」は使わない。"}, {"text": "痛く", "is_correct": false, "explanation": "意味：飲み物の性質として不適切。"}], "explanations": {"冷たく": "暑さに疲れた人の喉を潤す飲み物なので「冷たくて」が合う。", "眠く": "意味：レモネードが眠いことはない。", "若く": "意味：飲み物に「若い」は使わない。", "痛く": "意味：飲み物の性質として不適切。"}, "sentence_index": 0, "correct_answer": "冷たく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷たい水が一気に飲んだ。", "explanation": "助詞の混同：飲む対象なので「水を」が正しい。"}, {"text": "冬の朝は川の水がとても冷たいかった。", "explanation": "活用の誤り：い形容詞の過去形は「冷たかった」。"}, {"text": "一枚の冷たい水を飲んだ。", "explanation": "助数詞の誤り：水は「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風が冷たいて、手が赤くなった。", "corrected_sentence": "風が冷たくて、手が赤くなった。", "error_description": "活用の誤り：い形容詞のて形は「冷たくて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "冷たさ", "is_correct": true, "explanation": "「など」の前で名詞として働くので、名詞形「冷たさ」。"}, {"text": "冷たい", "is_correct": false, "explanation": "連体形は名詞が後に必要で、「冷たいなど」は不自然。"}, {"text": "冷たく", "is_correct": false, "explanation": "連用形は「の冷たく」と名詞を受けられない。"}, {"text": "冷たかった", "is_correct": false, "explanation": "過去形は「厳冬の」に続けられない。"}], "correct_form": "冷たさ", "base_form": "冷たい", "form_label": "派生", "sentence_index": 1, "explanations": {"冷たさ": "「など」の前で名詞として働くので、名詞形「冷たさ」。", "冷たい": "連体形は名詞が後に必要で、「冷たいなど」は不自然。", "冷たく": "連用形は「の冷たく」と名詞を受けられない。", "冷たかった": "過去形は「厳冬の」に続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熱い", "is_correct": true, "explanation": "温度が高いことで、冷たいの対義語。"}, {"text": "寒い", "is_correct": false, "explanation": "気温の低さを表し、対義ではない。"}, {"text": "涼しい", "is_correct": false, "explanation": "ほどよく低い温度で、対義ではない。"}, {"text": "ぬるい", "is_correct": false, "explanation": "温度が中途半端なことで、対義語ではない。"}], "correct_answer": "熱い", "explanations": {"熱い": "温度が高いことで、冷たいの対義語。", "寒い": "気温の低さを表し、対義ではない。", "涼しい": "ほどよく低い温度で、対義ではない。", "ぬるい": "温度が中途半端なことで、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冷たい", "is_correct": true, "explanation": "正解：つめたい。"}, {"text": "攻めたい", "is_correct": false, "explanation": "せめたい：「つ」が「せ」に変わる一モーラ差。"}, {"text": "染めたい", "is_correct": false, "explanation": "そめたい：「つ」が「そ」に変わる一モーラ差。"}, {"text": "褒めたい", "is_correct": false, "explanation": "ほめたい：「つ」が「ほ」に変わる一モーラ差。"}], "explanations": {"冷たい": "正解：つめたい。", "攻めたい": "せめたい：「つ」が「せ」に変わる一モーラ差。", "染めたい": "そめたい：「つ」が「そ」に変わる一モーラ差。", "褒めたい": "ほめたい：「つ」が「ほ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "冷たい"}, "level_3": {"options": [{"text": "冷たい", "is_correct": true, "explanation": "顔にあてるタオルの温度として自然。"}, {"text": "悲しい", "is_correct": false, "explanation": "意味：タオルは悲しくない。"}, {"text": "遅い", "is_correct": false, "explanation": "意味：タオルの性質に合わない。"}, {"text": "若い", "is_correct": false, "explanation": "意味：物に「若い」は使わない。"}], "explanations": {"冷たい": "顔にあてるタオルの温度として自然。", "悲しい": "意味：タオルは悲しくない。", "遅い": "意味：タオルの性質に合わない。", "若い": "意味：物に「若い」は使わない。"}, "sentence_index": 6, "correct_answer": "冷たい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓ガラスを冷たくなっている。", "explanation": "助詞の混同：「なる」の主語なので「窓ガラスが」。"}, {"text": "雪にさわったら、明日すごく冷たかった。", "explanation": "アスペクトの誤り：「明日」と過去形が合わない。"}, {"text": "冷たい三冊の水を飲んだ。", "explanation": "助数詞の誤り：水は「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷たいのアイスを食べられてうれしい。", "corrected_sentence": "冷たいアイスを食べられてうれしい。", "error_description": "接続の誤り：い形容詞は名詞に直接つき、「の」は不要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "冷たかった", "is_correct": true, "explanation": "さわった時の過去の感覚なので、た形が必要。"}, {"text": "冷たくて", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "冷たければ", "is_correct": false, "explanation": "仮定形では文が完結しない。"}, {"text": "冷たく", "is_correct": false, "explanation": "連用形だけでは文末にならない。"}], "correct_form": "冷たかった", "base_form": "冷たい", "form_label": "活用", "sentence_index": 7, "explanations": {"冷たかった": "さわった時の過去の感覚なので、た形が必要。", "冷たくて": "て形では文が終わらない。", "冷たければ": "仮定形では文が完結しない。", "冷たく": "連用形だけでは文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36559, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温かい", "is_correct": true, "explanation": "温度が高く心地よいことで、冷たいの対義語。"}, {"text": "寒い", "is_correct": false, "explanation": "低い気温を表し、対義ではない。"}, {"text": "涼しい", "is_correct": false, "explanation": "低めの温度で、対義ではない。"}, {"text": "固い", "is_correct": false, "explanation": "手ざわりの性質で、温度の対義語ではない。"}], "correct_answer": "温かい", "explanations": {"温かい": "温度が高く心地よいことで、冷たいの対義語。", "寒い": "低い気温を表し、対義ではない。", "涼しい": "低めの温度で、対義ではない。", "固い": "手ざわりの性質で、温度の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52050, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冷徹", "is_correct": true, "explanation": "正解：れいてつ。"}, {"text": "礼節", "is_correct": false, "explanation": "れいせつ：「て」が「せ」に変わる一モーラ差。"}, {"text": "零点", "is_correct": false, "explanation": "れいてん：「つ」が「ん」に変わる一モーラ差。"}, {"text": "蹄鉄", "is_correct": false, "explanation": "ていてつ：「れ」が「て」に変わる一モーラ差。"}], "explanations": {"冷徹": "正解：れいてつ。", "礼節": "れいせつ：「て」が「せ」に変わる一モーラ差。", "零点": "れいてん：「つ」が「ん」に変わる一モーラ差。", "蹄鉄": "ていてつ：「れ」が「て」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "冷徹"}, "level_3": {"options": [{"text": "冷徹に", "is_correct": true, "explanation": "感情を交えず客観的に認識するという意味で合う。"}, {"text": "派手に", "is_correct": false, "explanation": "意味：認識のしかたに「派手」は使わない。"}, {"text": "退屈に", "is_correct": false, "explanation": "意味：認識する態度として不適切。"}, {"text": "不便に", "is_correct": false, "explanation": "意味：認識のしかたを表さない。"}], "explanations": {"冷徹に": "感情を交えず客観的に認識するという意味で合う。", "派手に": "意味：認識のしかたに「派手」は使わない。", "退屈に": "意味：認識する態度として不適切。", "不便に": "意味：認識のしかたを表さない。"}, "sentence_index": 0, "correct_answer": "冷徹に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "監督は冷徹な判断が選手を選んだ。", "explanation": "助詞の混同：手段なので「判断で」が正しい。"}, {"text": "彼は事実を明日冷徹に見つめた。", "explanation": "アスペクトの誤り：「明日」と過去形が合わない。"}, {"text": "冷徹な一匹の判断をした。", "explanation": "助数詞の誤り：判断に「匹」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52050, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長は冷徹の数字だけを見ていた。", "corrected_sentence": "社長は冷徹に数字だけを見ていた。", "error_description": "活用の誤り：動詞を修飾するので「冷徹に」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "冷徹な", "is_correct": true, "explanation": "名詞「街路」を修飾するので連体形「冷徹な」。"}, {"text": "冷徹に", "is_correct": false, "explanation": "連用形は名詞を直接修飾できない。"}, {"text": "冷徹だ", "is_correct": false, "explanation": "終止形は名詞の前に置けない。"}, {"text": "冷徹で", "is_correct": false, "explanation": "て形は名詞を修飾できない。"}], "correct_form": "冷徹な", "base_form": "冷徹", "form_label": "活用", "sentence_index": 1, "explanations": {"冷徹な": "名詞「街路」を修飾するので連体形「冷徹な」。", "冷徹に": "連用形は名詞を直接修飾できない。", "冷徹だ": "終止形は名詞の前に置けない。", "冷徹で": "て形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52050, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "感情的", "is_correct": true, "explanation": "感情に左右されるさまで、冷徹の対義語。"}, {"text": "冷静", "is_correct": false, "explanation": "感情に流されない点で類義であり、対義ではない。"}, {"text": "厳格", "is_correct": false, "explanation": "きびしさを表し、対義ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深さを表し、対義ではない。"}], "correct_answer": "感情的", "explanations": {"感情的": "感情に左右されるさまで、冷徹の対義語。", "冷静": "感情に流されない点で類義であり、対義ではない。", "厳格": "きびしさを表し、対義ではない。", "慎重": "注意深さを表し、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52050, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冷徹", "is_correct": true, "explanation": "正解：れいてつ。"}, {"text": "霊的", "is_correct": false, "explanation": "れいてき：「つ」が「き」に変わる一モーラ差。"}, {"text": "製鉄", "is_correct": false, "explanation": "せいてつ：「れ」が「せ」に変わる一モーラ差。"}, {"text": "礼節", "is_correct": false, "explanation": "れいせつ：「て」が「せ」に変わる一モーラ差。"}], "explanations": {"冷徹": "正解：れいてつ。", "霊的": "れいてき：「つ」が「き」に変わる一モーラ差。", "製鉄": "せいてつ：「れ」が「せ」に変わる一モーラ差。", "礼節": "れいせつ：「て」が「せ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "冷徹"}, "level_3": {"options": [{"text": "冷徹な", "is_correct": true, "explanation": "感情を交えない目で失敗を見つめる意味で合う。"}, {"text": "便利な", "is_correct": false, "explanation": "意味：「便利な目」で考えるのは不自然。"}, {"text": "退屈な", "is_correct": false, "explanation": "連語：「退屈な目で考える」とは言わない。"}, {"text": "有名な", "is_correct": false, "explanation": "意味：目の性質として不適切。"}], "explanations": {"冷徹な": "感情を交えない目で失敗を見つめる意味で合う。", "便利な": "意味：「便利な目」で考えるのは不自然。", "退屈な": "連語：「退屈な目で考える」とは言わない。", "有名な": "意味：目の性質として不適切。"}, "sentence_index": 6, "correct_answer": "冷徹な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷徹に意見だが、正しいと思う。", "explanation": "活用の誤り：名詞「意見」を修飾するので連体形「冷徹な」。"}, {"text": "冷徹だ意見だが、正しいと思う。", "explanation": "活用の誤り：終止形「冷徹だ」は名詞の前に置けない。"}, {"text": "彼女の冷徹さをみんなおどろいた。", "explanation": "助詞の混同：「おどろく」は「に」をとる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52050, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷徹な目を自分の失敗を考えた。", "corrected_sentence": "冷徹な目で自分の失敗を考えた。", "error_description": "助詞の混同：手段を表すので「目で」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "冷徹さ", "is_correct": true, "explanation": "「彼女の」に続き「に」をとるので名詞形「冷徹さ」。"}, {"text": "冷徹な", "is_correct": false, "explanation": "連体形は後に名詞が必要。"}, {"text": "冷徹に", "is_correct": false, "explanation": "「の冷徹に」とは続かない。"}, {"text": "冷徹だ", "is_correct": false, "explanation": "終止形は助詞「に」に続かない。"}], "correct_form": "冷徹さ", "base_form": "冷徹", "form_label": "派生", "sentence_index": 7, "explanations": {"冷徹さ": "「彼女の」に続き「に」をとるので名詞形「冷徹さ」。", "冷徹な": "連体形は後に名詞が必要。", "冷徹に": "「の冷徹に」とは続かない。", "冷徹だ": "終止形は助詞「に」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
