INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35697, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供給", "is_correct": true, "explanation": "正解：きょうきゅう。"}, {"text": "高級", "is_correct": false, "explanation": "こうきゅう：「きょ」が「こ」に変わる一モーラ差。"}, {"text": "救急", "is_correct": false, "explanation": "きゅうきゅう：「きょ」が「きゅ」に変わる一モーラ差。"}, {"text": "郷愁", "is_correct": false, "explanation": "きょうしゅう：「きゅ」が「しゅ」に変わる一モーラ差。"}, {"text": "胸中", "is_correct": false, "explanation": "きょうちゅう：「きゅ」が「ちゅ」に変わる一モーラ差。"}], "explanations": {"供給": "正解：きょうきゅう。", "高級": "こうきゅう：「きょ」が「こ」に変わる一モーラ差。", "救急": "きゅうきゅう：「きょ」が「きゅ」に変わる一モーラ差。", "郷愁": "きょうしゅう：「きゅ」が「しゅ」に変わる一モーラ差。", "胸中": "きょうちゅう：「きゅ」が「ちゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "供給"}, "level_3": {"options": [{"text": "供給", "is_correct": true, "explanation": "食料を届け続ける仕組みとして「持続可能な食料供給」が合う。"}, {"text": "不足", "is_correct": false, "explanation": "意味：不足の実現を目指すことはない。"}, {"text": "廃棄", "is_correct": false, "explanation": "意味：食料廃棄の実現は目的と逆。"}, {"text": "価格", "is_correct": false, "explanation": "連語：「価格の実現」とは言わない。"}], "explanations": {"供給": "食料を届け続ける仕組みとして「持続可能な食料供給」が合う。", "不足": "意味：不足の実現を目指すことはない。", "廃棄": "意味：食料廃棄の実現は目的と逆。", "価格": "連語：「価格の実現」とは言わない。"}, "sentence_index": 0, "correct_answer": "供給"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町は電気の供給を安定している。", "explanation": "助詞の混同：「安定する」の主語なので「供給が」。"}, {"text": "野菜の供給が明日足りなかった。", "explanation": "アスペクトの誤り：「明日」と過去形が合わない。"}, {"text": "三匹の供給が止まった。", "explanation": "助数詞の誤り：供給に「匹」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
