INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35697, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「もたらす」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり「好循環がもたらす」と非文になる。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "「もたらす」の目的語を表す。", "が": "主格になり「好循環がもたらす」と非文になる。", "に": "着点を表し、目的語にならない。", "で": "手段を表し、この位置では非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "需要", "is_correct": true, "explanation": "求められる量で、供給と対になる語。"}, {"text": "生産", "is_correct": false, "explanation": "物を作ることで、対義ではない。"}, {"text": "輸送", "is_correct": false, "explanation": "運ぶことで、対義ではない。"}, {"text": "販売", "is_correct": false, "explanation": "売ることで、対義ではない。"}], "correct_answer": "需要", "explanations": {"需要": "求められる量で、供給と対になる語。", "生産": "物を作ることで、対義ではない。", "輸送": "運ぶことで、対義ではない。", "販売": "売ることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35697, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "供給", "is_correct": true, "explanation": "正解：きょうきゅう。"}, {"text": "要求", "is_correct": false, "explanation": "ようきゅう：「きょ」が「よ」に変わる一モーラ差。"}, {"text": "昇給", "is_correct": false, "explanation": "しょうきゅう：「きょ」が「しょ」に変わる一モーラ差。"}, {"text": "恐竜", "is_correct": false, "explanation": "きょうりゅう：「きゅ」が「りゅ」に変わる一モーラ差。"}], "explanations": {"供給": "正解：きょうきゅう。", "要求": "ようきゅう：「きょ」が「よ」に変わる一モーラ差。", "昇給": "しょうきゅう：「きょ」が「しょ」に変わる一モーラ差。", "恐竜": "きょうりゅう：「きゅ」が「りゅ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "供給"}, "level_3": {"options": [{"text": "供給", "is_correct": true, "explanation": "ガスを届けることが元にもどるので合う。"}, {"text": "爆発", "is_correct": false, "explanation": "意味：爆発が元にもどることはない。"}, {"text": "火事", "is_correct": false, "explanation": "意味：火事が元にもどるのは不自然。"}, {"text": "発明", "is_correct": false, "explanation": "意味：発明は元にもどらない。"}], "explanations": {"供給": "ガスを届けることが元にもどるので合う。", "爆発": "意味：爆発が元にもどることはない。", "火事": "意味：火事が元にもどるのは不自然。", "発明": "意味：発明は元にもどらない。"}, "sentence_index": 6, "correct_answer": "供給"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "供給が多いと、物を安くなる。", "explanation": "助詞の混同：「なる」の主語なので「物は」。"}, {"text": "食料を供給するできる国は少ない。", "explanation": "活用の誤り：可能の形は「供給できる」で、「するできる」とは言わない。"}, {"text": "二本の供給が来た。", "explanation": "助数詞の誤り：供給に「本」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
