INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35697, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「病院への」で行き先を表す。"}, {"text": "に", "is_correct": false, "explanation": "「にの」とは続かず非文。"}, {"text": "を", "is_correct": false, "explanation": "「をの」とは続かず非文。"}, {"text": "が", "is_correct": false, "explanation": "「がの」とは続かず非文。"}], "correct_answer": "へ", "explanations": {"へ": "「病院への」で行き先を表す。", "に": "「にの」とは続かず非文。", "を": "「をの」とは続かず非文。", "が": "「がの」とは続かず非文。"}, "error_tags": {"に": "direction", "を": "object_marking", "が": "other"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "需要", "is_correct": true, "explanation": "必要とされることで、供給の対義語。"}, {"text": "流通", "is_correct": false, "explanation": "物が行き渡ることで、対義ではない。"}, {"text": "配達", "is_correct": false, "explanation": "届けることで、むしろ近い意味。"}, {"text": "在庫", "is_correct": false, "explanation": "手元にある物で、対義ではない。"}], "correct_answer": "需要", "explanations": {"需要": "必要とされることで、供給の対義語。", "流通": "物が行き渡ることで、対義ではない。", "配達": "届けることで、むしろ近い意味。", "在庫": "手元にある物で、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53110, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "産む", "is_correct": true, "explanation": "正解：うむ。"}, {"text": "海", "is_correct": false, "explanation": "うみ：「む」が「み」に変わる一モーラ差。"}, {"text": "売る", "is_correct": false, "explanation": "うる：「む」が「る」に変わる一モーラ差。"}, {"text": "浮く", "is_correct": false, "explanation": "うく：「む」が「く」に変わる一モーラ差。"}, {"text": "組む", "is_correct": false, "explanation": "くむ：「う」が「く」に変わる一モーラ差。"}], "explanations": {"産む": "正解：うむ。", "海": "うみ：「む」が「み」に変わる一モーラ差。", "売る": "うる：「む」が「る」に変わる一モーラ差。", "浮く": "うく：「む」が「く」に変わる一モーラ差。", "組む": "くむ：「う」が「く」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "産む"}, "level_3": {"options": [{"text": "産ん", "is_correct": true, "explanation": "鶏が卵を体の外に出すので「産んで」。"}, {"text": "読ん", "is_correct": false, "explanation": "意味：鶏は卵を読まない。"}, {"text": "遊ん", "is_correct": false, "explanation": "項構造：「卵を遊んで」は格が合わない。"}, {"text": "死ん", "is_correct": false, "explanation": "項構造：「死ぬ」は目的語をとらない。"}], "explanations": {"産ん": "鶏が卵を体の外に出すので「産んで」。", "読ん": "意味：鶏は卵を読まない。", "遊ん": "項構造：「卵を遊んで」は格が合わない。", "死ん": "項構造：「死ぬ」は目的語をとらない。"}, "sentence_index": 0, "correct_answer": "産ん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カメは砂の中に卵が産む。", "explanation": "助詞の混同：目的語なので「卵を」。"}, {"text": "カメは昨日砂の中に卵を産む。", "explanation": "アスペクトの誤り：「昨日」には「産んだ」が必要。"}, {"text": "カメは三冊の卵を産んだ。", "explanation": "助数詞の誤り：卵は「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53110, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ねこが子ねこを三びき産むだ。", "corrected_sentence": "ねこが子ねこを三びき産んだ。", "error_description": "活用の誤り：「産む」のた形は「産んだ」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "産む", "is_correct": true, "explanation": "毎朝の習慣なので辞書形で文を終える。"}, {"text": "産んで", "is_correct": false, "explanation": "て形では文が終わらない。"}, {"text": "産ませる", "is_correct": false, "explanation": "使役形はニワトリ自身が産む文意に合わない。"}, {"text": "産まれる", "is_correct": false, "explanation": "受身形では「卵を」と合わない。"}], "correct_form": "産む", "base_form": "産む", "form_label": "活用", "sentence_index": 1, "explanations": {"産む": "毎朝の習慣なので辞書形で文を終える。", "産んで": "て形では文が終わらない。", "産ませる": "使役形はニワトリ自身が産む文意に合わない。", "産まれる": "受身形では「卵を」と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
