INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53110, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "産む", "is_correct": true, "explanation": "正解：うむ。"}, {"text": "打つ", "is_correct": false, "explanation": "うつ：「む」が「つ」に変わる一モーラ差。"}, {"text": "住む", "is_correct": false, "explanation": "すむ：「う」が「す」に変わる一モーラ差。"}, {"text": "噛む", "is_correct": false, "explanation": "かむ：「う」が「か」に変わる一モーラ差。"}, {"text": "売る", "is_correct": false, "explanation": "うる：「む」が「る」に変わる一モーラ差。"}], "explanations": {"産む": "正解：うむ。", "打つ": "うつ：「む」が「つ」に変わる一モーラ差。", "住む": "すむ：「う」が「す」に変わる一モーラ差。", "噛む": "かむ：「う」が「か」に変わる一モーラ差。", "売る": "うる：「む」が「る」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "産む"}, "level_3": {"options": [{"text": "産ま", "is_correct": true, "explanation": "寒いと鶏が卵を出さないので「産まない」。"}, {"text": "読ま", "is_correct": false, "explanation": "意味：鶏は卵を読まない。"}, {"text": "書か", "is_correct": false, "explanation": "意味：鶏は卵を書かない。"}, {"text": "泳が", "is_correct": false, "explanation": "項構造：「卵を泳がない」は格が合わない。"}], "explanations": {"産ま": "寒いと鶏が卵を出さないので「産まない」。", "読ま": "意味：鶏は卵を読まない。", "書か": "意味：鶏は卵を書かない。", "泳が": "項構造：「卵を泳がない」は格が合わない。"}, "sentence_index": 6, "correct_answer": "産ま"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卵を産むれる場所を鳥がさがしている。", "explanation": "活用の誤り：「産む」の可能形は「産める」。"}, {"text": "母は明日病院で弟を産んだ。", "explanation": "アスペクトの誤り：「明日」と過去形が合わない。"}, {"text": "犬が子犬を二枚産んだ。", "explanation": "助数詞の誤り：子犬は「匹」で数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
