INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36037, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "確立", "is_correct": true, "explanation": "正解：かくりつ。"}, {"text": "国立", "is_correct": false, "explanation": "こくりつ：「か」が「こ」に変わる一モーラ差。"}, {"text": "格別", "is_correct": false, "explanation": "かくべつ：「り」が「べ」に変わる一モーラ差。"}, {"text": "画一", "is_correct": false, "explanation": "かくいつ：「り」が「い」に変わる一モーラ差。"}], "explanations": {"確立": "正解：かくりつ。", "国立": "こくりつ：「か」が「こ」に変わる一モーラ差。", "格別": "かくべつ：「り」が「べ」に変わる一モーラ差。", "画一": "かくいつ：「り」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "確立"}, "level_3": {"options": [{"text": "確立", "is_correct": true, "explanation": "「確立された安住の地」で、しっかり定まった状態を表す。"}, {"text": "欠席", "is_correct": false, "explanation": "意味：「欠席された安住の地」は意味をなさない。"}, {"text": "衰退", "is_correct": false, "explanation": "衰えた場所は「安住の地」と矛盾する。"}, {"text": "想像", "is_correct": false, "explanation": "想像された地からの離脱では意味が通らない。"}], "explanations": {"確立": "「確立された安住の地」で、しっかり定まった状態を表す。", "欠席": "意味：「欠席された安住の地」は意味をなさない。", "衰退": "衰えた場所は「安住の地」と矛盾する。", "想像": "想像された地からの離脱では意味が通らない。"}, "sentence_index": 0, "correct_answer": "確立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝パンを確立して食べる。", "explanation": "食べ物を作る意味では使えない。"}, {"text": "雨が確立に降ってきた。", "explanation": "副詞のようには使えない。"}, {"text": "彼は駅まで確立した。", "explanation": "移動の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
