INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36037, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「確立には」で目的・対象を表し、「時間がかかる」と結びつく。"}, {"text": "を", "is_correct": false, "explanation": "「確立を時間がかかる」は非文。"}, {"text": "が", "is_correct": false, "explanation": "「確立がは」と助詞が重なり非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、ここでは使えない。"}], "correct_answer": "に", "explanations": {"に": "「確立には」で目的・対象を表し、「時間がかかる」と結びつく。", "を": "「確立を時間がかかる」は非文。", "が": "「確立がは」と助詞が重なり非文。", "へ": "方向を表すため、ここでは使えない。"}, "error_tags": {"を": "object_marking", "が": "other", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩壊", "is_correct": true, "explanation": "しっかり固まった状態が崩れることで、「確立」の反対。"}, {"text": "樹立", "is_correct": false, "explanation": "新しく打ち立てることで、類義語。"}, {"text": "構築", "is_correct": false, "explanation": "作り上げることで、類義語に近い。"}, {"text": "実施", "is_correct": false, "explanation": "行うことで、反対の関係ではない。"}], "correct_answer": "崩壊", "explanations": {"崩壊": "しっかり固まった状態が崩れることで、「確立」の反対。", "樹立": "新しく打ち立てることで、類義語。", "構築": "作り上げることで、類義語に近い。", "実施": "行うことで、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
