INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52526, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "見守る", "is_correct": true, "explanation": "見出し語そのものの音。"}, {"text": "見回る", "is_correct": false, "explanation": "みまわる：も→わの一モーラ差。"}, {"text": "身罷る", "is_correct": false, "explanation": "みまかる：も→かの一モーラ差。"}, {"text": "見積もる", "is_correct": false, "explanation": "みつもる：ま→つの一モーラ差。"}], "explanations": {"見守る": "見出し語そのものの音。", "見回る": "みまわる：も→わの一モーラ差。", "身罷る": "みまかる：も→かの一モーラ差。", "見積もる": "みつもる：ま→つの一モーラ差。"}, "sentence_index": null, "correct_answer": "見守る"}, "level_3": {"options": [{"text": "見守る", "is_correct": true, "explanation": "「祈りを込めて見守る」で心配しながら見続ける意味。"}, {"text": "見下す", "is_correct": false, "explanation": "祈りを込めて見下すのは矛盾する。"}, {"text": "見逃す", "is_correct": false, "explanation": "祈りを込めて見逃すは文脈に合わない。"}, {"text": "見捨てる", "is_correct": false, "explanation": "祈りを込めて見捨てるは矛盾する。"}], "explanations": {"見守る": "「祈りを込めて見守る」で心配しながら見続ける意味。", "見下す": "祈りを込めて見下すのは矛盾する。", "見逃す": "祈りを込めて見逃すは文脈に合わない。", "見捨てる": "祈りを込めて見捨てるは矛盾する。"}, "sentence_index": 0, "correct_answer": "見守る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラジオの音楽を見守った。", "explanation": "音は見るものではない。"}, {"text": "彼は駅まで見守って走った。", "explanation": "移動の意味はない。"}, {"text": "ご飯を見守って食べた。", "explanation": "食べ方の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
