INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51542, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "儀式", "is_correct": true, "explanation": "見出し語そのものの音。"}, {"text": "議席", "is_correct": false, "explanation": "ぎせき：し→せの一モーラ差。"}, {"text": "意識", "is_correct": false, "explanation": "いしき：ぎ→いの一モーラ差。"}, {"text": "知識", "is_correct": false, "explanation": "ちしき：ぎ→ちの一モーラ差。"}], "explanations": {"儀式": "見出し語そのものの音。", "議席": "ぎせき：し→せの一モーラ差。", "意識": "いしき：ぎ→いの一モーラ差。", "知識": "ちしき：ぎ→ちの一モーラ差。"}, "sentence_index": null, "correct_answer": "儀式"}, "level_3": {"options": [{"text": "儀式", "is_correct": true, "explanation": "毎朝決まった形で行う大切な行為を表す。"}, {"text": "病気", "is_correct": false, "explanation": "「重要な病気となっている」は文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "作業が天気になるは非文。"}, {"text": "家具", "is_correct": false, "explanation": "作業が家具になるは非文。"}], "explanations": {"儀式": "毎朝決まった形で行う大切な行為を表す。", "病気": "「重要な病気となっている」は文脈に合わない。", "天気": "作業が天気になるは非文。", "家具": "作業が家具になるは非文。"}, "sentence_index": 0, "correct_answer": "儀式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "儀式を一つ食べた。", "explanation": "食べ物ではない。"}, {"text": "儀式で髪を切った。", "explanation": "道具ではない。"}, {"text": "儀式が空から降った。", "explanation": "天気ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
