INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51542, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "受身「行われた」の主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "「儀式を行われた」は受身と合わず非文。"}, {"text": "に", "is_correct": false, "explanation": "「儀式に行われた」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「儀式で行われた」は意味が変わり不自然。"}], "correct_answer": "が", "explanations": {"が": "受身「行われた」の主語を表す。", "を": "「儀式を行われた」は受身と合わず非文。", "に": "「儀式に行われた」は非文。", "で": "「儀式で行われた」は意味が変わり不自然。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51542, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "儀式", "is_correct": true, "explanation": "見出し語そのものの音。"}, {"text": "五色", "is_correct": false, "explanation": "ごしき：ぎ→ごの一モーラ差。"}, {"text": "知識", "is_correct": false, "explanation": "ちしき：ぎ→ちの一モーラ差。"}, {"text": "議席", "is_correct": false, "explanation": "ぎせき：し→せの一モーラ差。"}], "explanations": {"儀式": "見出し語そのものの音。", "五色": "ごしき：ぎ→ごの一モーラ差。", "知識": "ちしき：ぎ→ちの一モーラ差。", "議席": "ぎせき：し→せの一モーラ差。"}, "sentence_index": null, "correct_answer": "儀式"}, "level_3": {"options": [{"text": "儀式", "is_correct": true, "explanation": "儀式の場で祈ったという意味。"}, {"text": "石鹸", "is_correct": false, "explanation": "「石鹸で静かに祈った」は意味をなさない。"}, {"text": "包丁", "is_correct": false, "explanation": "「包丁で祈った」は非文。"}, {"text": "砂", "is_correct": false, "explanation": "「砂で静かに祈った」は意味をなさない。"}], "explanations": {"儀式": "儀式の場で祈ったという意味。", "石鹸": "「石鹸で静かに祈った」は意味をなさない。", "包丁": "「包丁で祈った」は非文。", "砂": "「砂で静かに祈った」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "儀式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "儀式を冷蔵庫に入れた。", "explanation": "物ではない。"}, {"text": "儀式で手紙を切った。", "explanation": "道具ではない。"}, {"text": "儀式が庭で鳴いた。", "explanation": "動物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51542, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "儀式を飲んでから寝た。", "corrected_sentence": "儀式を終えてから寝た。", "error_description": "「儀式」は飲み物ではなく、行う・終える行事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51542, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「学ぶ」の目的語を表す。"}, {"text": "が", "is_correct": false, "explanation": "「意味が学んだ」は非文。"}, {"text": "に", "is_correct": false, "explanation": "「意味に学んだ」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「意味で学んだ」は非文。"}], "correct_answer": "を", "explanations": {"を": "「学ぶ」の目的語を表す。", "が": "「意味が学んだ」は非文。", "に": "「意味に学んだ」は不自然。", "で": "「意味で学んだ」は非文。"}, "error_tags": {"が": "topic_vs_subject", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52068, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "無心", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "無人", "is_correct": false, "explanation": "むじん。「し」が濁音「じ」になった清濁の違い。"}, {"text": "無線", "is_correct": false, "explanation": "むせん。「し」が「せ」に変わった一モーラ違い。"}, {"text": "自信", "is_correct": false, "explanation": "じしん。最初の「む」が「じ」に変わった一モーラ違い。"}, {"text": "普請", "is_correct": false, "explanation": "ふしん。最初の「む」が「ふ」に変わった一モーラ違い。"}], "explanations": {"無心": "音声どおりの語。", "無人": "むじん。「し」が濁音「じ」になった清濁の違い。", "無線": "むせん。「し」が「せ」に変わった一モーラ違い。", "自信": "じしん。最初の「む」が「じ」に変わった一モーラ違い。", "普請": "ふしん。最初の「む」が「ふ」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "無心"}, "level_3": {"options": [{"text": "無心", "is_correct": true, "explanation": "何も考えず一心に植物を見つめる眼差しを表す。"}, {"text": "冷酷", "is_correct": false, "explanation": "意味：子どもが植物を見る穏やかな場面に、思いやりのなさは合わない。"}, {"text": "無礼", "is_correct": false, "explanation": "意味：礼儀の欠如を表し、眼差しの描写として場面に合わない。"}, {"text": "頑固", "is_correct": false, "explanation": "連語：「頑固なる眼差し」は不自然で、幼子が植物を見る様子に合わない。"}], "explanations": {"無心": "何も考えず一心に植物を見つめる眼差しを表す。", "冷酷": "意味：子どもが植物を見る穏やかな場面に、思いやりのなさは合わない。", "無礼": "意味：礼儀の欠如を表し、眼差しの描写として場面に合わない。", "頑固": "連語：「頑固なる眼差し」は不自然で、幼子が植物を見る様子に合わない。"}, "sentence_index": 0, "correct_answer": "無心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "無心にお金を数えて、得をする方法を考えた。", "explanation": "意味の誤り：得を考えている状態は、何も考えない「無心」と矛盾する。"}, {"text": "彼は無心に、明日の計画を細かく考えた。", "explanation": "意味の誤り：計画を細かく考えることは「無心」と両立しない。"}, {"text": "無心が砂で子どもに遊んでいる。", "explanation": "助詞の混同：主語は「子どもが」、副詞的には「無心に」であり、「無心が」「子どもに」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52068, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが無心を砂で遊んでいる。", "corrected_sentence": "子どもが無心に砂で遊んでいる。", "error_description": "助詞の混同：様子を表すときは「無心に」とし、「無心を」は使わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "無心", "is_correct": true, "explanation": "後ろの「なる」「に」「な」などが文中にあるので、空欄には語幹だけが入る。"}, {"text": "無心な", "is_correct": false, "explanation": "後ろに「なる」があり「無心ななる」となって非文。"}, {"text": "無心に", "is_correct": false, "explanation": "「無心になる眼差し」は連体修飾にならず不自然。"}, {"text": "無心だ", "is_correct": false, "explanation": "終止形で、名詞「眼差し」を修飾できない。"}], "correct_form": "無心", "base_form": "無心", "form_label": "語幹（形状詞）", "sentence_index": 1, "explanations": {"無心": "後ろの「なる」「に」「な」などが文中にあるので、空欄には語幹だけが入る。", "無心な": "後ろに「なる」があり「無心ななる」となって非文。", "無心に": "「無心になる眼差し」は連体修飾にならず不自然。", "無心だ": "終止形で、名詞「眼差し」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
