INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52068, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "無心", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "マシン", "is_correct": false, "explanation": "ましん。最初の「む」が「ま」に変わった一モーラ違い。"}, {"text": "無線", "is_correct": false, "explanation": "むせん。「し」が「せ」に変わった一モーラ違い。"}, {"text": "不信", "is_correct": false, "explanation": "ふしん。「む」が「ふ」に変わった一モーラ違い。"}, {"text": "地震", "is_correct": false, "explanation": "じしん。「む」が「じ」に変わった一モーラ違い。"}, {"text": "無人", "is_correct": false, "explanation": "むじん。「し」と「じ」の清濁の違い。"}], "explanations": {"無心": "音声どおりの語。", "マシン": "ましん。最初の「む」が「ま」に変わった一モーラ違い。", "無線": "むせん。「し」が「せ」に変わった一モーラ違い。", "不信": "ふしん。「む」が「ふ」に変わった一モーラ違い。", "地震": "じしん。「む」が「じ」に変わった一モーラ違い。", "無人": "むじん。「し」と「じ」の清濁の違い。"}, "sentence_index": null, "correct_answer": "無心"}, "level_3": {"options": [{"text": "無心", "is_correct": true, "explanation": "本に夢中になって読む様子を表す。"}, {"text": "不便", "is_correct": false, "explanation": "「不便に本を読む」は意味をなさない。"}, {"text": "有名", "is_correct": false, "explanation": "「有名に本を読む」は非文。"}, {"text": "危険", "is_correct": false, "explanation": "「危険に本を読む」は不自然。"}], "explanations": {"無心": "本に夢中になって読む様子を表す。", "不便": "「不便に本を読む」は意味をなさない。", "有名": "「有名に本を読む」は非文。", "危険": "「危険に本を読む」は不自然。"}, "sentence_index": 6, "correct_answer": "無心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "無心な計算で、損をしない道を選んだ。", "explanation": "意味の誤り：損得を計算することは「無心」と正反対。"}, {"text": "その無心に姿に感動した。", "explanation": "活用の誤り：名詞「姿」を修飾するときは「無心な」で、「無心に」は使えない。"}, {"text": "彼は無心で、心配ごとばかり考えていた。", "explanation": "意味の誤り：心配ごとを考え続けるのは「無心」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52068, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "無心に姿に感動した。", "corrected_sentence": "その無心な姿に感動した。", "error_description": "活用の誤り：名詞を修飾するときは「無心な姿」とする。「無心に姿」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "無心", "is_correct": true, "explanation": "後ろの「なる」「に」「な」などが文中にあるので、空欄には語幹だけが入る。"}, {"text": "無心な", "is_correct": false, "explanation": "「無心ななって」となり非文。"}, {"text": "無心だ", "is_correct": false, "explanation": "「無心だになって」となり非文。"}, {"text": "無心さ", "is_correct": false, "explanation": "名詞形で、「無心さになって」は意味が変わり不自然。"}], "correct_form": "無心", "base_form": "無心", "form_label": "語幹（形状詞）", "sentence_index": 7, "explanations": {"無心": "後ろの「なる」「に」「な」などが文中にあるので、空欄には語幹だけが入る。", "無心な": "「無心ななって」となり非文。", "無心だ": "「無心だになって」となり非文。", "無心さ": "名詞形で、「無心さになって」は意味が変わり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
