INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "純粋", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "噴水", "is_correct": false, "explanation": "ふんすい。最初の「じゅ」が「ふ」に変わった一モーラ違い。"}, {"text": "淡水", "is_correct": false, "explanation": "たんすい。「じゅ」が「た」に変わった一モーラ違い。"}, {"text": "元帥", "is_correct": false, "explanation": "げんすい。「じゅ」が「げ」に変わった一モーラ違い。"}, {"text": "冠水", "is_correct": false, "explanation": "かんすい。「じゅ」が「か」に変わった一モーラ違い。"}], "explanations": {"純粋": "音声どおりの語。", "噴水": "ふんすい。最初の「じゅ」が「ふ」に変わった一モーラ違い。", "淡水": "たんすい。「じゅ」が「た」に変わった一モーラ違い。", "元帥": "げんすい。「じゅ」が「げ」に変わった一モーラ違い。", "冠水": "かんすい。「じゅ」が「か」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "純粋"}, "level_3": {"options": [{"text": "純粋", "is_correct": true, "explanation": "言葉を介さない、まじりけのない対話を表す。"}, {"text": "乱暴", "is_correct": false, "explanation": "意味：自然と静かに交わす対話の形容として正反対。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：「最も退屈な対話の形」では文全体の称賛の調子と合わない。"}, {"text": "便利", "is_correct": false, "explanation": "連語：「便利な対話の形」は対話の質を表す言い方として不自然。"}], "explanations": {"純粋": "言葉を介さない、まじりけのない対話を表す。", "乱暴": "意味：自然と静かに交わす対話の形容として正反対。", "退屈": "意味：「最も退屈な対話の形」では文全体の称賛の調子と合わない。", "便利": "連語：「便利な対話の形」は対話の質を表す言い方として不自然。"}, "sentence_index": 0, "correct_answer": "純粋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この純粋な水には、砂や泥がたくさんまざっている。", "explanation": "意味の誤り：まざり物が多いことは「純粋」と矛盾する。"}, {"text": "彼はうそばかりつく、とても純粋な人だ。", "explanation": "意味の誤り：うそをつく人を「純粋」とは言わない。"}, {"text": "純粋が音楽を楽しみたい。", "explanation": "助詞の混同：副詞として使うときは「純粋に」であり、「純粋が」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "純粋を音楽を楽しみたい。", "corrected_sentence": "純粋に音楽を楽しみたい。", "error_description": "助詞の混同：動詞を修飾するときは「純粋に」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "純粋", "is_correct": true, "explanation": "空欄の後に「な」があるので、空欄には語幹「純粋」が入る。"}, {"text": "純粋に", "is_correct": false, "explanation": "「純粋にな心」となり非文。"}, {"text": "純粋だ", "is_correct": false, "explanation": "「純粋だな心」となり非文。"}, {"text": "純粋さ", "is_correct": false, "explanation": "名詞形で「純粋さな心」は非文。"}], "correct_form": "純粋", "base_form": "純粋", "form_label": "語幹（形状詞）", "sentence_index": 1, "explanations": {"純粋": "空欄の後に「な」があるので、空欄には語幹「純粋」が入る。", "純粋に": "「純粋にな心」となり非文。", "純粋だ": "「純粋だな心」となり非文。", "純粋さ": "名詞形で「純粋さな心」は非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不純", "is_correct": true, "explanation": "まじりけがあり、心が清らかでない様子で、「純粋」の対義語。"}, {"text": "素直", "is_correct": false, "explanation": "性格のよさを表し、むしろ「純粋」に近い語で対義ではない。"}, {"text": "正直", "is_correct": false, "explanation": "うそをつかない様子で、対義関係にない。"}, {"text": "誠実", "is_correct": false, "explanation": "まじめで真心がある様子で、対義ではない。"}], "correct_answer": "不純", "explanations": {"不純": "まじりけがあり、心が清らかでない様子で、「純粋」の対義語。", "素直": "性格のよさを表し、むしろ「純粋」に近い語で対義ではない。", "正直": "うそをつかない様子で、対義関係にない。", "誠実": "まじめで真心がある様子で、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "純粋", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "分水", "is_correct": false, "explanation": "ぶんすい。「じゅ」が「ぶ」に変わった一モーラ違い。"}, {"text": "噴水", "is_correct": false, "explanation": "ふんすい。「じゅ」が「ふ」に変わった一モーラ違い。"}, {"text": "減衰", "is_correct": false, "explanation": "げんすい。「じゅ」が「げ」に変わった一モーラ違い。"}, {"text": "淡水", "is_correct": false, "explanation": "たんすい。「じゅ」が「た」に変わった一モーラ違い。"}], "explanations": {"純粋": "音声どおりの語。", "分水": "ぶんすい。「じゅ」が「ぶ」に変わった一モーラ違い。", "噴水": "ふんすい。「じゅ」が「ふ」に変わった一モーラ違い。", "減衰": "げんすい。「じゅ」が「げ」に変わった一モーラ違い。", "淡水": "たんすい。「じゅ」が「た」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "純粋"}, "level_3": {"options": [{"text": "純粋", "is_correct": true, "explanation": "うそや下心のない、清らかな気持ちを表す。"}, {"text": "不便", "is_correct": false, "explanation": "意味：「不便な気持ちで助けた」は意味をなさない。"}, {"text": "有名", "is_correct": false, "explanation": "意味：気持ちを「有名」とは言わない。"}, {"text": "頑丈", "is_correct": false, "explanation": "意味：「頑丈」は物の丈夫さで、気持ちには使わない。"}], "explanations": {"純粋": "うそや下心のない、清らかな気持ちを表す。", "不便": "意味：「不便な気持ちで助けた」は意味をなさない。", "有名": "意味：気持ちを「有名」とは言わない。", "頑丈": "意味：「頑丈」は物の丈夫さで、気持ちには使わない。"}, "sentence_index": 6, "correct_answer": "純粋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の夢は純粋で、人をだますためのものだった。", "explanation": "意味の誤り：人をだます目的は「純粋」と矛盾する。"}, {"text": "この金はいろいろな金属がまざっていて純粋だ。", "explanation": "意味の誤り：まざり物があるのは「純粋」の逆。"}, {"text": "彼の夢はいつも純粋にだった。", "explanation": "活用の誤り：述語では「純粋だった」で、「純粋にだった」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の夢はいつも純粋なだった。", "corrected_sentence": "彼の夢はいつも純粋だった。", "error_description": "活用の誤り：述語の過去は「純粋だった」。「純粋なだった」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "純粋", "is_correct": true, "explanation": "空欄の後に「な」があるので、空欄には語幹「純粋」が入る。"}, {"text": "純粋だ", "is_correct": false, "explanation": "「純粋だな興味」となり非文。"}, {"text": "純粋に", "is_correct": false, "explanation": "「純粋にな興味」となり非文。"}, {"text": "純粋で", "is_correct": false, "explanation": "「純粋でな興味」となり非文。"}], "correct_form": "純粋", "base_form": "純粋", "form_label": "語幹（形状詞）", "sentence_index": 7, "explanations": {"純粋": "空欄の後に「な」があるので、空欄には語幹「純粋」が入る。", "純粋だ": "「純粋だな興味」となり非文。", "純粋に": "「純粋にな興味」となり非文。", "純粋で": "「純粋でな興味」となり非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52118, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不純", "is_correct": true, "explanation": "まじりけがあり心がけがれている様子で、「純粋」の対義語。"}, {"text": "透明", "is_correct": false, "explanation": "すき通っている様子で、むしろ近い意味で対義ではない。"}, {"text": "素朴", "is_correct": false, "explanation": "飾りけのない様子で、対義関係にない。"}, {"text": "真剣", "is_correct": false, "explanation": "本気である様子で、対義ではない。"}], "correct_answer": "不純", "explanations": {"不純": "まじりけがあり心がけがれている様子で、「純粋」の対義語。", "透明": "すき通っている様子で、むしろ近い意味で対義ではない。", "素朴": "飾りけのない様子で、対義関係にない。", "真剣": "本気である様子で、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52222, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "往々", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "応用", "is_correct": false, "explanation": "おうよう。三つ目の「お」が「よ」に変わった一モーラ違い。"}, {"text": "横行", "is_correct": false, "explanation": "おうこう。「お」が「こ」に変わった一モーラ違い。"}, {"text": "応答", "is_correct": false, "explanation": "おうとう。「お」が「と」に変わった一モーラ違い。"}, {"text": "横暴", "is_correct": false, "explanation": "おうぼう。「お」が「ぼ」に変わった一モーラ違い。"}], "explanations": {"往々": "音声どおりの語。", "応用": "おうよう。三つ目の「お」が「よ」に変わった一モーラ違い。", "横行": "おうこう。「お」が「こ」に変わった一モーラ違い。", "応答": "おうとう。「お」が「と」に変わった一モーラ違い。", "横暴": "おうぼう。「お」が「ぼ」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "往々"}, "level_3": {"options": [{"text": "往々", "is_correct": true, "explanation": "「往々にして」で、大人がしばしば見落とすことを表す。"}, {"text": "堂々", "is_correct": false, "explanation": "連語：「堂々にして」とは言わず、見落とすの修飾にも合わない。"}, {"text": "延々", "is_correct": false, "explanation": "連語：「延々にして」という形はない。続く時間の長さを表す語で場面に合わない。"}, {"text": "黙々", "is_correct": false, "explanation": "連語：「黙々にして見落とす」は不自然。黙って作業する様子を表す語。"}], "explanations": {"往々": "「往々にして」で、大人がしばしば見落とすことを表す。", "堂々": "連語：「堂々にして」とは言わず、見落とすの修飾にも合わない。", "延々": "連語：「延々にして」という形はない。続く時間の長さを表す語で場面に合わない。", "黙々": "連語：「黙々にして見落とす」は不自然。黙って作業する様子を表す語。"}, "sentence_index": 0, "correct_answer": "往々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急ぐと往々にして、昨日失敗した。", "explanation": "アスペクトの誤り：一般的な傾向を表す「往々にして」は、特定の過去の一回の出来事には使えない。"}, {"text": "往々に急ぐと失敗する。", "explanation": "語形の誤り：「往々にして」の形で使い、「往々に」は不自然。"}, {"text": "往々にして、明日は雨が降るだろう。", "explanation": "意味の誤り：「往々にして」は繰り返し起こる傾向を表し、明日一回の出来事の予想には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
