INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52222, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "往々", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "桜桃", "is_correct": false, "explanation": "おうとう。三つ目の「お」が「と」に変わった一モーラ違い。"}, {"text": "応用", "is_correct": false, "explanation": "おうよう。「お」が「よ」に変わった一モーラ違い。"}, {"text": "横行", "is_correct": false, "explanation": "おうこう。「お」が「こ」に変わった一モーラ違い。"}, {"text": "王朝", "is_correct": false, "explanation": "おうちょう。「お」が「ちょ」に変わった一モーラ違い。"}], "explanations": {"往々": "音声どおりの語。", "桜桃": "おうとう。三つ目の「お」が「と」に変わった一モーラ違い。", "応用": "おうよう。「お」が「よ」に変わった一モーラ違い。", "横行": "おうこう。「お」が「こ」に変わった一モーラ違い。", "王朝": "おうちょう。「お」が「ちょ」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "往々"}, "level_3": {"options": [{"text": "往々", "is_correct": true, "explanation": "「往々にして」で、人がしばしば見た目で決めることを表す。"}, {"text": "散々", "is_correct": false, "explanation": "語形：「散々にして」という形はなく、ひどい様子を表す語。"}, {"text": "着々", "is_correct": false, "explanation": "語形：「着々にして」とは言わない。順調に進む様子の語。"}, {"text": "悠々", "is_correct": false, "explanation": "語形：「悠々にして人は決める」は不自然。ゆったりした様子の語。"}], "explanations": {"往々": "「往々にして」で、人がしばしば見た目で決めることを表す。", "散々": "語形：「散々にして」という形はなく、ひどい様子を表す語。", "着々": "語形：「着々にして」とは言わない。順調に進む様子の語。", "悠々": "語形：「悠々にして人は決める」は不自然。ゆったりした様子の語。"}, "sentence_index": 6, "correct_answer": "往々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "往々にして、私は来週引っ越す。", "explanation": "意味の誤り：一回だけの予定に、頻度を表す「往々にして」は使えない。"}, {"text": "往々にして、彼は一度だけ海外に行った。", "explanation": "意味の誤り：「一度だけ」と頻度を表す「往々にして」が矛盾する。"}, {"text": "私は往々にして、今朝かぎを一度なくした。", "explanation": "意味の誤り：一回だけの出来事に、頻度を表す「往々にして」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "そういうことは往々してある。", "corrected_sentence": "そういうことは往々にしてある。", "error_description": "語形の誤り：「往々にして」の「に」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
