INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36657, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "維持", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "意志", "is_correct": false, "explanation": "いし。「じ」が清音「し」になった清濁の違い。"}, {"text": "位置", "is_correct": false, "explanation": "いち。「じ」が「ち」に変わった一モーラ違い。"}, {"text": "意義", "is_correct": false, "explanation": "いぎ。「じ」が「ぎ」に変わった一モーラ違い。"}, {"text": "肘", "is_correct": false, "explanation": "ひじ。「い」が「ひ」に変わった一モーラ違い。"}, {"text": "虹", "is_correct": false, "explanation": "にじ。「い」が「に」に変わった一モーラ違い。"}], "explanations": {"維持": "音声どおりの語。", "意志": "いし。「じ」が清音「し」になった清濁の違い。", "位置": "いち。「じ」が「ち」に変わった一モーラ違い。", "意義": "いぎ。「じ」が「ぎ」に変わった一モーラ違い。", "肘": "ひじ。「い」が「ひ」に変わった一モーラ違い。", "虹": "にじ。「い」が「に」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "維持"}, "level_3": {"options": [{"text": "維持", "is_correct": true, "explanation": "有効性を変わらずに保つことを表す。"}, {"text": "発見", "is_correct": false, "explanation": "意味：「有効性を発見し得ない」は文意（もはや保てない）と合わない。"}, {"text": "出席", "is_correct": false, "explanation": "項構造：「有効性を出席する」とは言えない。"}, {"text": "紹介", "is_correct": false, "explanation": "意味：有効性を紹介するのでは、保てないという主張にならない。"}], "explanations": {"維持": "有効性を変わらずに保つことを表す。", "発見": "意味：「有効性を発見し得ない」は文意（もはや保てない）と合わない。", "出席": "項構造：「有効性を出席する」とは言えない。", "紹介": "意味：有効性を紹介するのでは、保てないという主張にならない。"}, "sentence_index": 0, "correct_answer": "維持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日家具を動かして、部屋の様子を維持した。", "explanation": "意味の誤り：毎日変えることは、そのまま保つ「維持」と矛盾する。"}, {"text": "壊れた家を維持して、新しく建て直した。", "explanation": "意味の誤り：建て直すことは今の状態を保つ「維持」と矛盾する。"}, {"text": "記録を大きく伸ばして、記録を維持した。", "explanation": "意味の誤り：記録を伸ばすのは変えることで、「維持」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36657, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "健康の維持を運動が大切だ。", "corrected_sentence": "健康の維持には運動が大切だ。", "error_description": "助詞の混同：目的を表すには「維持には」を使う。「維持を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36657, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「生命の維持」で、名詞と名詞をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「生命を維持と」は「維持」が名詞のままなので非文。"}, {"text": "に", "is_correct": false, "explanation": "「生命に維持」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「生命で維持」は非文。"}], "correct_answer": "の", "explanations": {"の": "「生命の維持」で、名詞と名詞をつなぐ。", "を": "「生命を維持と」は「維持」が名詞のままなので非文。", "に": "「生命に維持」は意味が通らない。", "で": "「生命で維持」は非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "other"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "変更", "is_correct": true, "explanation": "今の状態を変えることで、そのまま保つ「維持」の対義語。"}, {"text": "保存", "is_correct": false, "explanation": "そのまま残しておくことで、むしろ類義。"}, {"text": "管理", "is_correct": false, "explanation": "物事をとりしきることで、対義ではない。"}, {"text": "継続", "is_correct": false, "explanation": "続けることで、「維持」に近い語。"}], "correct_answer": "変更", "explanations": {"変更": "今の状態を変えることで、そのまま保つ「維持」の対義語。", "保存": "そのまま残しておくことで、むしろ類義。", "管理": "物事をとりしきることで、対義ではない。", "継続": "続けることで、「維持」に近い語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36657, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "維持", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "医師", "is_correct": false, "explanation": "いし。「じ」と「し」の清濁の違い。"}, {"text": "市", "is_correct": false, "explanation": "いち。「じ」が「ち」に変わった一モーラ違い。"}, {"text": "異議", "is_correct": false, "explanation": "いぎ。「じ」が「ぎ」に変わった一モーラ違い。"}, {"text": "肘", "is_correct": false, "explanation": "ひじ。「い」が「ひ」に変わった一モーラ違い。"}], "explanations": {"維持": "音声どおりの語。", "医師": "いし。「じ」と「し」の清濁の違い。", "市": "いち。「じ」が「ち」に変わった一モーラ違い。", "異議": "いぎ。「じ」が「ぎ」に変わった一モーラ違い。", "肘": "ひじ。「い」が「ひ」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "維持"}, "level_3": {"options": [{"text": "維持", "is_correct": true, "explanation": "平和を変わらずに保つことを表す。"}, {"text": "散歩", "is_correct": false, "explanation": "項構造：「平和を散歩する」とは言えない。"}, {"text": "成功", "is_correct": false, "explanation": "項構造：「成功」は「平和を」をとれない。"}, {"text": "返事", "is_correct": false, "explanation": "意味：平和を返事するという結びつきは意味をなさない。"}], "explanations": {"維持": "平和を変わらずに保つことを表す。", "散歩": "項構造：「平和を散歩する」とは言えない。", "成功": "項構造：「成功」は「平和を」をとれない。", "返事": "意味：平和を返事するという結びつきは意味をなさない。"}, "sentence_index": 6, "correct_answer": "維持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体重を減らすために、体重の維持を始めた。", "explanation": "意味の誤り：減らすことと、変えずに保つ「維持」が矛盾する。"}, {"text": "古い家を壊して、家の維持をした。", "explanation": "意味の誤り：壊すことは保つ「維持」の反対。"}, {"text": "体重を毎日どんどん増やして、維持している。", "explanation": "意味の誤り：増やし続けることは保つ「維持」と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
