INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36657, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「維持する」の目的語「温度」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「温度が維持してください」では依頼の目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「温度と」は並べる相手がなく非文。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「維持する」の目的語「温度」を示す。", "が": "「温度が維持してください」では依頼の目的語にならない。", "と": "「温度と」は並べる相手がなく非文。", "へ": "「へ」は方向を表し、目的語を示せない。"}, "error_tags": {"が": "object_marking", "と": "listing", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "変更", "is_correct": true, "explanation": "状態を変えることで、保つことを表す「維持」と反対。"}, {"text": "確保", "is_correct": false, "explanation": "しっかり手に入れておくことで、対義ではない。"}, {"text": "保持", "is_correct": false, "explanation": "保ち続けることで、類義語。"}, {"text": "記録", "is_correct": false, "explanation": "書き残すことで、対義関係にない。"}], "correct_answer": "変更", "explanations": {"変更": "状態を変えることで、保つことを表す「維持」と反対。", "確保": "しっかり手に入れておくことで、対義ではない。", "保持": "保ち続けることで、類義語。", "記録": "書き残すことで、対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51762, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "アルゴリズム", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "リズム", "is_correct": false, "explanation": "りずむ。後半の「リズム」だけが同じ実在語。モーラ数が違い、関門3を満たす一モーラ差の実在語は見つからない。"}, {"text": "アルカリ", "is_correct": false, "explanation": "あるかり。冒頭「アル」が同じ実在語。一モーラ差の実在語は見つからない。"}, {"text": "アルゴン", "is_correct": false, "explanation": "あるごん。冒頭「アルゴ」が同じ実在語。一モーラ差の実在語は見つからない。"}], "explanations": {"アルゴリズム": "音声どおりの語。", "リズム": "りずむ。後半の「リズム」だけが同じ実在語。モーラ数が違い、関門3を満たす一モーラ差の実在語は見つからない。", "アルカリ": "あるかり。冒頭「アル」が同じ実在語。一モーラ差の実在語は見つからない。", "アルゴン": "あるごん。冒頭「アルゴ」が同じ実在語。一モーラ差の実在語は見つからない。"}, "sentence_index": null, "correct_answer": "アルゴリズム"}, "level_3": {"options": [{"text": "アルゴリズム", "is_correct": true, "explanation": "人工知能による計算の手順を指し、分析を可能にする。"}, {"text": "カレンダー", "is_correct": false, "explanation": "意味：暦は習熟度分析を行う主体にならない。"}, {"text": "ポスター", "is_correct": false, "explanation": "意味：掲示物はリアルタイム分析をしない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "意味：制服は分析と結びつかない。"}], "explanations": {"アルゴリズム": "人工知能による計算の手順を指し、分析を可能にする。", "カレンダー": "意味：暦は習熟度分析を行う主体にならない。", "ポスター": "意味：掲示物はリアルタイム分析をしない。", "ユニフォーム": "意味：制服は分析と結びつかない。"}, "sentence_index": 0, "correct_answer": "アルゴリズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このアルゴリズムは甘くておいしい。", "explanation": "意味の誤り：計算手順に味はない。"}, {"text": "アルゴリズムを冷蔵庫に入れて冷やした。", "explanation": "意味の誤り：計算手順は物ではないので冷やせない。"}, {"text": "このアルゴリズムを一枚もらった。", "explanation": "助数詞の誤り：手順は「枚」で数えられる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
