INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51762, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「アルゴリズムに入力する」で入力先を示す。"}, {"text": "が", "is_correct": false, "explanation": "「アルゴリズムが入力し」では入力先にならない。"}, {"text": "の", "is_correct": false, "explanation": "「アルゴリズムの入力し」は非文。"}, {"text": "から", "is_correct": false, "explanation": "「アルゴリズムから入力し」は入力先と逆で不自然。"}], "correct_answer": "に", "explanations": {"に": "「アルゴリズムに入力する」で入力先を示す。", "が": "「アルゴリズムが入力し」では入力先にならない。", "の": "「アルゴリズムの入力し」は非文。", "から": "「アルゴリズムから入力し」は入力先と逆で不自然。"}, "error_tags": {"が": "object_marking", "の": "other", "から": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51762, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "アルゴリズム", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "アルミ", "is_correct": false, "explanation": "あるみ。冒頭「アル」が同じ実在語。一モーラ差の実在語は見つからない。"}, {"text": "アルコール", "is_correct": false, "explanation": "あるこーる。冒頭が似た実在語。一モーラ差ではない。"}, {"text": "アレルギー", "is_correct": false, "explanation": "あれるぎー。冒頭が似た実在語。一モーラ差ではない。"}], "explanations": {"アルゴリズム": "音声どおりの語。", "アルミ": "あるみ。冒頭「アル」が同じ実在語。一モーラ差の実在語は見つからない。", "アルコール": "あるこーる。冒頭が似た実在語。一モーラ差ではない。", "アレルギー": "あれるぎー。冒頭が似た実在語。一モーラ差ではない。"}, "sentence_index": null, "correct_answer": "アルゴリズム"}, "level_3": {"options": [{"text": "アルゴリズム", "is_correct": true, "explanation": "授業で計算の手順を学んだことを表す。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "意味：ハンカチは授業で学ぶ内容にならない。"}, {"text": "エプロン", "is_correct": false, "explanation": "意味：衣服は学ぶ対象にならない。"}, {"text": "バケツ", "is_correct": false, "explanation": "意味：バケツは学ぶ内容にならない。"}], "explanations": {"アルゴリズム": "授業で計算の手順を学んだことを表す。", "ハンカチ": "意味：ハンカチは授業で学ぶ内容にならない。", "エプロン": "意味：衣服は学ぶ対象にならない。", "バケツ": "意味：バケツは学ぶ内容にならない。"}, "sentence_index": 6, "correct_answer": "アルゴリズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "良いアルゴリズムが時間が減る。", "explanation": "助詞の混同：手段は「アルゴリズムで」。"}, {"text": "良いアルゴリズムを三匹飼っている。", "explanation": "助数詞・意味の誤り：手順は生き物ではない。"}, {"text": "良いアルゴリズムを食べて元気になった。", "explanation": "意味の誤り：計算手順は食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
