INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37303, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "設計", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "石鹸", "is_correct": false, "explanation": "せっけん。最後の「い」が「ん」に変わった一モーラ違い。"}, {"text": "切開", "is_correct": false, "explanation": "せっかい。「け」が「か」に変わった一モーラ違い。"}, {"text": "絶景", "is_correct": false, "explanation": "ぜっけい。「せ」が濁音「ぜ」になった清濁の違い。"}], "explanations": {"設計": "音声どおりの語。", "石鹸": "せっけん。最後の「い」が「ん」に変わった一モーラ違い。", "切開": "せっかい。「け」が「か」に変わった一モーラ違い。", "絶景": "ぜっけい。「せ」が濁音「ぜ」になった清濁の違い。"}, "sentence_index": null, "correct_answer": "設計"}, "level_3": {"options": [{"text": "設計", "is_correct": true, "explanation": "システムの形や仕組みを計画して決めることを表す。"}, {"text": "見学", "is_correct": false, "explanation": "意味：システムを見学して運用する、では教授陣の役割にならない。"}, {"text": "卒業", "is_correct": false, "explanation": "項構造：「システムを卒業し」は不自然。"}, {"text": "到着", "is_correct": false, "explanation": "項構造：「システムを到着し」とは言えない。"}], "explanations": {"設計": "システムの形や仕組みを計画して決めることを表す。", "見学": "意味：システムを見学して運用する、では教授陣の役割にならない。", "卒業": "項構造：「システムを卒業し」は不自然。", "到着": "項構造：「システムを到着し」とは言えない。"}, "sentence_index": 0, "correct_answer": "設計"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は家の設計を食べている。", "explanation": "意味の誤り：設計は食べるものではない。"}, {"text": "父は家に設計をしている。", "explanation": "助詞の混同：対象は「家の設計」。「家に」は不自然。"}, {"text": "父は今夜の料理の設計をしている。", "explanation": "意味の誤り：「設計」は建物や製品の形・仕組みを決めることで、料理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
