INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37303, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "設計", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "石灰", "is_correct": false, "explanation": "せっかい。「け」が「か」に変わった一モーラ違い。"}, {"text": "絶景", "is_correct": false, "explanation": "ぜっけい。「せ」が濁音「ぜ」になった清濁の違い。"}, {"text": "接見", "is_correct": false, "explanation": "せっけん。末尾の「い」が「ん」に変わった一モーラ違い。"}], "explanations": {"設計": "音声どおりの語。", "石灰": "せっかい。「け」が「か」に変わった一モーラ違い。", "絶景": "ぜっけい。「せ」が濁音「ぜ」になった清濁の違い。", "接見": "せっけん。末尾の「い」が「ん」に変わった一モーラ違い。"}, "sentence_index": null, "correct_answer": "設計"}, "level_3": {"options": [{"text": "設計", "is_correct": true, "explanation": "学校の形や仕組みを計画していることを表す。"}, {"text": "到着", "is_correct": false, "explanation": "項構造：「学校を到着している」とは言わない。"}, {"text": "成功", "is_correct": false, "explanation": "項構造：「成功」は「学校を」をとれない。"}, {"text": "入学", "is_correct": false, "explanation": "項構造：「学校を入学する」とは言わない。"}], "explanations": {"設計": "学校の形や仕組みを計画していることを表す。", "到着": "項構造：「学校を到着している」とは言わない。", "成功": "項構造：「成功」は「学校を」をとれない。", "入学": "項構造：「学校を入学する」とは言わない。"}, "sentence_index": 6, "correct_answer": "設計"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の天気の設計に一年かかった。", "explanation": "意味の誤り：天気は人が形や仕組みを計画するものではない。"}, {"text": "朝ごはんの設計に一年かかった。", "explanation": "意味の誤り：食事は「設計」する対象ではない。"}, {"text": "ロボットを設計に一年かかった。", "explanation": "助詞の混同：「ロボットの設計」と「の」でつなぐ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
