INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41329, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酵母", "is_correct": true, "explanation": "こうぼ。正解。"}, {"text": "候補", "is_correct": false, "explanation": "こうほ。最後のモーラが濁音ぼ／清音ほで違う。"}, {"text": "工場", "is_correct": false, "explanation": "こうば。最後のモーラがぼ／ばで一モーラ違う。"}, {"text": "工房", "is_correct": false, "explanation": "こうぼう。最後が長音になる長短の違い。"}], "explanations": {"酵母": "こうぼ。正解。", "候補": "こうほ。最後のモーラが濁音ぼ／清音ほで違う。", "工場": "こうば。最後のモーラがぼ／ばで一モーラ違う。", "工房": "こうぼう。最後が長音になる長短の違い。"}, "sentence_index": null, "correct_answer": "酵母"}, "level_3": {"options": [{"text": "酵母", "is_correct": true, "explanation": "パン作りに使う微生物で文脈に合う。"}, {"text": "電池", "is_correct": false, "explanation": "意味：電池はパン作りに用いない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "意味：製パンの材料ではない。"}, {"text": "石油", "is_correct": false, "explanation": "連語：「天然石油を用いた製パン」は不自然。"}], "explanations": {"酵母": "パン作りに使う微生物で文脈に合う。", "電池": "意味：電池はパン作りに用いない。", "鉛筆": "意味：製パンの材料ではない。", "石油": "連語：「天然石油を用いた製パン」は不自然。"}, "sentence_index": 0, "correct_answer": "酵母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "酵母を着て出かけた。", "explanation": "酵母は服ではない。"}, {"text": "酵母に座って休んだ。", "explanation": "酵母は椅子ではない。"}, {"text": "酵母で手紙を書いた。", "explanation": "酵母は筆記用具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
