INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39715, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「〜を通じて」の形を作る。"}, {"text": "が", "is_correct": false, "explanation": "「〜が通じて」では意味が変わり非文。"}, {"text": "に", "is_correct": false, "explanation": "「〜に通じて」は別の意味になる。"}, {"text": "で", "is_correct": false, "explanation": "「〜で通じて」とは言わない。"}], "correct_answer": "を", "explanations": {"を": "「〜を通じて」の形を作る。", "が": "「〜が通じて」では意味が変わり非文。", "に": "「〜に通じて」は別の意味になる。", "で": "「〜で通じて」とは言わない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39715, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指先", "is_correct": true, "explanation": "ゆびさき。正解。"}, {"text": "行き先", "is_correct": false, "explanation": "ゆきさき。び→きの一モーラ違い。"}, {"text": "指差し", "is_correct": false, "explanation": "ゆびさし。き→しの一モーラ違い。"}, {"text": "指貫", "is_correct": false, "explanation": "ゆびぬき。さ→ぬの一モーラ違い。"}], "explanations": {"指先": "ゆびさき。正解。", "行き先": "ゆきさき。び→きの一モーラ違い。", "指差し": "ゆびさし。き→しの一モーラ違い。", "指貫": "ゆびぬき。さ→ぬの一モーラ違い。"}, "sentence_index": null, "correct_answer": "指先"}, "level_3": {"options": [{"text": "指先", "is_correct": true, "explanation": "ピアノを弾く手の部分として合う。"}, {"text": "靴", "is_correct": false, "explanation": "意味：靴でピアノは弾かない。"}, {"text": "耳", "is_correct": false, "explanation": "意味：ピアノを弾く部位ではない。"}, {"text": "屋根", "is_correct": false, "explanation": "意味：体の部分でもない。"}], "explanations": {"指先": "ピアノを弾く手の部分として合う。", "靴": "意味：靴でピアノは弾かない。", "耳": "意味：ピアノを弾く部位ではない。", "屋根": "意味：体の部分でもない。"}, "sentence_index": 6, "correct_answer": "指先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "職人の指先を動きを見ている。", "explanation": "助詞の混同：連体修飾は「の」。"}, {"text": "職人の指先が二台の動きを見ている。", "explanation": "助数詞の誤り：「台」は機械を数える。"}, {"text": "職人の指先の動きを見ていた明日。", "explanation": "時の誤り：過去形と「明日」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
