INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39715, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "けがをした場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「けがをした」に既に目的語があり非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、場所にならない。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列を示し、ここでは不自然。"}], "correct_answer": "に", "explanations": {"に": "けがをした場所を示す。", "を": "「けがをした」に既に目的語があり非文。", "へ": "方向を示し、場所にならない。", "と": "相手・並列を示し、ここでは不自然。"}, "error_tags": {"を": "object_marking", "へ": "direction", "と": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纏う", "is_correct": true, "explanation": "まとう。正解。"}, {"text": "惑う", "is_correct": false, "explanation": "まどう。と→どの清濁の違い。"}, {"text": "迷う", "is_correct": false, "explanation": "まよう。と→よの一モーラ違い。"}, {"text": "下等", "is_correct": false, "explanation": "かとう。ま→かの一モーラ違い。"}], "explanations": {"纏う": "まとう。正解。", "惑う": "まどう。と→どの清濁の違い。", "迷う": "まよう。と→よの一モーラ違い。", "下等": "かとう。ま→かの一モーラ違い。"}, "sentence_index": null, "correct_answer": "纏う"}, "level_3": {"options": [{"text": "纏い", "is_correct": true, "explanation": "美しさを身に帯びる意味で合う。"}, {"text": "食べ", "is_correct": false, "explanation": "連語：美しさを食べるとは言わない。"}, {"text": "割り", "is_correct": false, "explanation": "連語：美しさを割ることはできない。"}, {"text": "洗い", "is_correct": false, "explanation": "意味：美しさを洗うは意味をなさない。"}], "explanations": {"纏い": "美しさを身に帯びる意味で合う。", "食べ": "連語：美しさを食べるとは言わない。", "割り": "連語：美しさを割ることはできない。", "洗い": "意味：美しさを洗うは意味をなさない。"}, "sentence_index": 0, "correct_answer": "纏い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は白いドレスに纏っていた。", "explanation": "助詞の混同：身に着ける物は「を」。"}, {"text": "彼女は白いドレスを纏っていた明日。", "explanation": "時の誤り：過去形と「明日」が合わない。"}, {"text": "白いドレスを彼女纏っては。", "explanation": "語順の誤り：文の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は白いドレスが纏っていた。", "corrected_sentence": "彼女は白いドレスを纏っていた。", "error_description": "助詞の混同：「纏う」の目的語は「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "纏う", "is_correct": true, "explanation": "名詞「リンゴ」を修飾する連体形（辞書形）。"}, {"text": "纏って", "is_correct": false, "explanation": "て形は後に動詞を要し名詞に続かない。"}, {"text": "纏わ", "is_correct": false, "explanation": "未然形で、「ない」などが必要。"}, {"text": "纏え", "is_correct": false, "explanation": "命令形で、名詞を修飾できない。"}], "correct_form": "纏う", "base_form": "纏う", "form_label": "活用", "sentence_index": 1, "explanations": {"纏う": "名詞「リンゴ」を修飾する連体形（辞書形）。", "纏って": "て形は後に動詞を要し名詞に続かない。", "纏わ": "未然形で、「ない」などが必要。", "纏え": "命令形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「纏う」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり他動詞の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、ここでは不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し非文になる。"}], "correct_answer": "を", "explanations": {"を": "「纏う」の目的語を示す。", "が": "主格になり他動詞の目的語にならない。", "に": "着点を示し、ここでは不自然。", "で": "手段を表し非文になる。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "身に着けたものを取り去る。纏うの反対。"}, {"text": "着る", "is_correct": false, "explanation": "類義語であり対義語ではない。"}, {"text": "飾る", "is_correct": false, "explanation": "近い分野だが反対の意味ではない。"}, {"text": "包む", "is_correct": false, "explanation": "覆う意味で、反対ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "身に着けたものを取り去る。纏うの反対。", "着る": "類義語であり対義語ではない。", "飾る": "近い分野だが反対の意味ではない。", "包む": "覆う意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纏う", "is_correct": true, "explanation": "まとう。正解。"}, {"text": "迷う", "is_correct": false, "explanation": "まよう。三番目と二番目の違い：と→よ。"}, {"text": "惑う", "is_correct": false, "explanation": "まどう。清濁の違い：と／ど。"}, {"text": "下等", "is_correct": false, "explanation": "かとう。最初のモーラま→か。"}], "explanations": {"纏う": "まとう。正解。", "迷う": "まよう。三番目と二番目の違い：と→よ。", "惑う": "まどう。清濁の違い：と／ど。", "下等": "かとう。最初のモーラま→か。"}, "sentence_index": null, "correct_answer": "纏う"}, "level_3": {"options": [{"text": "纏う", "is_correct": true, "explanation": "雰囲気を帯びる意味で合う。"}, {"text": "投げる", "is_correct": false, "explanation": "連語：空気を投げるとは言わない。"}, {"text": "切る", "is_correct": false, "explanation": "連語：空気を切るは別の意味で人物描写にならない。"}, {"text": "売る", "is_correct": false, "explanation": "意味：空気を売る人は文脈に合わない。"}], "explanations": {"纏う": "雰囲気を帯びる意味で合う。", "投げる": "連語：空気を投げるとは言わない。", "切る": "連語：空気を切るは別の意味で人物描写にならない。", "売る": "意味：空気を売る人は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "纏う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春の花は甘い香りが纏う。", "explanation": "助詞の混同：目的語は「を」。"}, {"text": "春の花は甘い香りを纏った明日。", "explanation": "時の誤り：過去形と「明日」が矛盾。"}, {"text": "甘い香りを春の纏う花は。", "explanation": "語順の誤り：係り受けが壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山は朝の霧に纏っている。", "corrected_sentence": "山は朝の霧を纏っている。", "error_description": "助詞の混同：「纏う」は「を」をとる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "纏っ", "is_correct": true, "explanation": "「ている」に続く促音便のて形。"}, {"text": "纏い", "is_correct": false, "explanation": "連用形で「ている」に直接続かない。"}, {"text": "纏わ", "is_correct": false, "explanation": "未然形で「ない」が必要。"}, {"text": "纏お", "is_correct": false, "explanation": "意向形の語幹で「う」が必要。"}], "correct_form": "纏っ", "base_form": "纏う", "form_label": "活用", "sentence_index": 7, "explanations": {"纏っ": "「ている」に続く促音便のて形。", "纏い": "連用形で「ている」に直接続かない。", "纏わ": "未然形で「ない」が必要。", "纏お": "意向形の語幹で「う」が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52082, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「纏う」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格で目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し非文。"}], "correct_answer": "を", "explanations": {"を": "「纏う」の目的語を示す。", "が": "主格で目的語にならない。", "で": "手段を表し不自然。", "へ": "方向を示し非文。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱ぐ", "is_correct": true, "explanation": "身に着けたものを外す。纏うの反対。"}, {"text": "羽織る", "is_correct": false, "explanation": "身に着ける類義語。"}, {"text": "帯びる", "is_correct": false, "explanation": "性質を持つ類義語。"}, {"text": "被る", "is_correct": false, "explanation": "頭に着ける意味で反対ではない。"}], "correct_answer": "脱ぐ", "explanations": {"脱ぐ": "身に着けたものを外す。纏うの反対。", "羽織る": "身に着ける類義語。", "帯びる": "性質を持つ類義語。", "被る": "頭に着ける意味で反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
