INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36155, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「構築する」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格では目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「「神経系」の構築し」は非文。動詞の前に「の」は置けない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し不自然。"}], "correct_answer": "を", "explanations": {"を": "「構築する」の目的語を示す。", "が": "主格では目的語にならない。", "の": "「「神経系」の構築し」は非文。動詞の前に「の」は置けない。", "へ": "方向を示し不自然。"}, "error_tags": {"が": "object_marking", "の": "genitive", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36155, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "論理", "is_correct": true, "explanation": "ろんり。正解。"}, {"text": "文理", "is_correct": false, "explanation": "ぶんり。最初のモーラろ→ぶ。"}, {"text": "千里", "is_correct": false, "explanation": "せんり。最初のモーラろ→せ。"}, {"text": "論旨", "is_correct": false, "explanation": "ろんし。最後のモーラり→し。"}, {"text": "論議", "is_correct": false, "explanation": "ろんぎ。最後のモーラり→ぎ。"}], "explanations": {"論理": "ろんり。正解。", "文理": "ぶんり。最初のモーラろ→ぶ。", "千里": "せんり。最初のモーラろ→せ。", "論旨": "ろんし。最後のモーラり→し。", "論議": "ろんぎ。最後のモーラり→ぎ。"}, "sentence_index": null, "correct_answer": "論理"}, "level_3": {"options": [{"text": "論理", "is_correct": true, "explanation": "「論理の力」で考えの筋道を立てる力を表し、数学で育てる力として合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "意味：数学で「鉛筆の力」を育てるとは言わない。"}, {"text": "階段", "is_correct": false, "explanation": "意味：「階段の力」は数学で育てる力ではない。"}, {"text": "野菜", "is_correct": false, "explanation": "意味：「野菜の力」は数学と関係がない。"}], "explanations": {"論理": "「論理の力」で考えの筋道を立てる力を表し、数学で育てる力として合う。", "鉛筆": "意味：数学で「鉛筆の力」を育てるとは言わない。", "階段": "意味：「階段の力」は数学で育てる力ではない。", "野菜": "意味：「野菜の力」は数学と関係がない。"}, "sentence_index": 6, "correct_answer": "論理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "感情より論理が大事にする人だ。", "explanation": "助詞の混同：「大事にする」の目的語は「を」。"}, {"text": "感情より論理を二枚大事にする人だ。", "explanation": "助数詞の誤り：論理は「枚」で数えない。"}, {"text": "感情より論理を大事にした人だ明日。", "explanation": "時の誤り：過去と「明日」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
