INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39369, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "イノベーション", "is_correct": true, "explanation": "正解。新しい考えで物事を大きく変えること。"}, {"text": "リノベーション", "is_correct": false, "explanation": "「りのべーしょん」。最初のモーラ「い」が「り」に変わる。建物の改修のこと。"}, {"text": "モチベーション", "is_correct": false, "explanation": "「もちべーしょん」。やる気のこと。前半の音が異なる。"}, {"text": "エレベーション", "is_correct": false, "explanation": "「えれべーしょん」。高さ・標高のこと。前半の音が異なる。"}], "explanations": {"イノベーション": "正解。新しい考えで物事を大きく変えること。", "リノベーション": "「りのべーしょん」。最初のモーラ「い」が「り」に変わる。建物の改修のこと。", "モチベーション": "「もちべーしょん」。やる気のこと。前半の音が異なる。", "エレベーション": "「えれべーしょん」。高さ・標高のこと。前半の音が異なる。"}, "sentence_index": null, "correct_answer": "イノベーション"}, "level_3": {"options": [{"text": "イノベーション", "is_correct": true, "explanation": "新たな価値を生む技術革新が文脈に合う。"}, {"text": "アンケート", "is_correct": false, "explanation": "意味：アンケートは「価値を生む」「加速させる」対象として不自然。"}, {"text": "トラブル", "is_correct": false, "explanation": "意味：市場に価値を生むトラブルは文脈と矛盾する。"}, {"text": "リスク", "is_correct": false, "explanation": "連語：「価値を生むリスクを加速させる」は結びつきが不自然。"}], "explanations": {"イノベーション": "新たな価値を生む技術革新が文脈に合う。", "アンケート": "意味：アンケートは「価値を生む」「加速させる」対象として不自然。", "トラブル": "意味：市場に価値を生むトラブルは文脈と矛盾する。", "リスク": "連語：「価値を生むリスクを加速させる」は結びつきが不自然。"}, "sentence_index": 0, "correct_answer": "イノベーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "イノベーションを一冊買った。", "explanation": "助数詞の誤り：抽象名詞を「冊」で数えることはできない。"}, {"text": "この会社がイノベーションで大切にしている。", "explanation": "助詞の混同：「を大切にする」が正しい。"}, {"text": "イノベーションは昨日起こしている。", "explanation": "活用・アスペクトの誤り：「昨日」と「ている」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
