INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39369, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「情報に基づく」が正しい結びつき。"}, {"text": "を", "is_correct": false, "explanation": "「情報を基づき」は非文。基づくは「に」をとる。"}, {"text": "で", "is_correct": false, "explanation": "「情報で基づき」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「情報が基づき」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「情報に基づく」が正しい結びつき。", "を": "「情報を基づき」は非文。基づくは「に」をとる。", "で": "「情報で基づき」は不自然。", "が": "「情報が基づき」は意味が通らない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "が": "topic_vs_subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
