INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39369, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「仕事が楽になる」で主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「仕事を楽になった」は非文。「なる」は目的語をとらない。"}, {"text": "へ", "is_correct": false, "explanation": "「仕事へ楽になった」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「仕事と楽になった」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「仕事が楽になる」で主語を示す。", "を": "「仕事を楽になった」は非文。「なる」は目的語をとらない。", "へ": "「仕事へ楽になった」は意味が通らない。", "と": "「仕事と楽になった」は不自然。"}, "error_tags": {"を": "object_marking", "へ": "direction", "と": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宿る", "is_correct": true, "explanation": "正解。「やどる」。"}, {"text": "破る", "is_correct": false, "explanation": "「やぶる」。二番目のモーラ「ど」が「ぶ」に変わる。"}, {"text": "踊る", "is_correct": false, "explanation": "「おどる」。最初のモーラ「や」が「お」に変わる。"}, {"text": "戻る", "is_correct": false, "explanation": "「もどる」。最初のモーラ「や」が「も」に変わる。"}], "explanations": {"宿る": "正解。「やどる」。", "破る": "「やぶる」。二番目のモーラ「ど」が「ぶ」に変わる。", "踊る": "「おどる」。最初のモーラ「や」が「お」に変わる。", "戻る": "「もどる」。最初のモーラ「や」が「も」に変わる。"}, "sentence_index": null, "correct_answer": "宿る"}, "level_3": {"options": [{"text": "宿っ", "is_correct": true, "explanation": "駆動力が内に存在している、の意で自然。"}, {"text": "走っ", "is_correct": false, "explanation": "意味：駆動力が「走っている」は比喩として不自然。"}, {"text": "壊れ", "is_correct": false, "explanation": "意味：「内にこそ壊れている」は文意が通らない。"}, {"text": "隠し", "is_correct": false, "explanation": "項構造：「隠している」は他動詞で目的語が必要。"}], "explanations": {"宿っ": "駆動力が内に存在している、の意で自然。", "走っ": "意味：駆動力が「走っている」は比喩として不自然。", "壊れ": "意味：「内にこそ壊れている」は文意が通らない。", "隠し": "項構造：「隠している」は他動詞で目的語が必要。"}, "sentence_index": 0, "correct_answer": "宿っ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木には神様を宿ると言われている。", "explanation": "助詞の混同：自動詞なので「神様が宿る」。"}, {"text": "この木で神様が宿ると言われている。", "explanation": "助詞の混同：存在する場所は「に」で示す。"}, {"text": "この木には神様が宿すと言われている。", "explanation": "自他の混同：「宿す」は他動詞。存在を表すのは自動詞「宿る」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホテルに一晩宿った。", "corrected_sentence": "彼女の目に強い決意が宿った。", "error_description": "この義項は見えないものが内側に存在する意味で、人が泊まる意味ではない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "宿っ", "is_correct": true, "explanation": "「ている」の前は促音便の「宿っ」。"}, {"text": "宿り", "is_correct": false, "explanation": "連用形だが「宿りている」は非文。"}, {"text": "宿ら", "is_correct": false, "explanation": "未然形。「宿らている」は非文。"}, {"text": "宿れ", "is_correct": false, "explanation": "「宿れている」は非文。"}], "correct_form": "宿っ", "base_form": "宿る", "form_label": "て形", "sentence_index": 1, "explanations": {"宿っ": "「ている」の前は促音便の「宿っ」。", "宿り": "連用形だが「宿りている」は非文。", "宿ら": "未然形。「宿らている」は非文。", "宿れ": "「宿れている」は非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所「瞳に（は）」。"}, {"text": "を", "is_correct": false, "explanation": "「瞳をは」は非文。"}, {"text": "と", "is_correct": false, "explanation": "「瞳とは」は定義の意味になり文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「瞳がは」は非文。"}], "correct_answer": "に", "explanations": {"に": "存在の場所「瞳に（は）」。", "を": "「瞳をは」は非文。", "と": "「瞳とは」は定義の意味になり文が成り立たない。", "が": "「瞳がは」は非文。"}, "error_tags": {"を": "object_marking", "と": "other", "が": "topic_vs_subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宿る", "is_correct": true, "explanation": "正解。「やどる」。"}, {"text": "宿す", "is_correct": false, "explanation": "「やどす」。最後のモーラ「る」が「す」に変わる。"}, {"text": "辿る", "is_correct": false, "explanation": "「たどる」。最初のモーラ「や」が「た」に変わる。"}, {"text": "頼る", "is_correct": false, "explanation": "「たよる」。「やど」が「たよ」に変わる。"}], "explanations": {"宿る": "正解。「やどる」。", "宿す": "「やどす」。最後のモーラ「る」が「す」に変わる。", "辿る": "「たどる」。最初のモーラ「や」が「た」に変わる。", "頼る": "「たよる」。「やど」が「たよ」に変わる。"}, "sentence_index": null, "correct_answer": "宿る"}, "level_3": {"options": [{"text": "宿っ", "is_correct": true, "explanation": "小さな体に力が存在している意で自然。"}, {"text": "落ち", "is_correct": false, "explanation": "意味：力が体に「落ちている」は不自然。"}, {"text": "売っ", "is_correct": false, "explanation": "項構造：「売っている」は他動詞で、力が主語では成り立たない。"}, {"text": "溶け", "is_correct": false, "explanation": "意味：力が体に溶けているは比喩として不自然。"}], "explanations": {"宿っ": "小さな体に力が存在している意で自然。", "落ち": "意味：力が体に「落ちている」は不自然。", "売っ": "項構造：「売っている」は他動詞で、力が主語では成り立たない。", "溶け": "意味：力が体に溶けているは比喩として不自然。"}, "sentence_index": 6, "correct_answer": "宿っ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅人の宿る種を大切に植えた。", "explanation": "義項の誤り：人が泊まる意味になり、種の中に存在する意味と合わない。"}, {"text": "命を宿る種を大切に植えた。", "explanation": "助詞の混同：「宿る」は自動詞。「命の／が宿る」。"}, {"text": "命の宿す種を大切に植えた。", "explanation": "自他の混同：「宿す」は他動詞で目的語が必要。「命の宿る種」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちの家に宿って、楽しかった。", "corrected_sentence": "その絵には画家の思いが宿っている。", "error_description": "この義項は見えないものが内に存在する意味で、人がとまる意味ではない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "宿る", "is_correct": true, "explanation": "引用「と」の前で、一般的な事実を辞書形で述べる。"}, {"text": "宿り", "is_correct": false, "explanation": "連用形。「宿りと」は非文。"}, {"text": "宿って", "is_correct": false, "explanation": "て形。「宿ってと」は非文。"}, {"text": "宿ら", "is_correct": false, "explanation": "未然形。「宿らと」は非文。"}], "correct_form": "宿る", "base_form": "宿る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"宿る": "引用「と」の前で、一般的な事実を辞書形で述べる。", "宿り": "連用形。「宿りと」は非文。", "宿って": "て形。「宿ってと」は非文。", "宿ら": "未然形。「宿らと」は非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52288, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「宿る」の主語。"}, {"text": "を", "is_correct": false, "explanation": "「魂を宿る」は非文。他動詞なら「宿す」。"}, {"text": "で", "is_correct": false, "explanation": "「魂で宿る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「魂へ宿る」は非文。"}], "correct_answer": "が", "explanations": {"が": "自動詞「宿る」の主語。", "を": "「魂を宿る」は非文。他動詞なら「宿す」。", "で": "「魂で宿る」は意味が通らない。", "へ": "「魂へ宿る」は非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消費", "is_correct": true, "explanation": "正解。「しょうひ」。"}, {"text": "消化", "is_correct": false, "explanation": "「しょうか」。最後のモーラ「ひ」が「か」に変わる。"}, {"text": "承知", "is_correct": false, "explanation": "「しょうち」。最後のモーラ「ひ」が「ち」に変わる。"}, {"text": "正気", "is_correct": false, "explanation": "「しょうき」。最後のモーラ「ひ」が「き」に変わる。"}, {"text": "勝負", "is_correct": false, "explanation": "「しょうぶ」。最後のモーラ「ひ」が「ぶ」に変わる。"}], "explanations": {"消費": "正解。「しょうひ」。", "消化": "「しょうか」。最後のモーラ「ひ」が「か」に変わる。", "承知": "「しょうち」。最後のモーラ「ひ」が「ち」に変わる。", "正気": "「しょうき」。最後のモーラ「ひ」が「き」に変わる。", "勝負": "「しょうぶ」。最後のモーラ「ひ」が「ぶ」に変わる。"}, "sentence_index": null, "correct_answer": "消費"}, "level_3": {"options": [{"text": "消費", "is_correct": true, "explanation": "燃料を使ってなくすこと。「大量消費」。"}, {"text": "研究", "is_correct": false, "explanation": "連語：「化石燃料の大量研究」とはいわず、森林破壊と並ぶ活動にならない。"}, {"text": "説明", "is_correct": false, "explanation": "意味：「大量説明」は意味が通らない。"}, {"text": "貯金", "is_correct": false, "explanation": "連語：「化石燃料の大量貯金」は結びつかない。"}], "explanations": {"消費": "燃料を使ってなくすこと。「大量消費」。", "研究": "連語：「化石燃料の大量研究」とはいわず、森林破壊と並ぶ活動にならない。", "説明": "意味：「大量説明」は意味が通らない。", "貯金": "連語：「化石燃料の大量貯金」は結びつかない。"}, "sentence_index": 0, "correct_answer": "消費"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は電気の消費を増える。", "explanation": "助詞の混同：「増える」は自動詞なので「が」。"}, {"text": "夏は電気の消費するが増える。", "explanation": "品詞の誤り：名詞として使う位置に動詞「消費する」は使えない。"}, {"text": "夏は電気を消費が増える。", "explanation": "助詞の誤り：名詞「消費」の対象は「の」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この車はガソリンを多く消費される。", "corrected_sentence": "この車はガソリンを多く消費する。", "error_description": "「を」をとるので能動の「消費する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アイデンティティを植え付ける」の目的語。"}, {"text": "が", "is_correct": false, "explanation": "「アイデンティティが植え付けよう」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「アイデンティティで植え付ける」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「アイデンティティへ植え付ける」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「アイデンティティを植え付ける」の目的語。", "が": "「アイデンティティが植え付けよう」は非文。", "で": "「アイデンティティで植え付ける」は意味が通らない。", "へ": "「アイデンティティへ植え付ける」は不自然。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生産", "is_correct": true, "explanation": "作り出すこと。使ってなくす「消費」の反対。"}, {"text": "節約", "is_correct": false, "explanation": "なるべく使わないことで、反対の関係ではない。"}, {"text": "購入", "is_correct": false, "explanation": "買うことで、消費の一部であり反対ではない。"}, {"text": "流通", "is_correct": false, "explanation": "物が行きわたることで反対ではない。"}], "correct_answer": "生産", "explanations": {"生産": "作り出すこと。使ってなくす「消費」の反対。", "節約": "なるべく使わないことで、反対の関係ではない。", "購入": "買うことで、消費の一部であり反対ではない。", "流通": "物が行きわたることで反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消費", "is_correct": true, "explanation": "正解。「しょうひ」。"}, {"text": "商品", "is_correct": false, "explanation": "「しょうひん」。最後に「ん」が加わる。"}, {"text": "小児", "is_correct": false, "explanation": "「しょうに」。最後のモーラ「ひ」が「に」に変わる。"}, {"text": "賞味", "is_correct": false, "explanation": "「しょうみ」。最後のモーラ「ひ」が「み」に変わる。"}, {"text": "将棋", "is_correct": false, "explanation": "「しょうぎ」。最後のモーラ「ひ」が「ぎ」に変わる。"}], "explanations": {"消費": "正解。「しょうひ」。", "商品": "「しょうひん」。最後に「ん」が加わる。", "小児": "「しょうに」。最後のモーラ「ひ」が「に」に変わる。", "賞味": "「しょうみ」。最後のモーラ「ひ」が「み」に変わる。", "将棋": "「しょうぎ」。最後のモーラ「ひ」が「ぎ」に変わる。"}, "sentence_index": null, "correct_answer": "消費"}, "level_3": {"options": [{"text": "消費", "is_correct": true, "explanation": "運動でエネルギーを使う、が自然。"}, {"text": "発見", "is_correct": false, "explanation": "意味：運動でエネルギーを発見するは不自然。"}, {"text": "輸入", "is_correct": false, "explanation": "意味・語域：輸入は国の経済の語で文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "連語：「エネルギーを注文する」は結びつかない。"}], "explanations": {"消費": "運動でエネルギーを使う、が自然。", "発見": "意味：運動でエネルギーを発見するは不自然。", "輸入": "意味・語域：輸入は国の経済の語で文脈に合わない。", "注文": "連語：「エネルギーを注文する」は結びつかない。"}, "sentence_index": 6, "correct_answer": "消費"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紙の消費するをおさえる工夫をしている。", "explanation": "品詞の誤り：「おさえる」の目的語は名詞「消費」で、「消費する」は使えない。"}, {"text": "紙が消費をおさえる工夫をしている。", "explanation": "助詞の混同：「紙の消費」とすべき。"}, {"text": "紙を消費をおさえる工夫をしている。", "explanation": "助詞の誤り：名詞「消費」の対象は「紙の」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この料理は米をたくさん消費になる。", "corrected_sentence": "この料理は米をたくさん消費する。", "error_description": "「を」をとる動詞としては「消費する」。「消費になる」とはいわない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35505, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「エネルギーを消費する」の目的語。"}, {"text": "に", "is_correct": false, "explanation": "「エネルギーに消費できる」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「エネルギーで消費できる」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「エネルギーへ消費できる」は非文。"}], "correct_answer": "を", "explanations": {"を": "「エネルギーを消費する」の目的語。", "に": "「エネルギーに消費できる」は非文。", "で": "「エネルギーで消費できる」は意味が通らない。", "へ": "「エネルギーへ消費できる」は非文。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生産", "is_correct": true, "explanation": "物を作り出すこと。消費の反対。"}, {"text": "利用", "is_correct": false, "explanation": "使うことで、むしろ近い意味。"}, {"text": "販売", "is_correct": false, "explanation": "売ることで反対の関係ではない。"}, {"text": "保存", "is_correct": false, "explanation": "とっておくことで、正式な対義語ではない。"}], "correct_answer": "生産", "explanations": {"生産": "物を作り出すこと。消費の反対。", "利用": "使うことで、むしろ近い意味。", "販売": "売ることで反対の関係ではない。", "保存": "とっておくことで、正式な対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38989, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嘗て", "is_correct": true, "explanation": "正解。「かつて」。"}, {"text": "勝手", "is_correct": false, "explanation": "「かって」。二番目のモーラ「つ」が促音「っ」に変わる。"}, {"text": "鰹", "is_correct": false, "explanation": "「かつお」。最後のモーラ「て」が「お」に変わる。"}, {"text": "鬘", "is_correct": false, "explanation": "「かつら」。最後のモーラ「て」が「ら」に変わる。"}, {"text": "担ぐ", "is_correct": false, "explanation": "「かつぐ」。最後のモーラ「て」が「ぐ」に変わる。"}], "explanations": {"嘗て": "正解。「かつて」。", "勝手": "「かって」。二番目のモーラ「つ」が促音「っ」に変わる。", "鰹": "「かつお」。最後のモーラ「て」が「お」に変わる。", "鬘": "「かつら」。最後のモーラ「て」が「ら」に変わる。", "担ぐ": "「かつぐ」。最後のモーラ「て」が「ぐ」に変わる。"}, "sentence_index": null, "correct_answer": "嘗て"}, "level_3": {"options": [{"text": "かつて", "is_correct": true, "explanation": "過去を表し「安定していた」と合う。"}, {"text": "いずれ", "is_correct": false, "explanation": "アスペクト：未来を表し、過去形「していた」と合わない。"}, {"text": "やがて", "is_correct": false, "explanation": "アスペクト：これからを表し、過去の状態と合わない。"}, {"text": "いよいよ", "is_correct": false, "explanation": "意味：事態が近づく意で、過去の状態を述べる文に合わない。"}], "explanations": {"かつて": "過去を表し「安定していた」と合う。", "いずれ": "アスペクト：未来を表し、過去形「していた」と合わない。", "やがて": "アスペクト：これからを表し、過去の状態と合わない。", "いよいよ": "意味：事態が近づく意で、過去の状態を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "かつて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ここはかつて小さな村になる。", "explanation": "活用・時制の誤り：「かつて」は過去なので「だった」。"}, {"text": "ここはかつて小さな村だろう。", "explanation": "時制の誤り：過去を表す「かつて」に現在の推量「だろう」は合わない（「だったろう」）。"}, {"text": "ここは小さなかつて村だった。", "explanation": "語順の誤り：副詞が名詞の修飾を割っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
