INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38989, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嘗て", "is_correct": true, "explanation": "正解。「かつて」。"}, {"text": "勝って", "is_correct": false, "explanation": "「かって」。二番目のモーラ「つ」が促音「っ」に変わる。"}, {"text": "活字", "is_correct": false, "explanation": "「かつじ」。最後のモーラ「て」が「じ」に変わる。"}, {"text": "片手", "is_correct": false, "explanation": "「かたて」。二番目のモーラ「つ」が「た」に変わる。"}, {"text": "果て", "is_correct": false, "explanation": "「はて」。「かつ」が「は」に変わる。"}], "explanations": {"嘗て": "正解。「かつて」。", "勝って": "「かって」。二番目のモーラ「つ」が促音「っ」に変わる。", "活字": "「かつじ」。最後のモーラ「て」が「じ」に変わる。", "片手": "「かたて」。二番目のモーラ「つ」が「た」に変わる。", "果て": "「はて」。「かつ」が「は」に変わる。"}, "sentence_index": null, "correct_answer": "嘗て"}, "level_3": {"options": [{"text": "かつて", "is_correct": true, "explanation": "以前の時代を表し、過去形「多かった」と合う。"}, {"text": "これから", "is_correct": false, "explanation": "アスペクト：未来を表し、「多かった」と合わない。"}, {"text": "たまに", "is_correct": false, "explanation": "意味：頻度の副詞で、「多かった」と矛盾する。"}, {"text": "今にも", "is_correct": false, "explanation": "アスペクト：差し迫る状態を表し、過去形と合わない。"}], "explanations": {"かつて": "以前の時代を表し、過去形「多かった」と合う。", "これから": "アスペクト：未来を表し、「多かった」と合わない。", "たまに": "意味：頻度の副詞で、「多かった」と矛盾する。", "今にも": "アスペクト：差し迫る状態を表し、過去形と合わない。"}, "sentence_index": 6, "correct_answer": "かつて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "かつて住んでいる家を明日訪ねる。", "explanation": "時制の誤り：「かつて」と現在の「住んでいる」が合わない。"}, {"text": "かつて住む家を訪ねた。", "explanation": "時制の誤り：「かつて」は過去なので「住んでいた」。"}, {"text": "かつて住んでいた家を、かつて訪ねるつもりだ。", "explanation": "意味の誤り：未来の予定に「かつて」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
