INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37687, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "際", "is_correct": true, "explanation": "正解。「さい」。"}, {"text": "坂", "is_correct": false, "explanation": "「さか」。二番目のモーラ「い」が「か」に変わる。"}, {"text": "酒", "is_correct": false, "explanation": "「さけ」。二番目のモーラ「い」が「け」に変わる。"}, {"text": "猿", "is_correct": false, "explanation": "「さる」。二番目のモーラ「い」が「る」に変わる。"}, {"text": "貝", "is_correct": false, "explanation": "「かい」。最初のモーラ「さ」が「か」に変わる。"}, {"text": "鯛", "is_correct": false, "explanation": "「たい」。最初のモーラ「さ」が「た」に変わる。"}], "explanations": {"際": "正解。「さい」。", "坂": "「さか」。二番目のモーラ「い」が「か」に変わる。", "酒": "「さけ」。二番目のモーラ「い」が「け」に変わる。", "猿": "「さる」。二番目のモーラ「い」が「る」に変わる。", "貝": "「かい」。最初のモーラ「さ」が「か」に変わる。", "鯛": "「たい」。最初のモーラ「さ」が「た」に変わる。"}, "sentence_index": null, "correct_answer": "際"}, "level_3": {"options": [{"text": "際", "is_correct": true, "explanation": "「決める際」で、決めるときの意。"}, {"text": "後", "is_correct": false, "explanation": "意味：決めた後なら「決めた後」が必要で、時制が合わない。"}, {"text": "はず", "is_correct": false, "explanation": "文法：「決めるはず、…」は文がつながらない。"}, {"text": "もの", "is_correct": false, "explanation": "意味：「決めるもの、…」は時を表さず文が成り立たない。"}], "explanations": {"際": "「決める際」で、決めるときの意。", "後": "意味：決めた後なら「決めた後」が必要で、時制が合わない。", "はず": "文法：「決めるはず、…」は文がつながらない。", "もの": "意味：「決めるもの、…」は時を表さず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "際"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震の際を机の下に入る。", "explanation": "助詞の誤り：時を表す「際」には「は／に」が付く。"}, {"text": "地震した際は机の下に入る。", "explanation": "接続の誤り：「地震」は名詞なので「地震の際」。"}, {"text": "地震の際で机の下に入る。", "explanation": "助詞の誤り：「際で」とはいわず「際は／際に」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
