INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37687, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "際", "is_correct": true, "explanation": "正解。「さい」。"}, {"text": "灰", "is_correct": false, "explanation": "「はい」。最初のモーラ「さ」が「は」に変わる。"}, {"text": "舞", "is_correct": false, "explanation": "「まい」。最初のモーラ「さ」が「ま」に変わる。"}, {"text": "鞘", "is_correct": false, "explanation": "「さや」。二番目のモーラ「い」が「や」に変わる。"}, {"text": "皿", "is_correct": false, "explanation": "「さら」。二番目のモーラ「い」が「ら」に変わる。"}], "explanations": {"際": "正解。「さい」。", "灰": "「はい」。最初のモーラ「さ」が「は」に変わる。", "舞": "「まい」。最初のモーラ「さ」が「ま」に変わる。", "鞘": "「さや」。二番目のモーラ「い」が「や」に変わる。", "皿": "「さら」。二番目のモーラ「い」が「ら」に変わる。"}, "sentence_index": null, "correct_answer": "際"}, "level_3": {"options": [{"text": "際", "is_correct": true, "explanation": "「出かける際」で、出かけるときの意。"}, {"text": "ほう", "is_correct": false, "explanation": "意味：「出かけるほうには」は意味が通らない。"}, {"text": "はず", "is_correct": false, "explanation": "連語：「出かけるはずには」は不自然。"}, {"text": "こと", "is_correct": false, "explanation": "意味：「出かけることには」は時を表さない。"}], "explanations": {"際": "「出かける際」で、出かけるときの意。", "ほう": "意味：「出かけるほうには」は意味が通らない。", "はず": "連語：「出かけるはずには」は不自然。", "こと": "意味：「出かけることには」は時を表さない。"}, "sentence_index": 6, "correct_answer": "際"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の際を注意を先生が話した。", "explanation": "助詞の混同：「際の注意」が正しい。"}, {"text": "試合が際の注意を先生が話した。", "explanation": "接続の誤り：名詞は「の」で「際」につなぐ。"}, {"text": "試合の際だ注意を先生が話した。", "explanation": "接続の誤り：名詞を修飾するときは「際の」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = 