INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38727, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栄養", "is_correct": true, "explanation": "正解。「えいよう」。"}, {"text": "栄光", "is_correct": false, "explanation": "「えいこう」。三番目のモーラ「よ」が「こ」に変わる。"}, {"text": "映像", "is_correct": false, "explanation": "「えいぞう」。三番目のモーラ「よ」が「ぞ」に変わる。"}, {"text": "内容", "is_correct": false, "explanation": "「ないよう」。最初のモーラ「え」が「な」に変わる。"}, {"text": "採用", "is_correct": false, "explanation": "「さいよう」。最初のモーラ「え」が「さ」に変わる。"}], "explanations": {"栄養": "正解。「えいよう」。", "栄光": "「えいこう」。三番目のモーラ「よ」が「こ」に変わる。", "映像": "「えいぞう」。三番目のモーラ「よ」が「ぞ」に変わる。", "内容": "「ないよう」。最初のモーラ「え」が「な」に変わる。", "採用": "「さいよう」。最初のモーラ「え」が「さ」に変わる。"}, "sentence_index": null, "correct_answer": "栄養"}, "level_3": {"options": [{"text": "栄養", "is_correct": true, "explanation": "体に必要な成分で、生体利用率と合う。"}, {"text": "香り", "is_correct": false, "explanation": "意味：香りの生体利用率とはいわない。"}, {"text": "値段", "is_correct": false, "explanation": "意味：細胞壁に阻まれた値段は意味が通らない。"}, {"text": "味", "is_correct": false, "explanation": "連語：「味の生体利用率」は結びつかない。"}], "explanations": {"栄養": "体に必要な成分で、生体利用率と合う。", "香り": "意味：香りの生体利用率とはいわない。", "値段": "意味：細胞壁に阻まれた値段は意味が通らない。", "味": "連語：「味の生体利用率」は結びつかない。"}, "sentence_index": 0, "correct_answer": "栄養"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "栄養をある物を食べなさい。", "explanation": "助詞の誤り：「ある」の主語は「の／が」。"}, {"text": "栄養する物を食べなさい。", "explanation": "品詞の誤り：「栄養」は「する」動詞にならない。"}, {"text": "栄養なある物を食べなさい。", "explanation": "接続の誤り：名詞なので「栄養のある」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
